import {
  Button as AriaButton,
  Disclosure as AriaDisclosure,
  DisclosureGroup as AriaDisclosureGroup,
  DisclosurePanel as AriaDisclosurePanel,
} from 'react-aria-components'
import type {
  ButtonProps as AriaButtonProps,
  DisclosureGroupProps as AriaDisclosureGroupProps,
  DisclosurePanelProps as AriaDisclosurePanelProps,
  DisclosureProps as AriaDisclosureProps,
} from 'react-aria-components'

/**
 * The sheet has no accordion in it — the second component here with nothing to copy, after the
 * date picker. So it follows the sheet's *language* rather than its markup: square, mono, the
 * hairline vocabulary of its dividers, and no fill of its own beyond the panel it sits on.
 */

/** A hairline-separated list, which is what the sheet's `.ds-div-hair` draws between rows. */
/** The set is the stack; every line in it belongs to an item. */
const ROOT = 'flex flex-col'

/**
 * One row, and the one element that owns its own state.
 *
 * `data-expanded` is here, not on the header button, so everything the state changes is published
 * from here as custom properties and merely *read* further in — the same arrangement as `Select`
 * and the date pickers, and for the same reason: a rule reaching a child through a group variant
 * ties on specificity with the child's own and loses on source order.
 *
 * The open row announces itself three ways, and none of them is a rule down its edge: the label
 * goes from 55% to full strength, the caret turns, and the row takes the sheet's `.ds-panel`
 * surface. The accent is spent on the caret alone.
 */
const ITEM = [
  'relative flex flex-col',
  // The open row is a panel, and a panel has a corner. A closed row's background is transparent, so
  // the radius is invisible until there is something for it to shape.
  'border-b border-border rounded-md',
  '[--accordion-caret-rotate:0deg]',
  '[--accordion-ink:color-mix(in_oklch,var(--color-foreground)_55%,transparent)]',
  '[--accordion-caret-ink:color-mix(in_oklch,var(--color-foreground)_45%,transparent)]',
  '[--accordion-row-bg:transparent]',
  'data-[expanded]:[--accordion-caret-rotate:180deg]',
  'data-[expanded]:[--accordion-caret-ink:var(--color-primary)]',
  'data-[expanded]:[--accordion-ink:var(--color-foreground)]',
  // The sheet's `.ds-panel`, put on the whole item rather than on the body alone: the open row is
  // one block, heading included, not a heading with a tinted paragraph under it.
  'data-[expanded]:[--accordion-row-bg:var(--color-card)]',
  '[background:var(--accordion-row-bg)]',
  'transition-colors duration-(--duration-base) ease-pulse',
].join(' ')

/**
 * The whole header row is the button, which is what makes an accordion usable with a mouse: a
 * target the width of the row rather than the width of the word.
 *
 * The label is the sheet's **row legend** — 12px, uppercase, letterspaced mono — which is how the
 * sheet labels everything from a field to a table row. A sentence-case 13px heading here would
 * read as a different system.
 */
const HEADER = [
  'flex w-full items-center justify-between gap-4 ps-5 pe-4 py-3.5 text-start',
  'text-[12px] uppercase tracking-[0.06em] [color:var(--accordion-ink)]',
  'cursor-pointer select-none',
  'transition-colors duration-(--duration-fast) ease-pulse',
  'data-[hovered]:bg-foreground/5 data-[hovered]:text-foreground',
  'data-[pressed]:bg-foreground/10',
  'data-[focus-visible]:outline-1 data-[focus-visible]:outline-ring',
  // Inset, because an outset ring on a row that reaches the panel's edges would be clipped by
  // whatever the accordion sits in.
  'data-[focus-visible]:-outline-offset-2',
  'data-[disabled]:cursor-not-allowed data-[disabled]:opacity-35',
].join(' ')

/** In the header's own colour, so it dims and brightens with the label beside it — except when
 * open, where the accent is the one thing that says so at a glance. */
const CARET = [
  'h-2 w-3 shrink-0 rotate-(--accordion-caret-rotate)',
  '[color:var(--accordion-caret-ink)]',
  'motion-safe:transition-[rotate,color] motion-safe:duration-(--duration-base) ease-pulse',
].join(' ')

/**
 * The body. It carries no surface of its own — the item does, so that the open row reads as one
 * block with its heading rather than as a heading with a tinted paragraph under it.
 *
 * The padding is guarded on the panel *not* being hidden, and that guard is doing real work.
 * React Aria hides a closed panel with `hidden="until-found"`, which the browser implements as
 * `content-visibility: hidden` — that skips the content but keeps the element's own box, so
 * padding left on a collapsed panel is dead space under every closed row. Tailwind's preflight
 * deliberately leaves `[hidden="until-found"]` out of its `display: none` rule, so there is
 * nothing else to remove it. The panel has no `data-expanded` to key off; `hidden` is the
 * attribute that is actually there.
 */
const PANEL = [
  'ps-5 pe-4 pb-4 pt-1 text-[13px] leading-[1.6] text-foreground/70',
  '[&[hidden]]:p-0',
  'outline-none',
].join(' ')

const Caret = (
  <svg viewBox="0 0 10 6" fill="none" aria-hidden="true" className={CARET}>
    <path
      d="M1 1L5 5L9 1"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
)

export interface AccordionProps extends Omit<
  AriaDisclosureGroupProps,
  'isDisabled' | 'children' | 'className'
> {
  /** React 19 passes `ref` as an ordinary prop, so no `forwardRef` wrapper. */
  ref?: React.Ref<HTMLDivElement>
  /** Disables every disclosure in the set. This is a React Aria prop — there is no `disabled`. */
  isDisabled?: AriaDisclosureGroupProps['isDisabled']
  /**
   * Which items are open. An accordion shows one at a time unless this is set, which is the
   * difference between an accordion and a stack of independent disclosures.
   */
  allowsMultipleExpanded?: AriaDisclosureGroupProps['allowsMultipleExpanded']
  expandedKeys?: AriaDisclosureGroupProps['expandedKeys']
  defaultExpandedKeys?: AriaDisclosureGroupProps['defaultExpandedKeys']
  onExpandedChange?: AriaDisclosureGroupProps['onExpandedChange']
  className?: string
  /** `Accordion.Item`s. */
  children?: React.ReactNode
}

export interface AccordionItemProps extends Omit<
  AriaDisclosureProps,
  'isDisabled' | 'children' | 'className'
> {
  /** Identifies the item to the set, and is what `expandedKeys` speaks in. */
  id?: AriaDisclosureProps['id']
  /** Disables this one item. */
  isDisabled?: AriaDisclosureProps['isDisabled']
  isExpanded?: AriaDisclosureProps['isExpanded']
  defaultExpanded?: AriaDisclosureProps['defaultExpanded']
  onExpandedChange?: AriaDisclosureProps['onExpandedChange']
  className?: string
  /** An `Accordion.Header`, then an `Accordion.Panel`. */
  children?: React.ReactNode
}

export interface AccordionHeaderProps extends Omit<
  AriaButtonProps,
  'children' | 'className' | 'slot'
> {
  className?: string
  /** The row's label. */
  children?: React.ReactNode
  /**
   * Replaces the caret. An accordion header always shows something that says whether it is open,
   * so this is only for changing *what* — a plus, a dot, a count.
   */
  indicator?: React.ReactNode
}

export interface AccordionPanelProps extends Omit<
  AriaDisclosurePanelProps,
  'children' | 'className'
> {
  className?: string
  children?: React.ReactNode
}

/**
 * One row's header. Use it as `Accordion.Header`, inside an `Accordion.Item`. The whole row is the
 * button, so the target is the width of the panel rather than the width of the word.
 *
 * Exported as `AccordionHeader` only so tooling can resolve it; consume the compound form
 * `Accordion.Header`.
 */
export function AccordionHeader({
  className,
  children,
  indicator,
  ...props
}: AccordionHeaderProps) {
  return (
    <AriaButton
      slot="trigger"
      className={[HEADER, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
      {indicator ?? Caret}
    </AriaButton>
  )
}

/**
 * The content behind a header. Use it as `Accordion.Panel`. While the item is closed React Aria
 * leaves the panel in the document, hidden with `hidden="until-found"` — out of sight and out of
 * the accessibility tree, but still there, which is what lets the browser's find-in-page open the
 * right one. Assert on its visibility, not on its absence.
 *
 * Exported as `AccordionPanel` only so tooling can resolve it; consume the compound form
 * `Accordion.Panel`.
 */
export function AccordionPanel({
  className,
  children,
  ...props
}: AccordionPanelProps) {
  return (
    <AriaDisclosurePanel
      className={[PANEL, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaDisclosurePanel>
  )
}

/**
 * One disclosure in the set. Use it as `Accordion.Item`; its `id` is what the set's `expandedKeys`
 * speaks in.
 *
 * Exported as `AccordionItem` only so tooling can resolve it; consume the compound form
 * `Accordion.Item`.
 */
export function AccordionItem({
  className,
  children,
  ...props
}: AccordionItemProps) {
  return (
    <AriaDisclosure
      className={[ITEM, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaDisclosure>
  )
}

/**
 * Styled element. Not exported — `Accordion` below is the public symbol, and docgen reads the
 * JSDoc from the *exported* declaration, not this one.
 */
function AccordionRoot({ ref, className, children, ...props }: AccordionProps) {
  return (
    <AriaDisclosureGroup
      data-slot="accordion"
      ref={ref}
      className={[ROOT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaDisclosureGroup>
  )
}

/**
 * A set of disclosures that takes turns — the sheet has no accordion in it, so this follows its
 * language rather than its markup: square, mono, and the hairline vocabulary of its dividers.
 *
 * ```tsx
 * <Accordion defaultExpandedKeys={['checks']}>
 *   <Accordion.Item id="checks">
 *     <Accordion.Header>Checks</Accordion.Header>
 *     <Accordion.Panel>Three checks are failing.</Accordion.Panel>
 *   </Accordion.Item>
 *   <Accordion.Item id="history">
 *     <Accordion.Header>History</Accordion.Header>
 *     <Accordion.Panel>No incidents in 24 hours.</Accordion.Panel>
 *   </Accordion.Item>
 * </Accordion>
 * ```
 *
 * **The set, not the item, decides how many may be open.** By default opening one closes the
 * rest, which is the difference between an accordion and a stack of independent disclosures;
 * `allowsMultipleExpanded` is the other behaviour, and it is worth asking for deliberately rather
 * than by writing a `Disclosure` per row and calling it an accordion.
 *
 * `expandedKeys` and `onExpandedChange` speak in the items' `id`s. Uncontrolled use takes
 * `defaultExpandedKeys`; controlling the set means passing `expandedKeys` instead, and the
 * component will not change it for you.
 */
export const Accordion = Object.assign(AccordionRoot, {
  Item: AccordionItem,
  Header: AccordionHeader,
  Panel: AccordionPanel,
})

import { useState } from 'react'
import { Button as AriaButton } from 'react-aria-components'

import { Modal } from '../Modal/Modal'

/**
 * Who something belongs to — a monitor's owner, an alert's assignee — as a picture or as initials.
 *
 * ```tsx
 * <Avatar alt="Ada Lovelace" src="/ada.png" />
 * <Avatar alt="Ada Lovelace" />              // initials, when there is no picture
 * <Avatar alt="fra1" color="primary" />      // a machine's name works the same way
 * <Avatar alt="Ada Lovelace" src="/ada.png" isPreviewable />
 * ```
 *
 * **This is the fourth component here with nothing in the sheet to copy** — after the date picker, the
 * accordion and the toast. `pulse-replica/` has no avatar, no user chip and nothing person-shaped at all,
 * so every decision below comes from the system's own language rather than from a source file:
 *
 * - **Square, like everything else.** The sheet squares off its buttons and inputs and makes exactly two
 *   exceptions — the checkbox's 2px and the radio's circle. A round avatar would be a third, so it is
 *   `rounded-none`. This is the one place a designer would expect a circle, which is why it is worth
 *   saying out loud rather than leaving to look like an oversight.
 * - **A fill carrying `ink`**, like every other filled control here. The five colours are `Button`'s, so an
 *   avatar cannot drift away from the palette it sits beside.
 * - **Mono, uppercase, letterspaced initials** — the same face every other label in this system wears.
 *
 * **Initials, not an icon.** The fallback is derived from `alt`: the first letter of the first and last
 * words, or the first two letters of a single word — so "Ada Lovelace" is `AL` and "fra1" is `FR`. A
 * generic silhouette would say "somebody" and this is a monitoring system, where *which* somebody is the
 * whole content of the cell.
 *
 * **A broken image falls back to initials rather than to nothing.** That is the state a real dashboard
 * spends most of its life in — an avatar URL that 404s, a service without a picture — and it is checked in
 * the stories with a source that cannot load.
 *
 * **`isPreviewable` changes what the element is, which is why it is opt-in.** Off, this is a `<span>` with
 * `role="img"` — a picture, correctly skipped by the tab order. On, it is a **button** that opens the
 * avatar large in a modal, because a picture that responds to a click has to be reachable by keyboard and
 * announced as something you can press. An avatar in a list or a table cell is decoration, and turning
 * every one of them into a tab stop would be the wrong default.
 */
export interface AvatarProps {
  /** The image. Omit it, or let it fail, and the initials are used. */
  src?: string
  /**
   * The person or thing this stands for. Required, and it is a **name rather than a description** — it
   * becomes the accessible name and the initials, so there is nothing else to give.
   */
  alt: string
  size?: 'sm' | 'md' | 'lg'
  /** `Button`'s palette. `neutral` is the default because most of these are not the interesting one. */
  color?: 'primary' | 'secondary' | 'neutral' | 'success' | 'danger'
  /**
   * Opens the avatar in a modal when it is pressed. The avatar becomes a button, so this changes the
   * element and its place in the tab order — see the note above on why it is off by default.
   */
  isPreviewable?: boolean
  className?: string
}

/** Only `--avatar` is set per colour; the fill and the label both read it, so they cannot disagree. */
const COLORS: Record<NonNullable<AvatarProps['color']>, string> = {
  primary: '[--avatar:var(--color-primary)]',
  secondary: '[--avatar:var(--color-warning)]',
  neutral: '[--avatar:var(--color-secondary)]',
  success: '[--avatar:var(--color-success)]',
  danger: '[--avatar:var(--color-destructive)]',
}

const SIZES: Record<NonNullable<AvatarProps['size']>, string> = {
  sm: 'size-6 text-[10px]',
  md: 'size-8 text-[11px]',
  lg: 'size-10 text-[13px]',
}

/**
 * The face in the modal: much larger than any inline size, because the whole point of opening it is to see
 * the picture. `size-56` is 224px — big enough to read a face, small enough to leave the dialog room for
 * the name beneath it.
 */
const PREVIEW_SIZE = 'size-56 text-[56px]'

/**
 * The first letter of the first and last words, or the first two letters of a single one.
 *
 * A name that is only punctuation or spaces has no letters to take, so it gets `?` rather than an empty
 * box — the one case where the fallback has to invent something rather than derive it.
 */
export function initials(name: string) {
  const words = name
    .trim()
    .split(/\s+/)
    .filter((word) => /\S/.test(word))
  if (words.length === 0) return '?'
  if (words.length === 1) return words[0].slice(0, 2).toUpperCase()
  return (words[0][0] + words.at(-1)![0]).toUpperCase()
}

export function Avatar({
  src,
  alt,
  size = 'md',
  color = 'neutral',
  isPreviewable = false,
  className,
}: AvatarProps) {
  const [failed, setFailed] = useState(false)
  const showImage = Boolean(src) && !failed

  /** The fill, the label and the shape — the same in the row and in the modal, at two different sizes. */
  const box = (dimensions: string, extra?: string) =>
    [
      // `clip`, not `hidden`: the box is not a scroller, and `hidden` would let a script (or a
      // stray focus) move its contents.
      'inline-flex shrink-0 items-center justify-center overflow-clip rounded-md',
      dimensions,
      COLORS[color],
      // `ink` on the fill, which inverts with the theme — black on the luminous dark accents, white on
      // the deep light ones. Hardcoding either is the mistake the token exists to prevent.
      'bg-(--avatar) font-mono tracking-[0.04em] text-ink uppercase',
      extra,
    ]
      .filter(Boolean)
      .join(' ')

  // The picture, or the initials when there is none to show. Rendered in whichever box is asking for it.
  const face = (
    <>
      {showImage ? (
        <img
          data-slot="avatar-image"
          src={src}
          alt=""
          onError={() => setFailed(true)}
          className="size-full object-cover"
        />
      ) : (
        <span data-slot="avatar-initials" aria-hidden="true">
          {initials(alt)}
        </span>
      )}
    </>
  )

  if (!isPreviewable) {
    return (
      <span
        data-slot="avatar"
        // The wrapper carries the name and the image is decorative, so a screen reader hears "Ada Lovelace"
        // once. Giving both an `alt` announces the same thing twice.
        role="img"
        aria-label={alt}
        className={box(SIZES[size], className)}
      >
        {face}
      </span>
    )
  }

  return (
    <Modal>
      {/* React Aria's own `Button`, not this system's: the styled one brings a fill, a size and a padding,
          and this element is an avatar that happens to be pressable. It also has to be a real button for
          `DialogTrigger` to open the modal from the keyboard. */}
      <AriaButton
        data-slot="avatar"
        // The name alone would not say what pressing it does, so the action is in the label. It is also
        // why the initials are `aria-hidden`: the name is announced once, by the button.
        aria-label={`Preview ${alt}`}
        className={box(SIZES[size], `cursor-pointer ${className ?? ''}`)}
      >
        {face}
      </AriaButton>
      <Modal.Content>
        <Modal.Close />
        <Modal.Title>{alt}</Modal.Title>
        <div className="flex justify-center py-2">
          <span
            data-slot="avatar-preview"
            role="img"
            aria-label={alt}
            className={box(PREVIEW_SIZE)}
          >
            {face}
          </span>
        </div>
      </Modal.Content>
    </Modal>
  )
}

import { useId, useRef, useState } from 'react'

import { CHART_TOOLTIP } from '../chartTooltip'

/**
 * A histogram — a row of bars over a dot-grid zone, with one of them allowed to be the current one.
 *
 * ```tsx
 * <BarChart
 *   values={[12, 30, 18, 44, 26, 9]}
 *   labels={['00', '04', '08', '12', '16', '20']}
 *   highlightIndex={3}
 *   label="Requests per four hours"
 * />
 * ```
 *
 * **Copied from `drawBars` in `pulse-replica/js/system.js`**, which draws exactly four things:
 *
 * 1. a **dot-grid zone** across the whole plotting area — `rgba(255,255,255,.15)` dots, radius `1`, on a
 *    `7.7px` pitch. That is a *lighter* texture than the sparkline's `.32`/`0.9`: a bar chart is busy
 *    enough without the background competing with it;
 * 2. a **baseline rule** — a 1px rule at `rgba(255,255,255,.34)`, which is what makes the bars sit on
 *    something instead of floating;
 * 3. the **bars**, each `--c-bar` grey, except the one the caller flags, which is drawn in the accent;
 * 4. the **axis row** below, labels absolutely positioned under the bar they name — the replica's
 *    `.dash-axis`, a 24px relative row with each label placed by percentage.
 *
 * **`highlightIndex` is the replica's `b[3]` flag**, and it is the reason this is a monitoring chart rather
 * than a plotting library: the interesting bar is the one the page is about — the current hour, the
 * breached window, the monitor you clicked — and a colour that says which one costs nothing.
 *
 * **Grey rather than accent for the rest, deliberately.** `.ds-tag` and the segmented control spend the
 * accent on the thing that is *chosen*; a histogram is the same idea at chart scale. A chart in which
 * everything is teal has stopped saying which bar matters.
 *
 * **The hover readout is the replica's `place()`.** `dashboard.html` keeps a `.dash-tip--chart` panel
 * (`#pc-tip`) and `system.js` positions it on `pointermove` with a hit rule rather than a per-bar event: a
 * bar whose x-range contains the pointer, with 2 units of slack, wins outright; otherwise the nearest bar
 * within 14 units is used; otherwise nothing happens. That tolerance is what makes the readout feel attached
 * to the chart rather than to a rectangle — a pointer just past a bar's edge still reads it.
 *
 * **It is `aria-hidden`, deliberately.** A readout that exists only under a pointer is not available to a
 * keyboard, so announcing it would claim an affordance the component cannot keep. The values belong in a
 * `Table` beside the chart — the boundary `Sparkline` and `FlatLine` record too.
 * **The drawing is a picture; the numbers belong beside it.** The `<svg>` is `role="img"` with one
 * `label`, so a screen reader hears "Requests per four hours" and not the series — a chart cannot be read
 * out through `role="img"` and this component does not pretend otherwise. Where the values are the point,
 * render them as a table next to it; `Table` is already here, and `Sparkline`'s docs record the same
 * boundary.
 */
export interface BarChartProps {
  /** One bar per value, oldest first. */
  values: number[]
  /** One per value, under its bar. A bar with no label simply gets none. */
  labels?: string[]
  /** The bar the page is about. It is drawn in the accent; every other bar is `--chart-1`. */
  highlightIndex?: number
  /** Width in user units **and** rendered px. A `className` can stretch it. */
  width?: number
  /** Height in user units and rendered px, excluding the axis row. */
  height?: number
  /** What this chart is, for a screen reader. It is the only text the drawing has. */
  label: string
  className?: string
}

/** The gap between bars, in user units — the replica's own spacing is in its data, so this is the one
 *  number not copied from it. */
const GAP = 2

export function BarChart({
  values,
  labels,
  highlightIndex,
  width = 720,
  height = 256,
  label,
  className,
}: BarChartProps) {
  const wrapper = useRef<HTMLDivElement>(null)
  const [hovered, setHovered] = useState<number | null>(null)
  // `<pattern>` ids are document-global: a fixed one means the second chart on a page paints the first
  // one's dots and loses its own zone when that one unmounts.
  const patternId = `bar-chart-dots-${useId()}`
  const max = Math.max(...values, 0)
  // A series of zeroes has no range to scale into. Dividing by one draws nothing rather than a `NaN`
  // rect, which the browser reports as no error at all.
  const span = max || 1
  const slot = values.length ? width / values.length : width
  const barWidth = Math.max(1, slot - GAP)
  const baseline = height

  return (
    <div
      ref={wrapper}
      data-slot="bar-chart"
      className={['relative flex flex-col', className]
        .filter(Boolean)
        .join(' ')}
      onPointerMove={(event) => {
        const box = wrapper.current?.getBoundingClientRect()
        if (!box || !values.length || box.width === 0) return
        // The pointer in the chart's own user units, which is what the bars are laid out in — the replica
        // converts the same way, and without it a stretched chart reads the wrong bar.
        const x = ((event.clientX - box.left) / box.width) * width
        let nearest: number | null = null
        let nearestDistance = Infinity
        for (let index = 0; index < values.length; index += 1) {
          const start = index * slot + GAP / 2
          if (x >= start - 2 && x <= start + barWidth + 2) {
            nearest = index
            nearestDistance = 0
            break
          }
          const distance = Math.abs(x - (start + barWidth / 2))
          if (distance < nearestDistance) {
            nearestDistance = distance
            nearest = index
          }
        }
        setHovered(nearestDistance <= 14 ? nearest : null)
      }}
      onPointerLeave={() => setHovered(null)}
    >
      <svg
        data-slot="bar-chart-svg"
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        preserveAspectRatio="none"
        role="img"
        aria-label={label}
        // **The prop is composed, not replaced.** It was `className="block"` outright, so the
        // `className` this component publishes — and documents as the way to stretch a chart — went
        // nowhere: a chart asked for `w-full` inside a card rendered at its own 720px and ran past the
        // edge of it. Found by putting one in a card on `/create`; `Sparkline` and `FlatLine` already
        // compose theirs, which is what made the difference visible.
        className={['block', className].filter(Boolean).join(' ')}
      >
        <defs>
          <pattern
            id={patternId}
            width="7.7"
            height="7.7"
            patternUnits="userSpaceOnUse"
          >
            <circle cx="1" cy="1" r="1" fill="rgba(255,255,255,0.15)" />
          </pattern>
        </defs>
        <rect
          data-slot="bar-chart-zone"
          x="0"
          y="0"
          width={width}
          height={baseline}
          fill={`url(#${patternId})`}
        />
        <rect
          data-slot="bar-chart-baseline"
          x="0"
          y={baseline - 1}
          width={width}
          height="1"
          fill="rgba(255,255,255,0.34)"
        />
        {values.map((value, index) => {
          const barHeight = (value / span) * (baseline - 2)
          return (
            <rect
              key={index}
              data-slot="bar-chart-bar"
              data-highlighted={index === highlightIndex ? 'true' : undefined}
              x={index * slot + GAP / 2}
              y={baseline - 1 - barHeight}
              width={barWidth}
              height={barHeight}
              fill={
                index === highlightIndex
                  ? 'var(--color-primary)'
                  : 'var(--color-chart-1)'
              }
            />
          )
        })}
      </svg>
      {hovered !== null ? (
        <div
          data-slot="bar-chart-tooltip"
          aria-hidden="true"
          className={`${CHART_TOOLTIP} -top-1`}
          style={{ left: `${((hovered + 0.5) / values.length) * 100}%` }}
        >
          {labels?.[hovered] ? `${labels[hovered]} · ` : ''}
          {values[hovered]}
        </div>
      ) : null}
      {labels ? (
        // The replica's `.dash-axis`: a relative row with each label placed under the centre of its bar,
        // so it stays aligned when the chart stretches.
        <div data-slot="bar-chart-axis" className="relative mt-2 h-4">
          {labels.map((text, index) => (
            <span
              key={index}
              data-slot="bar-chart-axis-label"
              className="absolute top-0 -translate-x-1/2 font-mono text-[11px] tracking-[0.04em] text-foreground/70 uppercase"
              style={{ left: `${((index + 0.5) / labels.length) * 100}%` }}
            >
              {text}
            </span>
          ))}
        </div>
      ) : null}
    </div>
  )
}

import {
  Breadcrumb as AriaBreadcrumb,
  Breadcrumbs as AriaBreadcrumbs,
} from 'react-aria-components'
import type {
  BreadcrumbProps as AriaBreadcrumbProps,
  BreadcrumbsProps as AriaBreadcrumbsProps,
} from 'react-aria-components'

import { Link } from '../Link/Link'

export interface BreadcrumbsProps<T> extends Omit<
  AriaBreadcrumbsProps<T>,
  | 'children'
  | 'className'
  | 'aria-label'
  | 'aria-labelledby'
  | 'onAction'
  | 'isDisabled'
> {
  /** Called with the key of the crumb that was pressed. React Aria's own name for it — a breadcrumb navigates, so this is not `onPress`. */
  onAction?: AriaBreadcrumbsProps<T>['onAction']
  /** Disables every crumb at once. */
  isDisabled?: AriaBreadcrumbsProps<T>['isDisabled']

  /** Names the trail. It goes on the `<nav>` landmark, which is the thing a screen reader lists. */
  label?: string
  className?: string
  children?: AriaBreadcrumbsProps<T>['children']
}

export interface BreadcrumbsItemProps extends Omit<
  AriaBreadcrumbProps,
  'className' | 'children' | 'id'
> {
  className?: string
  /** Where it goes. Leave it off for the page you are on, which is the last one. */
  href?: string
  children?: React.ReactNode
}

/**
 * The trail.
 *
 * **The sheet has no breadcrumb in it** — its `page-nav` is a single horizontal bar — so this is an
 * invention assembled from what the sheet does have: mono caps, a hairline's worth of contrast, and
 * the accent only for the link you can follow.
 *
 * The **slash is drawn by the item**, not by the list, which is the same call `Select.Menu` makes
 * about its popover: a trail is items and separators together, and a separator with nothing to
 * separate is not a thing anyone wants. It is also the one place here where a pseudo-element is
 * right — a slash carries no text, cannot be pressed, and needs no accessible name, unlike the
 * caret that had to become a real button in `Nav`.
 */
const LIST = 'flex flex-wrap items-center gap-0 outline-none'

const ITEM = [
  // `shrink-0` is what makes the trail wrap instead of squashing: without it a flex item happily
  // narrows, mid-word, and a breadcrumb whose steps are clipped is a breadcrumb nobody can read. The
  // `Wraps` story found this — three steps sat on one line in a 176px container with every word
  // squeezed, and `flex-wrap` never had anything to wrap.
  'flex shrink-0 items-center gap-2',
  // No font size: a step is a `caps` link, and the **link owns its own type** — the sheet's
  // `.ds-link-caps` at 14px, with `.ds-link-caps--lg` as the one larger size it has. A size utility
  // here would lose the cascade to the link's anyway, which is the correct outcome rather than a bug.
  'text-foreground/45',
  // The slash between two items, and only between two: `last:` drops it from the page you are on.
  "after:mx-2 after:text-foreground/30 after:content-['/'] last:after:content-none",
  /* **Nothing here hides a disabled crumb, and that is the whole of a bug the Create page found.**
     React Aria marks the *current* breadcrumb `data-disabled` as well as `data-current` — deliberately,
     because the page you are on is not pressable — so a `data-[disabled]:hidden` here hid the last step
     of every trail in this repo, the landing page's included. The `Current` story asserted the
     attribute and the colour and never that the step was *visible*, which is why it passed. */
].join(' ')

/** The page you are on: named, at full strength, and not a link. */
const CURRENT = 'text-foreground'

/**
 * A trail back up the hierarchy. The last item is the page you are on and is not a link.
 *
 * ```tsx
 * <Breadcrumbs label="Breadcrumb">
 *   <Breadcrumbs.Item href="/monitors">Monitors</Breadcrumbs.Item>
 *   <Breadcrumbs.Item href="/monitors/fra1">fra1</Breadcrumbs.Item>
 *   <Breadcrumbs.Item>Frankfurt</Breadcrumbs.Item>
 * </Breadcrumbs>
 * ```
 *
 * Every item but the last takes an `href` and renders a real `Link`, so middle-click and "open in a
 * new tab" work — which is most of what a breadcrumb is for, and what a `<span onClick>` gives up.
 *
 * **It wraps, and nothing collapses.** React Aria's documentation describes dropping the middle of the
 * trail when the container runs out of room, and this component used to say so; measured, this version
 * does nothing of the kind — `useBreadcrumbs` builds `navProps` and no more, and the `Deep` story's six
 * steps all render. So the trail wraps instead, which is why the items are `shrink-0` and the list is
 * `flex-wrap`.
 */
function BreadcrumbsRoot<T>({
  label = 'Breadcrumb',
  className,
  children,
  ...props
}: BreadcrumbsProps<T>) {
  return (
    // **React Aria renders the list and not the landmark.** Its `Breadcrumbs` is an `<ol>` — no
    // `<nav>` around it and no role on the list itself — so the first version of this component was a
    // list of links sitting in no landmark at all, and a screen reader's landmark list offered no way
    // to reach it. A breadcrumb *is* navigation, so the wrapper is this component's job.
    <nav data-slot="breadcrumbs" aria-label={label}>
      <AriaBreadcrumbs
        className={[LIST, className].filter(Boolean).join(' ')}
        {...props}
      >
        {children}
      </AriaBreadcrumbs>
    </nav>
  )
}

/**
 * One step. Use it as `Breadcrumbs.Item` — with an `href` it is a link, without one it is the page
 * you are on.
 *
 * Exported as `BreadcrumbsItem` only so tooling can resolve it; consume the compound form
 * `Breadcrumbs.Item`.
 */
export function BreadcrumbsItem({
  className,
  href,
  children,
  ...props
}: BreadcrumbsItemProps) {
  return (
    <AriaBreadcrumb
      className={[ITEM, className].filter(Boolean).join(' ')}
      {...props}
    >
      {({ isCurrent }) =>
        href === undefined ? (
          // The page you are on: not a link, because there is nowhere to go, and `aria-current`
          // rather than a heading so a screen reader can find the trail's end.
          <span aria-current="page" className={CURRENT}>
            {children}
          </span>
        ) : (
          <Link
            href={href}
            variant="caps"
            aria-current={isCurrent ? 'page' : undefined}
            className={isCurrent ? CURRENT : undefined}
          >
            {children}
          </Link>
        )
      }
    </AriaBreadcrumb>
  )
}

/**
 * The compound export. A plain `function` decorated with `Object.assign` leaves TypeScript unaware of
 * the slots, which is why the root is named apart and only the decorated const is exported.
 */
export const Breadcrumbs = Object.assign(BreadcrumbsRoot, {
  Item: BreadcrumbsItem,
})

import {
  Calendar as AriaCalendar,
  CalendarCell as AriaCalendarCell,
  CalendarStateContext,
} from 'react-aria-components'
import type {
  CalendarCellProps as AriaCalendarCellProps,
  CalendarProps as AriaCalendarProps,
  DateValue,
} from 'react-aria-components'

import { useContext } from 'react'
import type { ReactNode } from 'react'

import {
  DATE_CELL,
  DATE_HEADING,
  DateCalendarChrome,
  useVisibleRangeLabel,
} from '../date'

export interface CalendarProps extends Omit<
  AriaCalendarProps<DateValue>,
  | 'children'
  | 'className'
  | 'value'
  | 'defaultValue'
  | 'onChange'
  | 'isDisabled'
  | 'isReadOnly'
  | 'minValue'
  | 'maxValue'
  | 'visibleDuration'
> {
  /** The chosen date. Controlled. */
  value?: AriaCalendarProps<DateValue>['value']
  /** The date it starts on, for uncontrolled use. */
  defaultValue?: AriaCalendarProps<DateValue>['defaultValue']
  /** Called with the chosen date. */
  onChange?: AriaCalendarProps<DateValue>['onChange']
  /** Disables the whole month. */
  isDisabled?: AriaCalendarProps<DateValue>['isDisabled']
  /** Shows the month without letting a day be chosen. */
  isReadOnly?: AriaCalendarProps<DateValue>['isReadOnly']
  /** The earliest selectable day. */
  minValue?: AriaCalendarProps<DateValue>['minValue']
  /** The latest selectable day. */
  maxValue?: AriaCalendarProps<DateValue>['maxValue']
  /** What `months` becomes at the root — the prop that tells the calendar which days are in view. */
  visibleDuration?: AriaCalendarProps<DateValue>['visibleDuration']

  /** How many months are on screen at once. */
  months?: number
  className?: string
  /** Overrides the whole grid. Rarely wanted — the chrome below is the sheet's own. */
  children?: ReactNode
}

export interface CalendarHeadingProps {
  className?: string
  children?: ReactNode
}

export interface CalendarCellProps extends Omit<
  AriaCalendarCellProps,
  'className'
> {
  className?: string
}

/**
 * The month's name. Use it as `Calendar.Heading` when you are building your own grid.
 *
 * **It is `aria-hidden`, because React Aria renders its own heading for assistive tech just above
 * it** — and that one is correct for any number of visible months. This is the copy the eye reads;
 * React Aria's would otherwise be the one the eye reads instead, captioning a two-month calendar
 * with only its first month.
 *
 * Exported as `CalendarHeading` only so tooling can resolve it; consume the compound form
 * `Calendar.Heading`.
 */
export function CalendarHeading({ className, children }: CalendarHeadingProps) {
  const state = useContext(CalendarStateContext)
  const label = useVisibleRangeLabel(state?.visibleRange ?? null)

  return (
    <h2
      data-slot="heading"
      aria-hidden="true"
      className={[DATE_HEADING, className].filter(Boolean).join(' ')}
    >
      {children ?? label}
    </h2>
  )
}

/**
 * One day. Use it as `Calendar.Cell` when you are building your own grid.
 *
 * Exported as `CalendarCell` only so tooling can resolve it; consume the compound form
 * `Calendar.Cell`.
 */
export function CalendarCell({ className, ...props }: CalendarCellProps) {
  return (
    <AriaCalendarCell
      data-slot="cell"
      className={[DATE_CELL, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * A month on the page, with no field and no popover around it.
 *
 * ```tsx
 * <Calendar aria-label="Date" />
 * <Calendar aria-label="Range" months={2} />
 * ```
 *
 * **`DatePicker` is this inside a popover.** The picker draws the same grid through the same
 * `date.tsx` chrome, so a month looks identical whether it was opened from a field or is simply
 * sitting on the page — the drift that file exists to prevent. Reach for this when the date is the
 * point of the screen (a dashboard's range filter, an availability view) and for `DatePicker` when
 * the date is one value among several in a form.
 *
 * **Nothing is selected until a day is clicked**, and the keyboard is the calendar's own: the arrows
 * walk days, Page Up and Down change month, Home and End reach the ends of a week, and Enter picks.
 * That is a lot of behaviour for something that looks like a picture of a month.
 *
 * `months={2}` shows a range, and the heading spans both — which is the one thing a two-month grid
 * gets wrong by default, because React Aria's own heading can only caption the first.
 */
function CalendarRoot({
  months = 1,
  className,
  children,
  ...props
}: CalendarProps) {
  return (
    <AriaCalendar className={className} {...props} visibleDuration={{ months }}>
      {children ?? (
        <DateCalendarChrome
          Heading={CalendarHeading}
          Cell={CalendarCell}
          months={months}
        />
      )}
    </AriaCalendar>
  )
}

/**
 * The compound export. A plain `function` decorated with `Object.assign` leaves TypeScript unaware of
 * the slots, which is why the root is named apart and only the decorated const is exported.
 */
export const Calendar = Object.assign(CalendarRoot, {
  Heading: CalendarHeading,
  Cell: CalendarCell,
})

import type { HTMLAttributes, ReactNode } from 'react'
import { Heading as AriaHeading } from 'react-aria-components'
import type { HeadingProps as AriaHeadingProps } from 'react-aria-components'

/**
 * The sheet's panel, with a structure on it. A card is one thing on the page — a chart, a
 * monitor's detail, a run of results — and it borrows the surface Modal, Tooltip and Toast
 * already share: `bg-card`, a boundary in `--border-strong`, square, and no shadow.
 *
 * The divider under the header and above the footer is `--border`, the row rule Table draws
 * between its rows. That is the sheet's habit everywhere: a panel's own edge is the quieter
 * hairline and the rules inside it are the louder one.
 */
const CARD = 'flex flex-col border border-border-strong bg-card rounded-xl'

/**
 * A grid rather than a flex row, so the `Action` can sit in a second column beside both the title
 * and the description without needing a wrapper. It only becomes two columns when there is an
 * action to put in the second one — `has-data-[slot=card-action]` is that condition, read off the
 * element instead of a prop, so a header with nothing on the right has nothing on the right.
 */
const CARD_HEADER = [
  'grid auto-rows-min items-start gap-1',
  'border-b border-border p-4',
  'has-data-[slot=card-action]:grid-cols-[1fr_auto]',
].join(' ')

const CARD_TITLE =
  'text-[14px] leading-[1.3] font-semibold tracking-[-0.01em] text-foreground'

const CARD_DESCRIPTION = 'text-[12px] leading-[1.5] text-foreground/70'

const CARD_ACTION =
  'col-start-2 row-span-2 row-start-1 self-start justify-self-end'

const CARD_CONTENT = 'p-4 text-[13px] leading-[1.55] text-foreground/70'

const CARD_FOOTER = 'flex items-center gap-2 border-t border-border p-4'

export interface CardProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  'children' | 'className'
> {
  className?: string
  /** A `Card.Header`, a `Card.Content`, a `Card.Footer` — in that order, and none of them required. */
  children?: ReactNode
}

export interface CardHeaderProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  'children' | 'className'
> {
  className?: string
  /**
   * A `Card.Title`, a `Card.Description`, and optionally a `Card.Action`. React Aria renders the
   * title as a real heading, so the page's outline says what each card is.
   */
  children?: ReactNode
}

export interface CardTitleProps extends Omit<
  AriaHeadingProps,
  'children' | 'className'
> {
  className?: string
  children?: ReactNode
  /**
   * The heading level. Defaults to 3, or to one deeper than an enclosing React Aria `Section`.
   */
  level?: AriaHeadingProps['level']
}

export interface CardDescriptionProps extends Omit<
  HTMLAttributes<HTMLParagraphElement>,
  'children' | 'className'
> {
  className?: string
  children?: ReactNode
}

export interface CardActionProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  'children' | 'className'
> {
  className?: string
  /** One control — a `Button`, a `Menu` trigger. More than one belongs in the footer. */
  children?: ReactNode
}

export interface CardContentProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  'children' | 'className'
> {
  className?: string
  children?: ReactNode
}

export interface CardFooterProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  'children' | 'className'
> {
  className?: string
  children?: ReactNode
}

/**
 * The top of a card: what it is about, and one control beside that if there is one.
 *
 * Exported as `CardHeader` only so tooling can resolve it; consume the compound form
 * `Card.Header`.
 */
export function CardHeader({ className, children, ...props }: CardHeaderProps) {
  return (
    <div
      data-slot="card-header"
      className={[CARD_HEADER, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </div>
  )
}

/**
 * What the card is about.
 *
 * **A real heading, not a styled `div`.** React Aria renders it as an `h3` by default, so a page
 * of cards has an outline a screen reader can walk; the `level` is a published prop because a
 * card nested inside a section usually wants a different one.
 *
 * Exported as `CardTitle` only so tooling can resolve it; consume the compound form
 * `Card.Title`.
 */
export function CardTitle({ className, children, ...props }: CardTitleProps) {
  return (
    <AriaHeading
      data-slot="card-title"
      className={[CARD_TITLE, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaHeading>
  )
}

/**
 * The line under the title, for what the card contains rather than what it is.
 *
 * Exported as `CardDescription` only so tooling can resolve it; consume the compound form
 * `Card.Description`.
 */
export function CardDescription({
  className,
  children,
  ...props
}: CardDescriptionProps) {
  return (
    <p
      data-slot="card-description"
      className={[CARD_DESCRIPTION, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </p>
  )
}

/**
 * The right-hand corner of a header. One control, beside the title — a menu trigger, a refresh,
 * a dismiss.
 *
 * Exported as `CardAction` only so tooling can resolve it; consume the compound form
 * `Card.Action`.
 */
export function CardAction({ className, children, ...props }: CardActionProps) {
  return (
    <div
      data-slot="card-action"
      className={[CARD_ACTION, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </div>
  )
}

/**
 * The body — the chart, the table, the text.
 *
 * Exported as `CardContent` only so tooling can resolve it; consume the compound form
 * `Card.Content`.
 */
export function CardContent({
  className,
  children,
  ...props
}: CardContentProps) {
  return (
    <div
      data-slot="card-content"
      className={[CARD_CONTENT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </div>
  )
}

/**
 * The row of actions at the bottom, over its own hairline.
 *
 * Exported as `CardFooter` only so tooling can resolve it; consume the compound form
 * `Card.Footer`.
 */
export function CardFooter({ className, children, ...props }: CardFooterProps) {
  return (
    <div
      data-slot="card-footer"
      className={[CARD_FOOTER, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </div>
  )
}

function CardRoot({ className, children, ...props }: CardProps) {
  return (
    <div
      data-slot="card"
      className={[CARD, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </div>
  )
}

/**
 * One thing on the page, in the sheet's own surface.
 *
 * ```tsx
 * <Card>
 *   <Card.Header>
 *     <Card.Title>Frankfurt</Card.Title>
 *     <Card.Description>fra1 · 42ms</Card.Description>
 *     <Card.Action>
 *       <Menu.Trigger>…</Menu.Trigger>
 *     </Card.Action>
 *   </Card.Header>
 *   <Card.Content>
 *     <Sparkline points={…} />
 *   </Card.Content>
 *   <Card.Footer>
 *     <Button variant="outline">Open</Button>
 *   </Card.Footer>
 * </Card>
 * ```
 *
 * **It is not interactive, and that is the design.** There is no `onPress` and no React Aria
 * primitive under the panels, because a card is a surface rather than a control: a card that
 * does something holds a `Link` or a `Button` that says what the something is. A pressable
 * surface is a control with no name to announce and no target to aim at, and it makes the real
 * control inside it unreachable to anyone who cannot see where it is.
 *
 * **The slots are optional, and a card with only content is a complete card.** Padding lives on
 * the slots rather than on the root, so what the root holds is the surface itself.
 */
export const Card = Object.assign(CardRoot, {
  Header: CardHeader,
  Title: CardTitle,
  Description: CardDescription,
  Action: CardAction,
  Content: CardContent,
  Footer: CardFooter,
})

import {
  Checkbox as AriaCheckbox,
  CheckboxGroup as AriaCheckboxGroup,
  FieldError as AriaFieldError,
  Label as AriaLabel,
  Text as AriaText,
} from 'react-aria-components'
import type {
  CheckboxGroupProps as AriaCheckboxGroupProps,
  CheckboxProps as AriaCheckboxProps,
  FieldErrorProps as AriaFieldErrorProps,
  LabelProps as AriaLabelProps,
  TextProps as AriaTextProps,
} from 'react-aria-components'

import { ERROR, HINT, LABEL } from '../field'

/**
 * The sheet's `.ds-check`. Note the radius: the sheet squares off its buttons and
 * inputs but gives the selection controls the 2px a checkbox is expected to have,
 * so `rounded-none` is deliberately not applied here.
 *
 * Every state is published as a custom property rather than applied to the
 * indicator directly. The indicator is a child, so a rule reaching it must go
 * through a group variant — and group variants sort at the *same* specificity as a
 * plain utility (Tailwind wraps them in `:where(...)`), leaving the outcome to
 * source order. A `group-data-[hovered]:border-foreground` therefore loses to the
 * indicator's own `border-input`, silently. Publishing a property here means
 * the ordinary cascade decides, because both rules land on this one element and
 * `[data-selected][data-hovered]` plainly outranks `[data-hovered]`.
 *
 * The names are `--selection-*` so that `Radio` can publish the same set and its
 * own indicator can read them without knowing which one it is inside.
 */
const CONTROL = [
  'group/selection inline-flex items-center gap-2.5',
  'cursor-pointer select-none',
  'data-[disabled]:cursor-not-allowed data-[disabled]:opacity-35',
  // rest
  '[--selection-border:var(--color-input)]',
  '[--selection-bg:transparent]',
  '[--selection-mark:0]',
  '[--selection-mark-dash:0]',
  '[--selection-scale:0.4]',
  'motion-reduce:[--selection-scale:1]',
  '[--selection-ring:transparent]',
  // hover strengthens the border...
  'data-[hovered]:[--selection-border:var(--color-foreground)]',
  // ...selected fills it, shows the tick and scales the centre...
  'data-[selected]:[--selection-border:var(--color-primary)]',
  'data-[selected]:[--selection-bg:var(--color-primary)]',
  // Written as an exclusion rather than as a plain `data-[selected]`, because an indeterminate
  // checkbox is usually also a selected one and the two rules would tie on specificity: only one
  // of them may match.
  'data-[selected]:not-data-[indeterminate]:[--selection-mark:1]',
  'data-[selected]:[--selection-scale:1]',
  // ...and a checked control inverts on hover, the sheet's own `:hover` pair.
  'data-[selected]:data-[hovered]:[--selection-border:var(--color-foreground)]',
  'data-[selected]:data-[hovered]:[--selection-bg:var(--color-foreground)]',
  // ...and some-of-the-above fills the same way but shows a dash instead of a tick, which is the
  // whole difference between "all of it" and "some of it".
  'data-[indeterminate]:[--selection-border:var(--color-primary)]',
  'data-[indeterminate]:[--selection-bg:var(--color-primary)]',
  'data-[indeterminate]:[--selection-mark-dash:1]',
  'data-[indeterminate]:[--selection-scale:1]',
  // The ring is drawn on the indicator, because the control is a 1x1 invisible
  // input.
  'data-[focus-visible]:[--selection-ring:var(--color-primary)]',
].join(' ')

const BOX = [
  'grid size-[18px] flex-none place-items-center',
  'rounded-[2px] border border-(--selection-border) bg-(--selection-bg)',
  // A transparent outline rather than `outline-none`, so the ring fades in with
  // everything else instead of switching the outline on and off.
  'outline-1 outline-offset-[3px] outline-(--selection-ring)',
  'transition-[background-color,border-color,outline-color] duration-(--duration-fast) ease-pulse',
].join(' ')

/**
 * The tick is always in the DOM and fades in, as the sheet does — no layout shift
 * when it appears, and nothing to mount. It is sized in `rem` rather than `cap`,
 * because the box is a fixed 18px and does not scale with the type.
 */
const MARK = [
  // Both the tick and the dash sit in the box's single grid cell, so swapping one for the other
  // cannot change the box's size.
  'col-start-1 row-start-1',
  // The tick scales in as the box fills — the value the root publishes and that nothing read
  // until now, so the "scales the centre" the comment above describes never happened.
  'size-[11px] text-ink opacity-(--selection-mark) scale-(--selection-scale)',
  'transition-[opacity,scale] duration-(--duration-fast) ease-pulse',
].join(' ')

/** The dash an indeterminate checkbox shows instead of a tick. */
const DASH = [
  'col-start-1 row-start-1',
  'h-0.5 w-[9px] bg-ink opacity-(--selection-mark-dash)',
  'transition-opacity duration-(--duration-fast) ease-pulse',
].join(' ')

/** The sheet's `.ds-check-label`: 13px, foreground at 80%. */
const TEXT = 'text-[13px] text-foreground/80'

/**
 * The sheet's `<fieldset class="stack ds-field">`: legend, controls, then the
 * hint that explains them.
 *
 * `group` is here for `LABEL`'s required marker, which is drawn from the group's
 * own `data-required`. It is safe next to the controls' `group/selection`: that one
 * is named, so the two cannot be confused.
 */
const GROUP = 'group flex flex-col gap-2.5'

const Tick = (
  <svg
    viewBox="0 0 11 9"
    fill="none"
    aria-hidden="true"
    data-slot="mark"
    className={MARK}
  >
    <path
      d="M1.5 4.5L4.2 7.2L9.5 1.5"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
)

export interface CheckboxProps extends Omit<
  AriaCheckboxProps,
  | 'isDisabled'
  | 'isReadOnly'
  | 'isRequired'
  | 'isInvalid'
  | 'isSelected'
  | 'defaultSelected'
  | 'onChange'
  | 'children'
  | 'className'
  | 'ref'
> {
  /** React 19 passes `ref` as an ordinary prop, so no `forwardRef` wrapper. */
  ref?: React.Ref<HTMLLabelElement>
  /** Disables the control. This is a React Aria prop — there is no `disabled`. */
  isDisabled?: AriaCheckboxProps['isDisabled']
  /** Makes the value visible but not changeable. */
  isReadOnly?: AriaCheckboxProps['isReadOnly']
  isRequired?: AriaCheckboxProps['isRequired']
  isInvalid?: AriaCheckboxProps['isInvalid']
  /**
   * The control owns its selection, so these live here rather than on a slot.
   * Outside a `Checkbox.Group` that means `defaultSelected` + `onChange(boolean)`;
   * inside one the group owns it and this is driven by the group's array.
   */
  /**
   * Shows a dash rather than a tick, for a checkbox standing in for a set of which only some are
   * chosen — a table's select-all, usually. It fills like a checked one either way; the mark is
   * what says "some" rather than "all". React Aria renders `data-indeterminate` for it.
   */
  isIndeterminate?: AriaCheckboxProps['isIndeterminate']
  isSelected?: AriaCheckboxProps['isSelected']
  defaultSelected?: AriaCheckboxProps['defaultSelected']
  onChange?: AriaCheckboxProps['onChange']
  /** Identifies this control to its `Checkbox.Group`. */
  value?: AriaCheckboxProps['value']
  className?: string
  /** `Checkbox.Indicator` and `Checkbox.Text`, in that order. */
  children?: React.ReactNode
}

export interface CheckboxGroupProps extends Omit<
  AriaCheckboxGroupProps,
  | 'isDisabled'
  | 'isReadOnly'
  | 'isRequired'
  | 'isInvalid'
  | 'value'
  | 'defaultValue'
  | 'onChange'
  | 'children'
  | 'className'
  | 'ref'
> {
  ref?: React.Ref<HTMLDivElement>
  isDisabled?: AriaCheckboxGroupProps['isDisabled']
  isReadOnly?: AriaCheckboxGroupProps['isReadOnly']
  isRequired?: AriaCheckboxGroupProps['isRequired']
  isInvalid?: AriaCheckboxGroupProps['isInvalid']
  /** The group owns the selection: an array of the selected `value`s. */
  value?: AriaCheckboxGroupProps['value']
  defaultValue?: AriaCheckboxGroupProps['defaultValue']
  onChange?: AriaCheckboxGroupProps['onChange']
  className?: string
  /** `Checkbox.Label`, the checkboxes, then `Checkbox.Hint` and `Checkbox.Error`. */
  children?: React.ReactNode
}

export interface CheckboxIndicatorProps extends React.HTMLAttributes<HTMLSpanElement> {
  className?: string
}

export interface CheckboxTextProps extends React.HTMLAttributes<HTMLSpanElement> {
  children?: React.ReactNode
}

export interface CheckboxLabelProps extends AriaLabelProps {
  children?: React.ReactNode
}

export interface CheckboxHintProps extends AriaTextProps {
  children?: React.ReactNode
}

export interface CheckboxFieldErrorProps extends AriaFieldErrorProps {
  /** The message, or a function of the field's validation result. */
  children?: AriaFieldErrorProps['children']
}

/**
 * The box, with its tick — or its dash, when the checkbox is indeterminate. Use it as
 * `Checkbox.Indicator`, inside a `Checkbox`.
 *
 * Exported as `CheckboxIndicator` only so tooling can resolve it; consume the
 * compound form `Checkbox.Indicator`.
 */
export function CheckboxIndicator({
  className,
  ...props
}: CheckboxIndicatorProps) {
  return (
    <span
      data-slot="indicator"
      aria-hidden="true"
      className={[BOX, className].filter(Boolean).join(' ')}
      {...props}
    >
      {Tick}
      <span data-slot="dash" className={DASH} />
    </span>
  )
}

/**
 * The label of a single checkbox. Use it as `Checkbox.Text`, beside
 * `Checkbox.Indicator`. A bare text child renders too, just without the styling.
 *
 * Exported as `CheckboxText` only so tooling can resolve it; consume the compound
 * form `Checkbox.Text`.
 */
export function CheckboxText({
  className,
  children,
  ...props
}: CheckboxTextProps) {
  return (
    <span
      data-slot="text"
      className={[TEXT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </span>
  )
}

/**
 * The legend for the group. Use it as `Checkbox.Label`, inside `Checkbox.Group`.
 *
 * Exported as `CheckboxLabel` only so tooling can resolve it; consume the compound
 * form `Checkbox.Label`.
 */
export function CheckboxLabel({
  className,
  children,
  ...props
}: CheckboxLabelProps) {
  return (
    <AriaLabel
      className={[LABEL, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaLabel>
  )
}

/**
 * The guidance under the group. Use it as `Checkbox.Hint`. React Aria wires it to
 * the group's `aria-describedby`.
 *
 * Exported as `CheckboxHint` only so tooling can resolve it; consume the compound
 * form `Checkbox.Hint`.
 */
export function CheckboxHint({
  className,
  children,
  ...props
}: CheckboxHintProps) {
  return (
    <AriaText
      slot="description"
      className={[HINT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaText>
  )
}

/**
 * The message shown when the group is `isInvalid`. Use it as
 * `Checkbox.Error`; React Aria renders nothing while the group is valid.
 *
 * Exported as `CheckboxFieldError` only so tooling can resolve it; consume the
 * compound form `Checkbox.Error`.
 */
export function CheckboxFieldError({
  className,
  ...props
}: CheckboxFieldErrorProps) {
  return (
    <AriaFieldError
      className={[ERROR, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * The group. Use it as `Checkbox.Group`. It owns the value, as an array of the
 * selected `value`s.
 *
 * Exported as `CheckboxGroup` only so tooling can resolve it; consume the compound
 * form `Checkbox.Group`.
 */
export function CheckboxGroup({
  ref,
  className,
  children,
  ...props
}: CheckboxGroupProps) {
  return (
    <AriaCheckboxGroup
      ref={ref}
      className={[GROUP, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaCheckboxGroup>
  )
}

/**
 * Styled element. Not exported — `Checkbox` below is the public symbol, and docgen
 * reads the JSDoc from the *exported* declaration, not this one.
 */
function CheckboxControl({
  ref,
  className,
  children,
  ...props
}: CheckboxProps) {
  return (
    <AriaCheckbox
      ref={ref}
      className={[CONTROL, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaCheckbox>
  )
}

/**
 * A checkbox, and the group it can belong to — the sheet's `.ds-check`.
 *
 * ```tsx
 * <Checkbox.Group defaultValue={['slow']}>
 *   <Checkbox.Label>Alert me when</Checkbox.Label>
 *   <Checkbox value="down">
 *     <Checkbox.Indicator />
 *     <Checkbox.Text>Down</Checkbox.Text>
 *   </Checkbox>
 *   <Checkbox.Hint>Applies to every monitor.</Checkbox.Hint>
 *   <Checkbox.Error>Pick at least one.</Checkbox.Error>
 * </Checkbox.Group>
 * ```
 *
 * The slots are explicit, like `Button.Icon` and `Button.Text`:
 * `Checkbox.Indicator` draws the box and its tick, and `Checkbox.Text` the label. A
 * bare text child still renders, it just misses the label styling, so a missing
 * slot degrades rather than disappears.
 *
 * Alone, a `Checkbox` owns its selection: `defaultSelected` with
 * `onChange(boolean)`. Inside a `Checkbox.Group` the group owns it, as an array,
 * and `value` identifies the control to it.
 */
export const Checkbox = Object.assign(CheckboxControl, {
  Group: CheckboxGroup,
  Indicator: CheckboxIndicator,
  Text: CheckboxText,
  Label: CheckboxLabel,
  Hint: CheckboxHint,
  Error: CheckboxFieldError,
})

import {
  ColorField as AriaColorField,
  ColorFieldStateContext,
  FieldError as AriaFieldError,
  Input as AriaInput,
  Label as AriaLabel,
  Text as AriaText,
} from 'react-aria-components'
import type {
  ColorFieldProps as AriaColorFieldProps,
  FieldErrorProps as AriaFieldErrorProps,
  InputProps as AriaInputProps,
  LabelProps as AriaLabelProps,
  TextProps as AriaTextProps,
} from 'react-aria-components'

import { useContext } from 'react'
import type { ReactNode } from 'react'

import { ERROR, FIELD, GROUP, HINT, INPUT, LABEL } from '../field'

export interface ColorFieldProps extends Omit<
  AriaColorFieldProps,
  | 'children'
  | 'className'
  | 'value'
  | 'defaultValue'
  | 'onChange'
  | 'isDisabled'
  | 'isInvalid'
  | 'isRequired'
  | 'isReadOnly'
  | 'channel'
> {
  /** The colour as a `Color` — or a string it can parse. Controlled. */
  value?: AriaColorFieldProps['value']
  /** The colour it starts at, for uncontrolled use. */
  defaultValue?: AriaColorFieldProps['defaultValue']
  /** Called with the parsed colour, or `null` when the text is not one. */
  onChange?: AriaColorFieldProps['onChange']
  /** Disables the field. */
  isDisabled?: AriaColorFieldProps['isDisabled']
  /** Marks the field invalid from the outside, for a server's answer. */
  isInvalid?: AriaColorFieldProps['isInvalid']
  /** Marks it required and draws the label's marker. */
  isRequired?: AriaColorFieldProps['isRequired']
  /** Keeps the value readable and selectable but uneditable — and does not dim it. */
  isReadOnly?: AriaColorFieldProps['isReadOnly']
  /** Edits one channel rather than the whole hex value. */
  channel?: AriaColorFieldProps['channel']

  className?: string
  children?: ReactNode
}

export interface ColorFieldLabelProps extends Omit<
  AriaLabelProps,
  'className'
> {
  className?: string
}

export interface ColorFieldControlProps {
  className?: string
  children?: ReactNode
}

export interface ColorFieldSwatchProps {
  className?: string
}

export interface ColorFieldInputProps extends Omit<
  AriaInputProps,
  'className'
> {
  className?: string
}

export interface ColorFieldHintProps extends Omit<AriaTextProps, 'className'> {
  className?: string
}

export interface ColorFieldErrorProps extends Omit<
  AriaFieldErrorProps,
  'className'
> {
  className?: string
}

/**
 * The legend. Use it as `ColorField.Label`.
 *
 * Exported as `ColorFieldLabel` only so tooling can resolve it; consume the compound form
 * `ColorField.Label`.
 */
export function ColorFieldLabel({ className, ...props }: ColorFieldLabelProps) {
  return (
    <AriaLabel
      className={[LABEL, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * The row the swatch and the input share. Use it as `ColorField.Control`.
 *
 * **`ColorField`'s children are the whole column**, not a row — its own element is the field, exactly as
 * `TextField`'s is, and the legend, the control and the hint are its direct children. The swatch and the
 * input *are* a row, so they need one element between them and the column. Without it the hint renders
 * beside the input.
 *
 * Exported as `ColorFieldControl` only so tooling can resolve it; consume the compound form
 * `ColorField.Control`.
 */
export function ColorFieldControl({
  className,
  children,
}: ColorFieldControlProps) {
  return (
    <div
      data-slot="color-control"
      className={[GROUP, 'items-center gap-2', className]
        .filter(Boolean)
        .join(' ')}
    >
      {children}
    </div>
  )
}

/**
 * The colour the field currently holds, as a square. Use it as `ColorField.Swatch`.
 *
 * **It reads the field's own state** rather than being handed a colour, so it cannot drift from the
 * value in the input — the arrangement `Meter.Fill` and `Nav.Label` use. The state property is
 * **`colorValue`**, not `value`; there is no `value` on a `ColorFieldState`.
 *
 * An empty field paints **nothing**: a black square would claim there was a value, and there is not —
 * the same distinction a progress bar draws between "unknown" and "zero".
 *
 * Exported as `ColorFieldSwatch` only so tooling can resolve it; consume the compound form
 * `ColorField.Swatch`.
 */
export function ColorFieldSwatch({ className }: ColorFieldSwatchProps) {
  const state = useContext(ColorFieldStateContext)
  const color = state?.colorValue?.toString('hex')

  return (
    <span
      data-slot="swatch"
      aria-hidden="true"
      className={['size-6 shrink-0 border border-input', className]
        .filter(Boolean)
        .join(' ')}
      style={color ? { background: color } : undefined}
    />
  )
}

/**
 * The control. Use it as `ColorField.Input`.
 *
 * It keeps the shared `INPUT` — the same height, type and hairline — because a colour field is a text
 * field that happens to parse what you type as a colour: the hex digits are real segments you can step
 * and select, exactly as a date field's are.
 *
 * Exported as `ColorFieldInput` only so tooling can resolve it; consume the compound form
 * `ColorField.Input`.
 */
export function ColorFieldInput({ className, ...props }: ColorFieldInputProps) {
  return (
    <AriaInput
      data-slot="input"
      className={[INPUT, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * The guidance under the control. Use it as `ColorField.Hint`.
 *
 * Exported as `ColorFieldHint` only so tooling can resolve it; consume the compound form
 * `ColorField.Hint`.
 */
export function ColorFieldHint({ className, ...props }: ColorFieldHintProps) {
  return (
    <AriaText
      slot="description"
      className={[HINT, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * The error, which renders nothing while the field is valid. Use it as `ColorField.Error`.
 *
 * Exported as `ColorFieldError` only so tooling can resolve it; consume the compound form
 * `ColorField.Error`.
 */
export function ColorFieldError({ className, ...props }: ColorFieldErrorProps) {
  return (
    <AriaFieldError
      className={[ERROR, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * A colour typed into a field, with a square showing what it is.
 *
 * ```tsx
 * <ColorField defaultValue={parseColor('#71FFF6')}>
 *   <ColorField.Label>Label colour</ColorField.Label>
 *   <ColorField.Control>
 *     <ColorField.Swatch />
 *     <ColorField.Input />
 *   </ColorField.Control>
 *   <ColorField.Hint>Hex, rgb() or oklch().</ColorField.Hint>
 *   <ColorField.Error>That is not a colour.</ColorField.Error>
 * </ColorField>
 * ```
 *
 * **It is a text field whose value happens to be a colour**, which is why it wears `field.ts`'s whole
 * anatomy — the legend, the hairline, the hint column, the error — and inherits every rule that file
 * already establishes, including the read-only behaviour and the resting boundary. A field that looked
 * like a native `<input type="color">` swatch would be the one control here with a different shape.
 *
 * **The square is a swatch, not the control.** The control is the text: a colour is something people
 * paste, and typing one is faster than dragging a picker to the value already in hand.
 *
 * **This is not a colour picker.** `ColorArea`, `ColorWheel` and `ColorSlider` exist for that and would
 * need a spectrum this design language does not have — Pulse's palette is four semantic accents, not a
 * gradient. A field is the honest half of the colour set to build here.
 */
function ColorFieldRoot({ className, children, ...props }: ColorFieldProps) {
  return (
    <AriaColorField
      data-slot="color-field"
      className={[FIELD, 'w-fit', className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaColorField>
  )
}

/**
 * The compound export. A plain `function` decorated with `Object.assign` leaves TypeScript unaware of
 * the slots, which is why the root is named apart and only the decorated const is exported.
 */
export const ColorField = Object.assign(ColorFieldRoot, {
  Label: ColorFieldLabel,
  Control: ColorFieldControl,
  Swatch: ColorFieldSwatch,
  Input: ColorFieldInput,
  Hint: ColorFieldHint,
  Error: ColorFieldError,
})

import {
  ColorSwatch as AriaColorSwatch,
  ColorSwatchPicker as AriaColorSwatchPicker,
  ColorSwatchPickerItem as AriaColorSwatchPickerItem,
} from 'react-aria-components'
import type {
  ColorSwatchPickerItemProps as AriaColorSwatchPickerItemProps,
  ColorSwatchPickerProps as AriaColorSwatchPickerProps,
} from 'react-aria-components'

import type { ReactNode } from 'react'

import { SWATCH } from '../ColorSwatch/ColorSwatch'

/** How the swatches sit: in a row, or stacked. Chosen in JS, because the layout is a class list. */
const LAYOUTS = {
  grid: 'flex flex-row flex-wrap items-center gap-2',
  stack: 'flex flex-col items-start gap-2',
} as const

/**
 * One preset. Use it as `ColorSwatchPicker.Item`.
 *
 * **The ring is `--foreground`, and this is the one place in the system the accent cannot be used.**
 * Everywhere else a selected or current thing takes teal — a `Nav` item, a `Table` row, a
 * `ToggleButton`. Here teal is one of the *choices*: a teal ring around the teal swatch says nothing, and
 * the same is true of yellow, green and red. A marker that shares a colour with an option cannot say
 * "this one", so the ring is the text colour, which inverts with the theme and contrasts with all five.
 *
 * The ring is drawn with `outline` at a 2px offset, so it sits *outside* the square and the colour keeps
 * its full 24px; an inset border would eat a fifth of a swatch and change the colour it exists to show.
 *
 * **The ring needs a transparent outline at rest, not `outline-none`.** `outline-none` sets Tailwind's
 * shared `--tw-outline-style` custom property, and every `outline-<width>` utility reads that same
 * property back — so once it is `none`, no ring on this element can draw again, not even from a
 * `data-[selected]:` variant. The swatch reported `outline-width: 2px` with `outline-style: none` while
 * looking perfectly styled. `Radio`, `Checkbox` and `Switch` already do it this way, which is why their
 * rings work.
 *
 * Exported as `ColorSwatchPickerItem` only so tooling can resolve it; consume the compound form
 * `ColorSwatchPicker.Item`.
 */
export function ColorSwatchPickerItem({
  className,
  color,
  ...props
}: AriaColorSwatchPickerItemProps) {
  return (
    <AriaColorSwatchPickerItem
      data-slot="swatch-option"
      color={color}
      className={[
        // The square itself is `ColorSwatch`'s, composed rather than repeated — a swatch has to look
        // the same whether it is being shown or being picked.
        SWATCH,
        // **A transparent outline at rest, never `outline-none`.** `outline-none` sets Tailwind's shared
        // `--tw-outline-style` custom property, and every `outline-<width>` utility reads that same
        // property back — so once it is `none`, *no* ring on this element can ever draw again, not even
        // from a `data-[selected]:` variant. The swatch reported `outline-width: 2px` and
        // `outline-style: none` while looking perfectly styled. `Radio`, `Checkbox` and `Switch` already
        // draw their rings this way, which is why theirs work.
        'cursor-pointer outline-2 outline-offset-2 outline-transparent',
        'transition-[outline-color] duration-(--duration-fast) ease-pulse',
        'data-[selected]:outline-foreground',
        'data-[focus-visible]:outline-foreground',
        'data-[hovered]:border-foreground',
        'data-[disabled]:cursor-not-allowed data-[disabled]:opacity-30',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
      {...props}
    >
      <AriaColorSwatch
        className="block size-full"
        style={({ color: c }) => ({ background: c.toString('css') })}
      />
    </AriaColorSwatchPickerItem>
  )
}

export interface ColorSwatchPickerProps extends Omit<
  AriaColorSwatchPickerProps,
  'children' | 'className' | 'value' | 'defaultValue' | 'onChange' | 'layout'
> {
  /** The chosen colour. Controlled. */
  value?: AriaColorSwatchPickerProps['value']
  /** The colour it starts on. */
  defaultValue?: AriaColorSwatchPickerProps['defaultValue']
  /** Called with the chosen colour. */
  onChange?: AriaColorSwatchPickerProps['onChange']
  /** `grid` puts the swatches in a row, `stack` in a column. */
  layout?: AriaColorSwatchPickerProps['layout']

  className?: string
  children?: ReactNode
}

/**
 * A row of preset colours, one of which is chosen.
 *
 * ```tsx
 * <ColorSwatchPicker aria-label="Label colour" defaultValue="#71FFF6">
 *   <ColorSwatchPicker.Item color="#71FFF6" />
 *   <ColorSwatchPicker.Item color="#FAD14F" />
 *   <ColorSwatchPicker.Item color="#FF9A8B" />
 * </ColorSwatchPicker>
 * ```
 *
 * **This is the other half of the colour set**, and the half that fits this design language: a palette
 * of colours the system already has, not a spectrum. `ColorArea`, `ColorWheel` and `ColorSlider` are for
 * picking *any* colour and would need a gradient Pulse does not contain; a picker over five semantic
 * accents is a decision someone can actually make.
 *
 * **The palette is the consumer's**, deliberately. A swatch needs a concrete colour value, and this
 * system's colours are `light-dark()` pairs resolved by CSS — there is no token a swatch can be handed.
 * So the picker arranges presets; which presets is the application's business, exactly as `TagGroup`
 * arranges chips it is given.
 *
 * Use `ColorField` instead when the colour is already known and needs typing or pasting — this is for
 * choosing from a set the application offers.
 */
function ColorSwatchPickerRoot({
  className,
  children,
  layout = 'grid',
  ...props
}: ColorSwatchPickerProps) {
  return (
    <AriaColorSwatchPicker
      data-slot="swatch-picker"
      className={[LAYOUTS[layout], className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaColorSwatchPicker>
  )
}

/**
 * The compound export. A plain `function` decorated with `Object.assign` leaves TypeScript unaware of
 * the slots, which is why the root is named apart and only the decorated const is exported.
 */
export const ColorSwatchPicker = Object.assign(ColorSwatchPickerRoot, {
  Item: ColorSwatchPickerItem,
})

