  children?: React.ReactNode
}

/**
 * A segment of a date. Taken from React Aria's own render prop rather than re-declared, so it
 * cannot drift from the signature it has to match.
 */
type Segment = Parameters<NonNullable<AriaDateInputProps['children']>>[0]

export interface DateRangePickerLabelProps extends AriaLabelProps {
  children?: React.ReactNode
}

export interface DateRangePickerGroupProps extends Omit<
  AriaGroupProps,
  'className'
> {
  className?: string
  children?: React.ReactNode
}

/**
 * The pair of dates. Narrower than a `DateInput`'s props on purpose: this is two inputs and one
 * control, so input-level props have no single input to go to. Anything genuinely per-segment
 * belongs on the segment.
 */
export interface DateRangePickerInputProps {
  className?: string
  /** What sits between the two dates. An en dash, by default. */
  separator?: React.ReactNode
  /** How to draw each segment. Optional — the segments are drawn for you. */
  children?: (segment: Segment) => React.ReactElement
}

export interface DateRangePickerSegmentProps extends Omit<
  AriaDateSegmentProps,
  'children' | 'className'
> {
  className?: string
  children?: React.ReactNode
}

export interface DateRangePickerIconProps extends React.HTMLAttributes<HTMLSpanElement> {
  position?: IconPosition
  className?: string
  children?: React.ReactNode
}

export interface DateRangePickerButtonProps extends Omit<
  AriaButtonProps,
  'children' | 'className'
> {
  className?: string
  children?: React.ReactNode
}

export interface DateRangePickerPopoverProps extends Omit<
  AriaPopoverProps,
  'className'
> {
  className?: string
  children?: React.ReactNode
}

export interface DateRangePickerCalendarProps extends Omit<
  AriaRangeCalendarProps<DateValue>,
  'children' | 'className'
> {
  className?: string
  children?: React.ReactElement | React.ReactElement[]
}

export interface DateRangePickerHeadingProps extends AriaCalendarHeadingProps {
  children?: React.ReactNode
}

export interface DateRangePickerGridProps extends Omit<
  AriaCalendarGridProps,
  'children' | 'className'
> {
  className?: string
  children?: React.ReactElement | React.ReactElement[]
}

export interface DateRangePickerCellProps extends Omit<
  AriaCalendarCellProps,
  'children' | 'className'
> {
  className?: string
  children?: React.ReactNode
}

export interface DateRangePickerHintProps extends AriaTextProps {
  children?: React.ReactNode
}

export interface DateRangePickerFieldErrorProps extends AriaFieldErrorProps {
  /** The message, or a function of the field's validation result. */
  children?: AriaFieldErrorProps['children']
}

/**
 * The legend. Use it as `DateRangePicker.Label`.
 *
 * Exported as `DateRangePickerLabel` only so tooling can resolve it; consume the compound form
 * `DateRangePicker.Label`.
 */
export function DateRangePickerLabel({
  className,
  children,
  ...props
}: DateRangePickerLabelProps) {
  return (
    <AriaLabel
      className={[LABEL, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaLabel>
  )
}

/**
 * Wraps the two dates and the button. Use it as `DateRangePicker.Group`.
 *
 * Exported as `DateRangePickerGroup` only so tooling can resolve it; consume the compound form
 * `DateRangePicker.Group`.
 */
export function DateRangePickerGroup({
  className,
  children,
  ...props
}: DateRangePickerGroupProps) {
  return (
    <AriaGroup
      className={[GROUP, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaGroup>
  )
}

/**
 * Both dates, with the separator between them. Use it as `DateRangePicker.Input`.
 *
 * It is one slot rather than two, because a range *is* one value: the two inputs share a single
 * control, and React Aria still needs to be told which is the start and which the end. Drawing
 * them here means the pairing cannot be got wrong and the field's hairline is drawn once around
 * both, rather than twice with a seam down the middle.
 *
 * Exported as `DateRangePickerInput` only so tooling can resolve it; consume the compound form
 * `DateRangePicker.Input`.
 */
export function DateRangePickerInput({
  className,
  separator,
  children,
}: DateRangePickerInputProps) {
  const segment =
    children ?? ((s: Segment) => <DateRangePickerSegment segment={s} />)

  return (
    <div
      data-slot="input"
      className={[RANGE_INPUT, className].filter(Boolean).join(' ')}
    >
      <AriaDateInput slot="start" className="flex items-center">
        {segment}
      </AriaDateInput>
      <span aria-hidden="true" className={SEPARATOR}>
        {separator ?? '–'}
      </span>
      <AriaDateInput slot="end" className="flex items-center">
        {segment}
      </AriaDateInput>
    </div>
  )
}

/**
 * One segment of a date. Input` draws them for you.
 *
 * **Internal.** `DateRangePicker` draws one itself; it is not a published slot.
 */
export function DateRangePickerSegment({
  className,
  children,
  ...props
}: DateRangePickerSegmentProps) {
  return (
    <AriaDateSegment
      className={[DATE_SEGMENT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaDateSegment>
  )
}

/**
 * An affix at either end of the control. Group`.
 *
 * **Internal.** `DateRangePicker` draws one itself; it is not a published slot.
 */
export function DateRangePickerIcon({
  position = 'start',
  className,
  children,
  ...props
}: DateRangePickerIconProps) {
  return (
    <span
      data-slot={position === 'start' ? 'icon-start' : 'icon-end'}
      aria-hidden="true"
      className={[ICON, ICON_POSITIONS[position], className]
        .filter(Boolean)
        .join(' ')}
      {...props}
    >
      {children ?? (
        <svg viewBox="0 0 16 16" fill="none" className="h-full w-auto">
          <rect
            x="1.75"
            y="3.25"
            width="12.5"
            height="11"
            stroke="currentColor"
            strokeWidth="1.5"
          />
          <path
            d="M1.75 6.75h12.5M5.25 1.75v3M10.75 1.75v3"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
          />
        </svg>
      )}
    </span>
  )
}

/**
 * The chevron that opens the calendar. Use it as `DateRangePicker.Button`, inside a
 * `DateRangePicker.Group`.
 *
 * Exported as `DateRangePickerButton` only so tooling can resolve it; consume the compound form
 * `DateRangePicker.Button`.
 */
export function DateRangePickerButton({
  className,
  children,
  ...props
}: DateRangePickerButtonProps) {
  return (
    <AriaButton
      data-slot="icon-end"
      className={[DATE_TRIGGER, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children ?? <DateCaret />}
    </AriaButton>
  )
}

/**
 * The calendar surface. Its `placement` is worth setting —
 * a range calendar is wide, and `bottom start` is where it reads best.
 *
 * **Internal.** `DateRangePicker` draws one itself; it is not a published slot.
 */
export function DateRangePickerPopover({
  className,
  children,
  ...props
}: DateRangePickerPopoverProps) {
  return (
    <AriaPopover
      data-slot="dropdown"
      className={[DATE_MENU, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaPopover>
  )
}

/**
 * The month heading, between the arrows. *
 * **Internal.** `DateRangePicker` draws one itself; it is not a published slot.
 */
export function DateRangePickerHeading({
  className,
  children,
  ...props
}: DateRangePickerHeadingProps) {
  // Read the state rather than letting React Aria caption it: with two months visible its
  // `aria-hidden` visual node names only the first — see the note in `date.tsx`.
  const state = useContext(RangeCalendarStateContext)
  const label = useVisibleRangeLabel(state?.visibleRange ?? null)

  return (
    // `aria-hidden`, because React Aria renders its own heading for assistive tech just above
    // this one — and that one is correct for any number of visible months. This is the copy the
    // eye reads, and React Aria's would otherwise be the one the eye reads instead, captioning a
    // two-month calendar with only its first month.
    <h2
      data-slot="heading"
      aria-hidden="true"
      className={[DATE_HEADING, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children ?? label}
    </h2>
  )
}

/**
 * The month grid. *
 * **Internal.** `DateRangePicker` draws one itself; it is not a published slot.
 */
export function DateRangePickerGrid({
  className,
  children,
  ...props
}: DateRangePickerGridProps) {
  return (
    <AriaCalendarGrid
      className={[className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaCalendarGrid>
  )
}

/**
 * One day. Both ends of the
 * range carry the accent whole; the days between them take it as a wash.
 *
 * **Internal.** `DateRangePicker` draws one itself; it is not a published slot.
 */
export function DateRangePickerCell({
  className,
  children,
  ...props
}: DateRangePickerCellProps) {
  return (
    <AriaCalendarCell
      data-slot="cell"
      className={[CELL, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaCalendarCell>
  )
}

/**
 * The range calendar, drawn whole. Set `visibleDuration` to
 * show two months at once, which is what a range usually wants.
 *
 * **Internal.** `DateRangePicker` draws one itself; it is not a published slot.
 */
export function DateRangePickerCalendar({
  className,
  children,
  visibleDuration,
  ...props
}: DateRangePickerCalendarProps) {
  // **Two months, always.** A range's two ends are rarely in the same month, so one month would make the
  // common case a second interaction. Enforced here rather than offered as a prop — there is no range in
  // this system that wants one, and it used to be reachable only through a `Calendar` slot.
  const MONTHS = 2

  return (
    <AriaRangeCalendar
      className={[className].filter(Boolean).join(' ')}
      visibleDuration={{ months: MONTHS }}
      {...props}
    >
      {children ?? (
        <DateCalendarChrome
          Heading={DateRangePickerHeading}
          Cell={DateRangePickerCell}
          months={MONTHS}
        />
      )}
    </AriaRangeCalendar>
  )
}

/**
 * The guidance under the control. Use it as `DateRangePicker.Hint`.
 *
 * Exported as `DateRangePickerHint` only so tooling can resolve it; consume the compound form
 * `DateRangePicker.Hint`.
 */
export function DateRangePickerHint({
  className,
  children,
  ...props
}: DateRangePickerHintProps) {
  return (
    <AriaText
      slot="description"
      className={[HINT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaText>
  )
}

/**
 * The message shown when the picker is `isInvalid`. Use it as `DateRangePicker.Error`.
 *
 * Exported as `DateRangePickerFieldError` only so tooling can resolve it; consume the compound
 * form `DateRangePicker.Error`.
 */
export function DateRangePickerFieldError({
  className,
  ...props
}: DateRangePickerFieldErrorProps) {
  return (
    <AriaFieldError
      className={[ERROR, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * Styled element. Not exported — `DateRangePicker` below is the public symbol, and docgen reads
 * the JSDoc from the *exported* declaration, not this one.
 */
function DateRangePickerRoot<T extends DateValue>({
  ref,
  size = 'md',
  className,
  children,
  ...props
}: DateRangePickerProps<T>) {
  return (
    <AriaDateRangePicker
      ref={ref}
      className={[DATE_ROOT, FIELD_SIZES[size], className]
        .filter(Boolean)
        .join(' ')}
      {...props}
    >
      {children}
      {/* A picker without a calendar is not a picker, so one is always drawn. It used to be skippable by
          passing a `Popover` of your own; that slot is gone, so the branch went with it. */}
      <DateRangePickerPopover placement="bottom start">
        <DateRangePickerCalendar />
      </DateRangePickerPopover>
    </AriaDateRangePicker>
  )
}

/**
 * Two dates, as one value — "when does this window start and end". The difference from two
 * `DatePicker`s is not cosmetic: a range has a validity of its own (the end cannot precede the
 * start), one calendar serves both ends, and the days between them are shown as chosen rather
 * than as two unrelated picks.
 *
 * ```tsx
 * <DateRangePicker
 *   defaultValue={{ start: parseDate('2026-10-11'), end: parseDate('2026-10-20') }}
 * >
 *   <DateRangePicker.Label>Window</DateRangePicker.Label>
 *   <DateRangePicker.Group>
 *     <DateRangePicker.Input />
 *     <DateRangePicker.Button />
 *   </DateRangePicker.Group>
 *   <DateRangePicker.Hint>Your local time.</DateRangePicker.Hint>
 * </DateRangePicker>
 * ```
 *
 * Sharing an anatomy with `DatePicker` rather than copying it, the same way the field components
 * share `field.ts`. The one part that genuinely differs is the day: in a range every day between
 * the ends is selected, so the two ends carry the accent whole and the days between take it as a
 * wash. Without that, a range reads as two separate picks that happen to be far apart.
 *
 * The calendar draws **two months**, which is what a range wants: the ends are
 * rarely in the same month, so one month would make the common case a second interaction. It is enforced
 * here rather than offered as a prop, and it used to be reachable only through a `Calendar` slot.
 */
export const DateRangePicker = Object.assign(DateRangePickerRoot, {
  Label: DateRangePickerLabel,
  Group: DateRangePickerGroup,
  Input: DateRangePickerInput,
  Button: DateRangePickerButton,
  Hint: DateRangePickerHint,
  Error: DateRangePickerFieldError,
})

import { useEffect, useRef, useState } from 'react'

import { CHART_TOOLTIP } from '../chartTooltip'
import type { MapDot } from './worldDots'

/**
 * A world map drawn as dots on a `<canvas>`, with the ones that matter in the accent.
 *
 * ```tsx
 * import { WORLD_DOTS } from './worldDots'
 * <DotMap dots={WORLD_DOTS} label="Request origins, last hour" />
 * ```
 *
 * **The drawing is `drawMap` from `pulse-replica/js/system.js`.** Every point is a `2.6×2.6` square
 * centred on its coordinate, filled either near-white or with a dimmer teal. The replica builds those as
 * `<rect>` elements inside an `<svg>`; this draws the same squares with `fillRect`, because ~850 DOM nodes
 * for one picture is the cost the canvas exists to avoid. The replica's staggered fade-in is not copied —
 * a page-level flourish rather than a property of the map.
 *
 * **Canvas costs three things SVG gave for free, and each is handled rather than ignored:**
 *
 * 1. **A canvas cannot read `var()` or `color-mix()`.** `fillStyle` needs a concrete colour, so the two
 *    fills are resolved by assigning them to the element's own `color` and reading back what the browser
 *    computed — which is what makes `light-dark()` and the `color-mix` derivations work here at all. The
 *    canvas has no text, so using its `color` as the probe changes nothing on screen.
 * 2. **A canvas has to be redrawn when the theme changes.** The tokens are CSS, so flipping `data-theme`
 *    changes what they resolve to without touching this component. A `MutationObserver` on the document
 *    element redraws; without it the map keeps the colours of whichever theme was active when it mounted.
 * 3. **The readout cannot be a `<foreignObject>`**, because there is no SVG. It is an HTML panel in a
 *    wrapper around the canvas, positioned by percentage exactly as `BarChart`'s is.
 *
 * **The device pixel ratio is applied, not assumed.** The canvas's `width`/`height` attributes are its
 * *bitmap* size while its CSS size is the box, so a retina display draws a blurry map unless the bitmap is
 * scaled up and the context scaled back down. `width`/`height` here are user units and CSS pixels; the
 * bitmap is `dpr ×` that.
 *
 * **The map is fitted to its box by default, and the replica's caller is why.** The data's range is about
 * `x 81–482`, `y 144–401` — 401 tall — while the zone `dashboard.html` gives it is `528×380`. The comment
 * there says the dots are *"scaled ~0.93 into a 528×380 zone, centered"*, and that scaling lives in the
 * page, not in `drawMap`. `fitDots` is exported because that is now the geometry worth testing directly:
 * with the drawing on a canvas there are no longer any dots in the DOM to inspect.
 *
 * **Two colours, both derived.** The replica writes `#5be4dc` for an accented dot and
 * `rgba(255,255,255,.85)` for the rest. The first is the accent about 12% toward ink — a small dot at full
 * accent is a glare. The second is `--foreground` at 85%: white on the dark theme, near-black on the light
 * one, which is the behaviour a map on a white page needs and the replica never had to consider.
 *
 * **The readout is opt-in through the data.** The replica's `GEO_DOTS` is bare geometry with no values, so
 * its map has no tooltip and could not have one. Give a dot a fourth element and it becomes hoverable: the
 * map finds the nearest labelled dot within 10 units of the pointer. Unlabelled dots are skipped, so a
 * pointer over the ocean finds nothing rather than the nearest coastline fragment. It is `aria-hidden` for
 * the same reason the chart's is — it exists only under a pointer, so announcing it would claim an
 * affordance this cannot keep.
 */
export interface DotMapProps {
  /** Dot centres. `[x, y]` for a plain dot, `[x, y, 1]` for one in the accent, `[x, y, 1, label]`. */
  dots: MapDot[]
  /** Width in user units **and** CSS pixels. */
  width?: number
  /** Height in user units and CSS pixels. */
  height?: number
  /** Scale and centre the points into the box. Off for coordinates already in the box's units. */
  fit?: boolean
  /** What this map shows, for a screen reader. It is the drawing's only text. */
  label: string
  className?: string
}

/** The replica's dot: a 2.6-unit square, which is what makes the coastline read at a distance. */
const DOT = 2.6
/** Breathing room when fitting, in user units, so an edge dot is not half outside the box. */
const PAD = 3
/** How close the pointer must be to a labelled dot, in user units. */
const HIT_RADIUS = 10

/** The two fills, written the way the design system expresses them. Resolved before use — see above. */
const FILL_ACCENT =
  'color-mix(in oklch, var(--color-primary) 88%, var(--color-ink))'
const FILL_PLAIN =
  'color-mix(in oklch, var(--color-foreground) 85%, transparent)'

/**
 * Scale and centre a set of points into a box, keeping each dot's accent flag and label.
 *
 * **Exported because it is the part of this component that can be tested.** While the map was an SVG, the
 * stories could read every `<rect>` back out of the DOM and check where it landed; a canvas has no such
 * elements, so the geometry moved into a pure function and is asserted directly instead of through pixels.
 */
export function fitDots(
  dots: MapDot[],
  width: number,
  height: number,
  pad: number = PAD,
): MapDot[] {
  if (!dots.length) return dots
  const xs = dots.map((d) => d[0])
  const ys = dots.map((d) => d[1])
  const minX = Math.min(...xs)
  const maxX = Math.max(...xs)
  const minY = Math.min(...ys)
  const maxY = Math.max(...ys)
  const scale = Math.min(
    (width - pad * 2) / (maxX - minX || 1),
    (height - pad * 2) / (maxY - minY || 1),
  )
  const offsetX = (width - (maxX - minX) * scale) / 2
  const offsetY = (height - (maxY - minY) * scale) / 2
  return dots.map(
    (d) =>
      [
        (d[0] - minX) * scale + offsetX,
        (d[1] - minY) * scale + offsetY,
        ...d.slice(2),
      ] as MapDot,
  )
}

export function DotMap({
  dots,
  width = 528,
  height = 380,
  fit = true,
  label,
  className,
}: DotMapProps) {
  const canvas = useRef<HTMLCanvasElement>(null)
  const [hovered, setHovered] = useState<MapDot | null>(null)
  const draw = fit ? fitDots(dots, width, height) : dots

  useEffect(() => {
    const element = canvas.current
    if (!element) return
    const context = element.getContext('2d')
    if (!context) return

    const paint = () => {
      // The bitmap is dpr × the box, and the context is scaled back so everything below draws in user
      // units. Without both halves a retina display gets a quarter-resolution map.
      const dpr = window.devicePixelRatio || 1
      element.width = Math.round(width * dpr)
      element.height = Math.round(height * dpr)
      context.setTransform(dpr, 0, 0, dpr, 0, 0)
      context.clearRect(0, 0, width, height)

      // A canvas cannot use `var()` or `color-mix()`. Assigning the expression to the element's own
      // `color` and reading it back lets the browser do the computation — which is what keeps
      // `light-dark()` and the token derivations working here. The canvas has no text to recolour.
      const resolve = (expression: string) => {
        element.style.color = expression
        const computed = getComputedStyle(element).color
        element.style.color = ''
        return computed || '#888'
      }
      const accent = resolve(FILL_ACCENT)
      const plain = resolve(FILL_PLAIN)

      for (const dot of draw) {
        context.fillStyle = dot[2] === 1 ? accent : plain
        context.fillRect(dot[0] - DOT / 2, dot[1] - DOT / 2, DOT, DOT)
      }
    }

    paint()
    // The tokens are CSS, so a theme switch changes what they resolve to without touching this component.
    // Observing the document element is what stops the map keeping the theme it mounted in.
    const observer = new MutationObserver(paint)
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ['data-theme', 'class', 'style'],
    })
    return () => observer.disconnect()
  }, [draw, width, height])

  return (
    <div
      data-slot="dot-map"
      className={['relative', className].filter(Boolean).join(' ')}
      style={{ width, height }}
      onPointerMove={(event) => {
        const box = canvas.current?.getBoundingClientRect()
        if (!box || box.width === 0) return
        // The pointer in the drawing's own units. Each axis is converted against its own dimension,
        // because the canvas stretches to its box independently of its bitmap.
        const x = ((event.clientX - box.left) / box.width) * width
        const y = ((event.clientY - box.top) / box.height) * height
        let nearest: MapDot | null = null
        let nearestDistance = Infinity
        for (const dot of draw) {
          if (typeof dot[3] !== 'string') continue
          const distance = Math.hypot(dot[0] - x, dot[1] - y)
          if (distance < nearestDistance) {
            nearestDistance = distance
            nearest = dot
          }
        }
        setHovered(nearestDistance <= HIT_RADIUS ? nearest : null)
      }}
      onPointerLeave={() => setHovered(null)}
    >
      <canvas
        ref={canvas}
        data-slot="dot-map-canvas"
        role="img"
        aria-label={label}
        className="block size-full"
      />
      {hovered ? (
        <div
          data-slot="dot-map-tooltip"
          aria-hidden="true"
          className={`${CHART_TOOLTIP} -top-2 w-max`}
          style={{
            left: `${(hovered[0] / width) * 100}%`,
            top: `${(hovered[1] / height) * 100}%`,
          }}
        >
          {hovered[3]}
        </div>
      ) : null}
    </div>
  )
}

import { DropZone as AriaDropZone } from 'react-aria-components'
import type { DropZoneProps as AriaDropZoneProps } from 'react-aria-components'

import type { ReactNode } from 'react'

export interface DropZoneProps extends Omit<
  AriaDropZoneProps,
  | 'className'
  | 'children'
  | 'onDrop'
  | 'isDisabled'
  | 'onDropEnter'
  | 'onDropExit'
> {
  /** Called with the dropped files. This is the whole point of the component — and it was missing from the published manifest, so it looked like a component that took nothing. */
  onDrop?: AriaDropZoneProps['onDrop']
  /** Stops the zone accepting drops. */
  isDisabled?: AriaDropZoneProps['isDisabled']
  /** Called when a drag enters the zone. */
  onDropEnter?: AriaDropZoneProps['onDropEnter']
  /** Called when a drag leaves the zone. */
  onDropExit?: AriaDropZoneProps['onDropExit']

  className?: string
  children?: ReactNode
}

/** What the zone is for. */
export interface DropZoneTitleProps {
  className?: string
  children?: ReactNode
}

/** The line under it — the "or", the accepted types, the size limit. */
export interface DropZoneHintProps {
  className?: string
  children?: ReactNode
}

/**
 * A target that accepts files dragged onto it.
 *
 * **The sheet has no drop zone**, so this is an invention built from what it does have: a dashed
 * rule where `Separator` draws its dashed one, the panel's own surface, and the capped mono legend.
 *
 * The **dashed edge is the whole affordance**, and it is the only place in this system a dashed
 * border means "put something here" rather than "these two things are apart". A solid edge would read
 * as a panel with nothing in it; a dashed one reads as a space waiting to be filled.
 *
 * ```tsx
 * <DropZone onDrop={async (e) => importFiles(await collect(e.items))}>
 *   <DropZone.Title>Drop a log file here</DropZone.Title>
 *   <DropZone.Hint>JSON or CSV, up to 10 MB</DropZone.Hint>
 *   <FileTrigger acceptedFileTypes={['.json', '.csv']} onSelect={(files) => upload(files)}>
 *     <Button variant="outline">Browse…</Button>
 *   </FileTrigger>
 * </DropZone>
 * ```
 *
 * **A drop zone on its own is not accessible.** Dragging is a pointer gesture, so it is invisible to
 * a keyboard and to a screen reader — which is why the `FileTrigger` and its button are not optional
 * decoration but the other half of the component. A page that offers only the drop is a page some
 * people cannot use at all. `FileTrigger` needs no styling of its own: it renders a hidden file input
 * and hands the chosen files to whatever child you give it, so the visible control is your `Button`.
 *
 * React Aria handles the parts that are genuinely hard: it knows when a drag is over the zone and
 * reports it as `data-drop-target`, it can tell a file drag from a text drag, and `getDropOperation`
 * decides whether the drop is a copy or a move.
 */
function DropZoneRoot({ className, children, ...props }: DropZoneProps) {
  return (
    <AriaDropZone
      // **`[data-rac]` is on every element React Aria renders**, so querying the first one from the
      // story root finds the browse *button* — the documented trap, and one this suite has now walked
      // into twice. `data-slot` names the box itself, as it does for the fill and the slider's grip.
      data-slot="dropzone"
      className={[
        'flex min-h-40 flex-col items-center justify-center gap-3 p-8',
        'border border-dashed border-border bg-card rounded-md text-center',
        // The target lights up while a file is over it, which is the only feedback a drag gets.
        'transition-colors duration-(--duration-fast) ease-pulse',
        'data-[drop-target]:border-primary data-[drop-target]:bg-primary/8',
        'data-[focus-visible]:outline-2 data-[focus-visible]:-outline-offset-2 data-[focus-visible]:outline-ring',
        'data-[disabled]:opacity-30',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
      {...props}
    >
      {children}
    </AriaDropZone>
  )
}

/**
 * What the zone is for. Use it as `DropZone.Title`.
 *
 * Exported as `DropZoneTitle` only so tooling can resolve it; consume the compound form
 * `DropZone.Title`.
 */
export function DropZoneTitle({ className, children }: DropZoneTitleProps) {
  return (
    <p
      className={['text-[14px] text-foreground', className]
        .filter(Boolean)
        .join(' ')}
    >
      {children}
    </p>
  )
}

/**
 * The line under the title — accepted types, a size limit, or the word "or". Use it as
 * `DropZone.Hint`.
 *
 * Exported as `DropZoneHint` only so tooling can resolve it; consume the compound form
 * `DropZone.Hint`.
 */
export function DropZoneHint({ className, children }: DropZoneHintProps) {
  return (
    <p
      className={[
        'font-mono text-[11px] uppercase tracking-[0.04em] text-foreground/45',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
    >
      {children}
    </p>
  )
}

/**
 * The compound export. A plain `function` decorated with `Object.assign` leaves TypeScript unaware of
 * the slots, which is why the root is named apart and only the decorated const is exported.
 */
export const DropZone = Object.assign(DropZoneRoot, {
  Title: DropZoneTitle,
  Hint: DropZoneHint,
})

import { useId } from 'react'

/**
 * A series that never varied — a monitor at 100% — as one flat rule near the top of its box.
 *
 * ```tsx
 * <FlatLine label="fra1 uptime, 100%" />
 * <FlatLine height={52} lineY={6} label="iad1 uptime, 100%" />
 * ```
 *
 * **This is `drawFlat` from `pulse-replica/js/system.js`, whose own comment calls it the "flat 100%
 * line".** A sparkline is a series scaled to its own range, and a series with no range has nothing to
 * scale into — which is why the replica has a *separate function* for this case rather than a branch
 * inside `drawSpark`. That separation is the whole point: drawing a flat series through the middle of
 * the box, as a naive scale would, says "average"; drawing it at the top says "perfect, and it stayed
 * that way", which is what an uptime line at 100% means.
 *
 * It draws two things, in this order:
 *
 * 1. a **dot-grid zone** from five units below the rule to the bottom of the box — the same `.32`
 *    weight as the sparkline's, because this is a sparkline's neighbour;
 * 2. the **rule itself**, 2px of accent, full width.
 *
 * **`lineY` is in user units, not a fraction, and that is deliberate.** The replica draws it at `y=1` in
 * an 84-tall box and at `y=6` in a 52-tall one — 1.2% and 11.5%. Those are not the same fraction, so the
 * value is a distance from the top rather than a proportion, and treating it as a proportion would move
 * the line in one of the two places the replica uses it.
 */
export interface FlatLineProps {
  /** Width in user units **and** rendered px. A `className` can stretch it. */
  width?: number
  /** Height in user units and rendered px. */
  height?: number
  /** Where the rule sits, in user units from the top. The replica's own values are 1 and 6. */
  lineY?: number
  /** What this line says, for a screen reader. It is the drawing's only text. */
  label: string
  className?: string
}

/** How far below the rule the texture starts — the replica's `y + 5`. */
const ZONE_GAP = 5

export function FlatLine({
  width = 300,
  height = 84,
  lineY = 1,
  label,
  className,
}: FlatLineProps) {
  // `<pattern>` ids are document-global, so two of these on a page would otherwise share the first one's
  // dots. `BarChart` and `Sparkline` both learned this the same way.
  const patternId = `flat-line-dots-${useId()}`
  const zoneTop = lineY + ZONE_GAP

  return (
    <svg
      data-slot="flat-line"
      // Rendered as well as declared in the viewBox — a viewBox with no size collapses to nothing, which
      // is how the Sparkline shipped invisible for a round.
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      preserveAspectRatio="none"
      role="img"
      aria-label={label}
      className={className}
    >
      <defs>
        <pattern
          id={patternId}
          width="7.7"
          height="7.7"
          patternUnits="userSpaceOnUse"
        >
          <circle cx="0.9" cy="0.9" r="0.9" fill="rgba(255,255,255,0.32)" />
        </pattern>
      </defs>
      <rect
        data-slot="flat-line-zone"
        x="0"
        y={zoneTop}
        width={width}
        height={Math.max(0, height - zoneTop)}
        fill={`url(#${patternId})`}
      />
      <rect
        data-slot="flat-line-rule"
        x="0"
        y={lineY - 1}
        width={width}
        height="2"
        fill="var(--color-primary)"
      />
    </svg>
  )
}

import {
  GridList as AriaGridList,
  GridListHeader as AriaGridListHeader,
  GridListItem as AriaGridListItem,
  GridListSection as AriaGridListSection,
  GridListLoadMoreItem as AriaGridListLoadMoreItem,
} from 'react-aria-components'
import { LOAD_MORE, LoadMoreSpinner } from '../loadMore'
import type {
  GridListHeaderProps as AriaGridListHeaderProps,
  GridListItemProps as AriaGridListItemProps,
  GridListProps as AriaGridListProps,
  GridListSectionProps as AriaGridListSectionProps,
  GridListLoadMoreItemProps as AriaGridListLoadMoreItemProps,
} from 'react-aria-components'

import type { ReactNode } from 'react'

export interface GridListProps<T> extends Omit<
  AriaGridListProps<T>,
  | 'children'
  | 'className'
  | 'selectionMode'
  | 'selectedKeys'
  | 'defaultSelectedKeys'
  | 'onSelectionChange'
  | 'disabledKeys'
  | 'dragAndDropHooks'
> {
  /**
   * Wires drag-and-drop, from React Aria's own `useDragAndDrop`. Without it a row cannot be picked up —
   * and a `DropIndicator` has nowhere to be rendered, so the two arrive together.
   */
  dragAndDropHooks?: AriaGridListProps<T>['dragAndDropHooks']

  /** `none`, `single` or `multiple`. */
  selectionMode?: AriaGridListProps<T>['selectionMode']
  /** The chosen rows, by each item's `id`. */
  selectedKeys?: AriaGridListProps<T>['selectedKeys']
  /** What starts chosen. */
  defaultSelectedKeys?: AriaGridListProps<T>['defaultSelectedKeys']
  /** Called with the new set of keys. */
  onSelectionChange?: AriaGridListProps<T>['onSelectionChange']
  /** Rows that cannot be chosen. */
  disabledKeys?: AriaGridListProps<T>['disabledKeys']

  /** The rows, or a function that renders one from an item. */
  children?: AriaGridListProps<T>['children']
  className?: string
}

export interface GridListItemProps<T = object> extends Omit<
  AriaGridListItemProps<T>,
  'className' | 'children'
> {
  className?: string
  /** What the row says, for keyboard type-ahead and for a screen reader. */
  textValue?: string
  children?: ReactNode
}

/** The inside of a row, laid out as a column instead of React Aria's inline default. */
export interface GridListBodyProps {
  className?: string
  children?: ReactNode
}

export interface GridListSectionProps<T> extends Omit<
  AriaGridListSectionProps<T>,
  'className' | 'children'
> {
  className?: string
  children?: ReactNode
}

export interface GridListHeaderProps extends Omit<
  AriaGridListHeaderProps,
  'className'
> {
  className?: string
}

/**
 * The surface the rows sit on.
 *
 * **The sheet has no list or grid class of its own** — its dashboard is a stack of `.ds-panel`s — so
 * the arrangement is an invention and every visible part is borrowed: the panel, the hairline, the
 * uppercase legend. `GridList` is the sheet's dashboard as something you can select from.
 *
 * A list is a column and a grid is a `grid`, and only the caller knows which they want, so the layout
 * is a `className` rather than a `layout` prop that would have to guess.
 */
const LIST = [
  'flex flex-col outline-none',
  'data-[empty]:items-center data-[empty]:justify-center',
].join(' ')

/**
 * A row: the sheet's panel, with the selected state on its edge rather than on a fill.
 *
 * A fill would have to carry `ink`, and a card is mostly *text* — a filled card would invert every
 * word in it. The edge and a hairline of accent is enough to say which one is chosen, and it leaves
 * the text alone.
 */
const ITEM = [
  'flex items-start gap-3 p-4',
  'border border-border-strong bg-card rounded-xl',
  'text-foreground outline-2 -outline-offset-2 outline-transparent',
  'transition-colors duration-(--duration-fast) ease-pulse',
  'data-[hovered]:bg-muted',
  'data-[pressed]:bg-foreground/10',
  'data-[focus-visible]:outline-2 data-[focus-visible]:-outline-offset-2 data-[focus-visible]:outline-ring',
  'data-[selected]:border-primary',
  'data-[disabled]:opacity-30 data-[disabled]:cursor-not-allowed',
].join(' ')

const BODY = 'flex min-w-0 flex-1 flex-col gap-1'

const SECTION = 'flex flex-col gap-2'

/** The sheet's `.ds-field-legend`, over a run of rows. */
const HEADER = [
  'px-0.5 pt-1 pb-0.5',
  'font-mono text-[11px] uppercase tracking-[0.08em] text-foreground/45',
].join(' ')

/**
 * The empty state, styled rather than left as a bare string, because an empty list is the state a
 * dashboard is in most mornings.
 */
const EMPTY = 'px-4 py-10 text-center text-[13px] text-foreground/45'

/**
 * A selectable list or grid of rows. Use it for anything the page is a collection of — a dashboard's
 * monitors, a run of results, a set of files.
 *
 * ```tsx
 * <GridList aria-label="Monitors" selectionMode="multiple" className="grid grid-cols-3 gap-3">
 *   <GridList.Item id="fra1" textValue="fra1 · Frankfurt">
 *     <GridList.Body>
 *       <span className="font-mono text-[13px] text-foreground">fra1 · Frankfurt</span>
 *       <span className="text-[12px] text-foreground/70">up · 42ms</span>
 *     </GridList.Body>
 *   </GridList.Item>
 * </GridList>
 * ```
 *
 * **A grid list is a table that is not a table.** Both render `role="grid"` with rows, and both are
 * navigated with the arrow keys — but a table's columns are the point, and a grid list's rows are.
 * Reach for `Table` when the data has a header row worth aligning to; reach for this when the rows
 * are cards.
 *
 * The selection is React Aria's: `selectionMode`, `selectedKeys`, `disabledKeys`, and a row that
 * reports itself through `aria-selected` and `data-selected`. The keyboard model is the table's —
 * arrows move, Space toggles, Ctrl+A selects the lot — with type-ahead over each row's `textValue`.
 *
 * `GridList.Section` and `GridList.Header` group rows that belong together, and
 * `renderEmptyState` gives the list something to say when there is nothing in it, which a bare
 * `map` over an empty array never does.
 */
function GridListRoot<T>({ className, children, ...props }: GridListProps<T>) {
  return (
    <AriaGridList
      data-slot="grid-list"
      className={[LIST, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaGridList>
  )
}

/**
 * One row. Use it as `GridList.Item`, with a `GridList.Body` inside it and a `textValue` for
 * type-ahead.
 *
 * Exported as `GridListItem` only so tooling can resolve it; consume the compound form
 * `GridList.Item`.
 */
export function GridListItem<T = object>({
  className,
  children,
  ...props
}: GridListItemProps<T>) {
  return (
    <AriaGridListItem
      className={[ITEM, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaGridListItem>
  )
}

/**
 * What a row holds, as a column. Use it as `GridList.Body`.
 *
 * Exported as `GridListBody` only so tooling can resolve it; consume the compound form
 * `GridList.Body`.
 */
export function GridListBody({ className, children }: GridListBodyProps) {
  return (
    <div className={[BODY, className].filter(Boolean).join(' ')}>
      {children}
    </div>
  )
}

/**
 * A group of rows. Use it as `GridList.Section`, with a `GridList.Header` at the top of it.
 *
 * Exported as `GridListSection` only so tooling can resolve it; consume the compound form
 * `GridList.Section`.
 */
export function GridListSection<T>({
  className,
  children,
  ...props
}: GridListSectionProps<T>) {
  return (
    <AriaGridListSection
      className={[SECTION, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaGridListSection>
  )
}

/**
 * A group's legend. Use it as `GridList.Header`.
 *
 * Exported as `GridListHeader` only so tooling can resolve it; consume the compound form
 * `GridList.Header`.
 */
export function GridListHeader({
  className,
  children,
  ...props
}: GridListHeaderProps) {
  return (
    <AriaGridListHeader
      className={[HEADER, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaGridListHeader>
  )
}

/**
 * What a list says when it has nothing to show.
 *
 * It is a **component** rather than a string so a caller can put a button in it — "nothing here yet"
 * and "nothing here yet, add one" are different messages, and the second is the one a person on an
 * empty dashboard needs.
 */
export function GridListEmpty({ children }: { children?: ReactNode }) {
  return <div className={EMPTY}>{children}</div>
}

/**
 * The compound export. A plain `function` decorated with `Object.assign` would leave TypeScript
 * unaware of the slots — the same shape every other component here uses, and the reason the root is
 * not itself exported under the plain name.
 */
/**
 * The row that asks for the next page. Use it as `GridList.LoadMore`, last inside `GridList`.
 *
 * ```tsx
 * <GridList aria-label="Monitors" onLoadMore={() => loadNextPage()}>
 *   {rows}
 *   <GridList.LoadMore isLoading={isLoading} onLoadMore={() => loadNextPage()} />
 * </GridList>
 * ```
 *
 * **It watches the scroll position and calls `onLoadMore` when it comes into view** — React Aria's own
 * sentinel, not something this component implements. What it adds is the row: a quiet centred strip at
 * the foot of the list, where the next page arrives.
 *
 * **It draws nothing until `isLoading`.** React Aria renders the sentinel's children only while loading, so
 * the element is always in the DOM to be observed and the spinner appears inside it when there is work in
 * flight. The spinner is `motion-safe`, so a reader who has asked for less motion gets a still one rather
 * than none.
 */
export function GridListLoadMore({
  className,
  children,
  ...props
}: AriaGridListLoadMoreItemProps) {
  return (
    <AriaGridListLoadMoreItem
      data-slot="grid-list-load-more"
      className={[LOAD_MORE, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children ?? <LoadMoreSpinner />}
    </AriaGridListLoadMoreItem>
  )
}

export const GridList = Object.assign(GridListRoot, {
  Item: GridListItem,
  Body: GridListBody,
  Section: GridListSection,
  Header: GridListHeader,
  Empty: GridListEmpty,
  LoadMore: GridListLoadMore,
})

import {
  Header as AriaHeader,
  ListBox as AriaListBox,
  ListBoxItem as AriaListBoxItem,
  ListBoxLoadMoreItem as AriaListBoxLoadMoreItem,
  ListBoxSection as AriaListBoxSection,
} from 'react-aria-components'
import type {
  HeaderProps as AriaHeaderProps,
  ListBoxItemProps as AriaListBoxItemProps,
  ListBoxLoadMoreItemProps as AriaListBoxLoadMoreItemProps,
  ListBoxProps as AriaListBoxProps,
  ListBoxSectionProps as AriaListBoxSectionProps,
} from 'react-aria-components'

import type { ReactNode } from 'react'

import { LOAD_MORE, LoadMoreSpinner } from '../loadMore'
import { OPTION, OPTION_LIST } from '../optionList'

// `overflow-clip` so the rounded panel actually clips the option rows it holds — a row's hover fill
// is a rectangle and would otherwise paint over the corner. The panel's own focus ring is drawn on the
// panel, not inside it, so clipping its children costs nothing. `clip` rather than `hidden`: this box
// is not a scroller, and `hidden` would leave one a script could move.
const PANEL = 'border border-border-strong bg-card rounded-xl overflow-clip'

export interface ListBoxProps<T> extends Omit<
  AriaListBoxProps<T>,
  | 'children'
  | 'className'
  | 'selectionMode'
  | 'selectedKeys'
  | 'defaultSelectedKeys'
  | 'onSelectionChange'
  | 'disabledKeys'
  | 'dragAndDropHooks'
> {
  /** `none`, `single` or `multiple`. A list box with no selection mode is a list of labels. */
  selectionMode?: AriaListBoxProps<T>['selectionMode']
  /** The chosen options, by each item's `id`. Controlled. */
  selectedKeys?: AriaListBoxProps<T>['selectedKeys']
  /** What starts chosen. Uncontrolled. */
  defaultSelectedKeys?: AriaListBoxProps<T>['defaultSelectedKeys']
  /** Called with the new set of keys. */
  onSelectionChange?: AriaListBoxProps<T>['onSelectionChange']
  /** Options that cannot be chosen. */
  disabledKeys?: AriaListBoxProps<T>['disabledKeys']
  /** Wires drag-and-drop, from React Aria's own `useDragAndDrop`. */
  dragAndDropHooks?: AriaListBoxProps<T>['dragAndDropHooks']
  className?: string
  children?: ReactNode
}

export interface ListBoxItemProps<T = object> extends Omit<
  AriaListBoxItemProps<T>,
  'className'
> {
  className?: string
}

export interface ListBoxSectionProps<T> extends Omit<
  AriaListBoxSectionProps<T>,
  'className'
> {
  className?: string
}

export interface ListBoxHeaderProps extends Omit<AriaHeaderProps, 'className'> {
  className?: string
}

export interface ListBoxLoadMoreProps extends Omit<
  AriaListBoxLoadMoreItemProps,
  'className'
> {
  className?: string
}

/**
 * One option. Use it as `ListBox.Item`.
 *
 * It carries the same class list the `Select` menu's options do, imported rather than copied — an option
 * that looks one way inside a select and another way in a list on the page would be one component wearing
 * two designs.
 */
export function ListBoxItem<T = object>({
  className,
  ...props
}: ListBoxItemProps<T>) {
  return (
    <AriaListBoxItem
      data-slot="list-box-item"
      className={[OPTION, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/** A named group of options. Use it as `ListBox.Section`. */
export function ListBoxSection<T>({
  className,
  ...props
}: ListBoxSectionProps<T>) {
  return <AriaListBoxSection className={className} {...props} />
}

/** A section's heading. Use it as `ListBox.Header`, inside a `ListBox.Section`. */
export function ListBoxHeader({ className, ...props }: ListBoxHeaderProps) {
  return (
    <AriaHeader
      data-slot="list-box-header"
      className={[
        'px-3.5 pt-3 pb-1 text-[11px] uppercase tracking-[0.08em] text-foreground/45',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
      {...props}
    />
  )
}

/**
 * The row that asks for the next page. Use it as `ListBox.LoadMore`, last inside `ListBox`.
 *
 * It only works inside a virtualized collection — see `gridlist.md` for the mechanism and the end-to-end
 * proof that it fires; this is the same sentinel on the same shared recipe.
 */
export function ListBoxLoadMore({
  className,
  children,
  ...props
}: ListBoxLoadMoreProps) {
  return (
    <AriaListBoxLoadMoreItem
      data-slot="list-box-load-more"
      className={[LOAD_MORE, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children ?? <LoadMoreSpinner />}
    </AriaListBoxLoadMoreItem>
  )
}

function ListBoxRoot<T>({ className, children, ...props }: ListBoxProps<T>) {
  return (
    <AriaListBox
      data-slot="list-box"
      className={[PANEL, OPTION_LIST, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaListBox>
  )
}

/**
 * A list of options where the choice is a value, not a set of rows.
 *
 * ```tsx
 * <ListBox aria-label="Region" selectionMode="single" defaultSelectedKeys={['fra']}>
 *   <ListBox.Item id="fra">Frankfurt</ListBox.Item>
 *   <ListBox.Item id="iad">Ashburn</ListBox.Item>
 * </ListBox>
 * ```
 *
 * **This is not `GridList`.** A grid list is a set of **rows** — a dashboard's monitors, a run of results
 * — where each row is a thing you look at and act on. A list box is a set of **options**, where the list's
 * whole purpose is to produce one value. The two look similar and answer different questions, which is
 * why both exist and why an option and a row are styled differently.
 *
 * It is what `Select`, `ComboBox` and `Menu` build their panels out of, so those already shared these
 * recipes; this is the same list standing on the page, with its own border rather than a popover's.
 */
export const ListBox = Object.assign(ListBoxRoot, {
  Item: ListBoxItem,
  Section: ListBoxSection,
  Header: ListBoxHeader,
  LoadMore: ListBoxLoadMore,
})

