  className?: string
}

/**
 * The surface the items sit on, and the list itself. Use it as `Menu.Popover`, as the second child of
 * a `Menu` — it draws both, because a popover with no list in it and a list with nowhere to open are
 * never useful apart, the same call `Select.Menu` makes.
 *
 * Exported as `MenuPopover` only so tooling can resolve it; consume the compound form
 * `Menu.Popover`.
 */
export function MenuPopover<T>({
  className,
  menuProps,
  children,
  ...props
}: MenuPopoverProps<T>) {
  return (
    <AriaPopover
      data-slot="menu"
      className={[POPOVER, className].filter(Boolean).join(' ')}
      {...props}
    >
      <AriaMenu className={LIST} {...menuProps}>
        {children}
      </AriaMenu>
    </AriaPopover>
  )
}

/**
 * One row. Use it as `Menu.Item` — with an `href` it is a link, with `onAction` on the menu it is an
 * action, and with a `SubmenuTrigger` inside it it opens again.
 *
 * Exported as `MenuItem` only so tooling can resolve it; consume the compound form `Menu.Item`.
 */
export function MenuItem<T = object>({
  className,
  children,
  ...props
}: MenuItemProps<T>) {
  return (
    <AriaMenuItem
      className={[ITEM, className].filter(Boolean).join(' ')}
      {...props}
    >
      {({ hasSubmenu }) => (
        <>
          <span className={ITEM_LABEL}>{children}</span>
          {hasSubmenu ? (
            <svg
              viewBox="0 0 10 10"
              fill="none"
              aria-hidden="true"
              className={`size-2.5 ${SUBMENU_CARET}`}
            >
              <path
                d="M3 1L7 5L3 9"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          ) : null}
        </>
      )}
    </AriaMenuItem>
  )
}

/**
 * A group of items. Use it as `Menu.Section`, with a `Menu.SectionTitle` at the top of it.
 *
 * Exported as `MenuSection` only so tooling can resolve it; consume the compound form `Menu.Section`.
 */
export function MenuSection<T>({ children, ...props }: MenuSectionProps<T>) {
  return (
    <AriaMenuSection className={SECTION} {...props}>
      {children}
    </AriaMenuSection>
  )
}

/**
 * A group's heading. Use it as `Menu.SectionTitle`.
 *
 * Exported as `MenuSectionTitle` only so tooling can resolve it; consume the compound form
 * `Menu.SectionTitle`.
 */
export function MenuSectionTitle({
  children,
  ...props
}: MenuSectionTitleProps) {
  return (
    <AriaHeader className={SECTION_TITLE} {...props}>
      {children}
    </AriaHeader>
  )
}

/**
 * The sheet's hairline, between two runs of items. Use it as `Menu.Separator`.
 *
 * Exported as `MenuSeparator` only so tooling can resolve it; consume the compound form
 * `Menu.Separator`.
 */
export function MenuSeparator({ className, ...props }: MenuSeparatorProps) {
  return (
    <AriaSeparator
      elementType="div"
      className={[SEPARATOR, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * Styled element. Not exported — `Menu` below is the public symbol, and docgen reads the JSDoc from
 * the *exported* declaration, not this one.
 */
function MenuRoot({ children, ...props }: MenuProps) {
  return <AriaMenuTrigger {...props}>{children}</AriaMenuTrigger>
}

/**
 * A menu of actions or choices, opened from a control. The surface is the sheet's
 * `.ds-select-menu`, shared with the select through `popover.ts`.
 *
 * ```tsx
 * <Menu>
 *   <Button>Actions</Button>
 *   <Menu.Popover menuProps={{ onAction: (key) => run(key) }}>
 *     <Menu.Item id="restart">Restart</Menu.Item>
 *     <Menu.Separator />
 *     <Menu.Item id="delete">Delete</Menu.Item>
 *   </Menu.Popover>
 * </Menu>
 * ```
 *
 * **A menu is a list of things to do, and it closes when you do one.** That is the difference between
 * it and a `Select`: a select keeps a value and says so in its trigger, while a menu performs an
 * action and goes away. `onAction` is the prop that says which this is — set it and the rows are
 * commands, leave it off and `selectionMode` makes them choices.
 *
 * React Aria does the parts a hand-rolled menu gets wrong: the popover is positioned against the
 * trigger and flips when it would run off the page, focus moves into the list and back out to the
 * trigger, the arrow keys walk it, Escape and a click outside dismiss it, and type-ahead jumps to a
 * row by its first letters.
 *
 * `Menu.Popover` carries the menu's own props — `selectionMode`, `disabledKeys`, `onAction` — so they
 * are written once rather than split across two slots. A submenu is a `SubmenuTrigger` inside a
 * `Menu.Item`; this component does not wrap it, because a submenu is a second menu and wrapping it
 * would have to answer questions the consumer has not been asked yet.
 */

/**
 * The row that asks for the next page. Use it as `Menu.LoadMore`, last inside `Menu`.
 *
 * A menu that runs long — a list of regions, a list of hundreds of actions — has no scrollbar a reader
 * can consult for how much is left. This is where the rest arrives.
 *
 * It only works inside a virtualized collection, draws nothing until `isLoading`, and React Aria renders
 * nothing at all for it when idle. `gridlist.md` carries the mechanism and the end-to-end proof that it
 * fires on scroll; this is the same sentinel on the same shared recipe.
 */
export function MenuLoadMore({
  className,
  children,
  ...props
}: AriaMenuLoadMoreItemProps) {
  return (
    <AriaMenuLoadMoreItem
      data-slot="menu-load-more"
      className={[LOAD_MORE, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children ?? <LoadMoreSpinner />}
    </AriaMenuLoadMoreItem>
  )
}

export const Menu = Object.assign(MenuRoot, {
  Popover: MenuPopover,
  LoadMore: MenuLoadMore,
  Item: MenuItem,
  Section: MenuSection,
  SectionTitle: MenuSectionTitle,
  Separator: MenuSeparator,
})

import { Meter as AriaMeter } from 'react-aria-components'
import type { MeterProps as AriaMeterProps } from 'react-aria-components'

import { createContext, useContext, useId } from 'react'
import type { ReactNode } from 'react'

import {
  FILL,
  HEADER,
  INDETERMINATE,
  LABEL,
  PROGRESS,
  TONE,
  TRACK,
  VALUE,
} from '../progress'

export interface MeterProps extends Omit<
  AriaMeterProps,
  'children' | 'className'
> {
  value?: AriaMeterProps['value']
  minValue?: AriaMeterProps['minValue']
  maxValue?: AriaMeterProps['maxValue']
  formatOptions?: AriaMeterProps['formatOptions']
  /**
   * What the reading means.
   *
   * There is no default that reads the value and picks a colour for you, because only the caller
   * knows which direction is the bad one: 80% of a disk used is a warning and 80% of a disk free is
   * not. Deriving it here would guess, and guess confidently.
   */
  tone?: keyof typeof TONE
  className?: string
  /** A `Meter.Label`, a `Meter.Track`, and whatever else it says. */
  children?: ReactNode
}

export interface MeterLabelProps {
  className?: string
  children?: ReactNode
}

/** The label and the reading on one line. */
export interface MeterHeaderProps {
  className?: string
  children?: ReactNode
}

export interface MeterValueProps {
  className?: string
  /** Overrides what React Aria formatted. Rarely wanted. */
  children?: ReactNode
}

export interface MeterTrackProps {
  className?: string
  children?: ReactNode
}

export interface MeterFillProps {
  /** Overrides the value React Aria computed. Rarely wanted. */
  percentage?: number
  tone?: keyof typeof TONE
  className?: string
}

/**
 * What the pieces inside a `Meter` need from the one outside it — the fraction, the formatted
 * reading and the id that names it. The same arrangement as `ProgressBar`, for the same reason: the
 * render props live inside the component so the slots can stay ordinary children.
 */
interface MeterContextValue {
  percentage?: number
  valueText?: string
  labelId: string
  /**
   * The tone has to travel too. It is set on the meter — one reading, one meaning — while the thing
   * it colours is the fill, and a first version left it out of the context: `tone="success"` on the
   * meter was silently ignored and every fill rendered neutral, which the `Tones` story caught by
   * finding five identical colours where it expected five.
   */
  tone: keyof typeof TONE
}

const MeterContext = createContext<MeterContextValue | null>(null)

/**
 * What the meter is measuring. Use it as `Meter.Label`. Its id is what names the widget, because
 * React Aria omits `label` on a meter and its `Label` child captions the drawing without naming it.
 *
 * Exported as `MeterLabel` only so tooling can resolve it; consume the compound form `Meter.Label`.
 */
export function MeterLabel({ className, children }: MeterLabelProps) {
  const ctx = useContext(MeterContext)
  return (
    <span
      id={ctx?.labelId}
      className={[LABEL, className].filter(Boolean).join(' ')}
    >
      {children}
    </span>
  )
}

/**
 * The line above the rail: the label on the left, the reading on the right. Use it as
 * `Meter.Header`.
 *
 * Exported as `MeterHeader` only so tooling can resolve it; consume the compound form `Meter.Header`.
 */
export function MeterHeader({ className, children }: MeterHeaderProps) {
  return (
    <div className={[HEADER, className].filter(Boolean).join(' ')}>
      {children}
    </div>
  )
}

/**
 * The reading. Use it as `Meter.Value` — with no children it renders the formatted value itself.
 *
 * Exported as `MeterValue` only so tooling can resolve it; consume the compound form `Meter.Value`.
 */
export function MeterValue({ className, children }: MeterValueProps) {
  const ctx = useContext(MeterContext)
  return (
    <span className={[VALUE, className].filter(Boolean).join(' ')}>
      {children ?? ctx?.valueText}
    </span>
  )
}

/**
 * The rail. Use it as `Meter.Track`, around a `Meter.Fill`.
 *
 * Exported as `MeterTrack` only so tooling can resolve it; consume the compound form `Meter.Track`.
 */
export function MeterTrack({ className, children }: MeterTrackProps) {
  return (
    <div className={[TRACK, className].filter(Boolean).join(' ')}>
      {children}
    </div>
  )
}

/**
 * The bar. Use it as `Meter.Fill`, inside a `Meter.Track`.
 *
 * Exported as `MeterFill` only so tooling can resolve it; consume the compound form `Meter.Fill`.
 */
export function MeterFill({ percentage, tone, className }: MeterFillProps) {
  const ctx = useContext(MeterContext)
  const value = percentage ?? ctx?.percentage
  const which = tone ?? ctx?.tone ?? 'neutral'
  return (
    <div
      data-slot="fill"
      style={{ '--fill': `${value ?? 100}%` } as React.CSSProperties}
      className={[
        FILL,
        TONE[which] ?? TONE.neutral,
        value === undefined ? INDETERMINATE : '',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
    />
  )
}

/**
 * Styled element. Not exported — `Meter` below is the public symbol, and docgen reads the JSDoc from
 * the *exported* declaration, not this one.
 */
function MeterRoot({
  tone = 'neutral',
  className,
  children,
  ...props
}: MeterProps) {
  const labelId = useId()
  return (
    <AriaMeter
      // Points at the label slot whether or not one was written — the same trade the modal makes for
      // its description, and for the same reason.
      aria-labelledby={labelId}
      className={[PROGRESS, className].filter(Boolean).join(' ')}
      {...props}
    >
      {({ percentage, valueText }) => (
        <MeterContext.Provider value={{ percentage, valueText, labelId, tone }}>
          {children}
        </MeterContext.Provider>
      )}
    </AriaMeter>
  )
}

/**
 * How much of something there is. A meter and a `ProgressBar` are the same drawing of two different
 * facts, which is why they share `progress.ts` — and why the difference is worth keeping rather than
 * collapsing into one component with a flag.
 *
 * ```tsx
 * <Meter value={82} tone={82 > 80 ? 'danger' : 'success'} className="w-72">
 *   <Meter.Header>
 *     <Meter.Label>Disk</Meter.Label>
 *     <Meter.Value />
 *   </Meter.Header>
 *   <Meter.Track>
 *     <Meter.Fill />
 *   </Meter.Track>
 * </Meter>
 * ```
 *
 * **A meter reports; a progress bar completes.** A progress bar's maximum is almost always 100% and
 * its accent means "getting there is good". A meter's reading is a fact about the world, and whether
 * it is good depends on what is being measured — 80% of a disk used is a warning, 80% of a disk free
 * is not. So `tone` is asked for rather than derived: the component would have to guess, and it would
 * guess confidently.
 *
 * The slots are ordinary children, as they are everywhere else here. React Aria hands `percentage`
 * and `valueText` to a **function** child, which would make this the one family whose consumer writes
 * a callback; the function lives inside the component instead and the slots read a context.
 */
export const Meter = Object.assign(MeterRoot, {
  Label: MeterLabel,
  Header: MeterHeader,
  Value: MeterValue,
  Track: MeterTrack,
  Fill: MeterFill,
})

import { createContext, useContext, useId } from 'react'
import {
  Button as AriaButton,
  Dialog as AriaDialog,
  DialogTrigger as AriaDialogTrigger,
  Heading as AriaHeading,
  Modal as AriaModal,
  ModalOverlay as AriaModalOverlay,
  Text as AriaText,
} from 'react-aria-components'
import type {
  ButtonProps as AriaButtonProps,
  DialogProps as AriaDialogProps,
  DialogTriggerProps as AriaDialogTriggerProps,
  HeadingProps as AriaHeadingProps,
  TextProps as AriaTextProps,
} from 'react-aria-components'

/**
 * The scrim. **The one place in this system where the palette deliberately does not reach.**
 *
 * A scrim's job is to push the page back, which means it has to *darken* — and there is no token
 * that darkens in both themes. `--color-ink` is black in the dark theme and white in the light one,
 * so it would haze a white page white and separate nothing; `--background` is black in one and white
 * in the other for the same reason. `black/50` is Tailwind's own, is the same in both themes by
 * design, and says exactly what it is.
 */
const OVERLAY = [
  // `place-items-center-safe`: a dialog taller than the viewport is centered *safely*, so its top
  // stays reachable instead of overflowing past the block-start edge, where no scroll can get to
  // it. The dialog's own `max-h` below is what keeps that case rare.
  'fixed inset-0 z-50 grid place-items-center-safe overflow-y-auto overscroll-contain p-4',
  'bg-black/50',
].join(' ')

/**
 * The sheet's `.ds-panel`, with an edge: a dialog floats over a page, so it needs the same separation
 * the tooltip and the toast do — its own panel, and a hairline to say where it ends.
 */
const DIALOG = [
  // **A limit, or the dialog has none.** Before this it was `w-full max-w-md` and nothing else,
  // so a dialog longer than the screen pushed its own title off the top and its footer off the
  // bottom, and the overlay's scroller could not reach either. Capped, it scrolls inside itself.
  'relative max-h-[90dvh] w-full max-w-md overflow-y-auto overscroll-contain',
  'border border-border-strong bg-card rounded-xl p-6',
  'outline-1 -outline-offset-2 outline-transparent',
  // **`:focus-visible`, not `data-[focus-visible]`.** React Aria's `Dialog` emits no data
  // attributes of its own — no `data-focus-visible` among them — so a rule keyed on that attribute
  // is inert on this element. Measured: the dialog matches `:focus-visible` and was left with a
  // transparent outline. The controls inside it are real buttons and keep the data attribute.
  'focus-visible:outline-ring',
].join(' ')

/** The sheet's `.ds-panel-title`: 18px/600, measured off its Page Check reference. */
export const DIALOG_TITLE =
  'm-0 text-[18px] font-semibold tracking-[0.01em] text-foreground'

export const DIALOG_DESCRIPTION =
  'mbs-2 text-[13px] leading-[1.5] text-foreground/70'

export const DIALOG_FOOTER = 'mbs-6 flex items-center justify-end gap-3'

/** The same dismiss control the toast draws, for the same reason: it is the one that is often missed. */
export const DIALOG_CLOSE = [
  'absolute end-4 inset-bs-4 grid size-5 cursor-pointer place-items-center',
  'text-foreground/45',
  'transition-[color,opacity] duration-(--duration-fast) ease-pulse',
  // A 20px × is a 20px target. The pseudo-element makes it 44 without moving the glyph, inside the
  // dialog's 24px padding.
  'after:absolute after:content-[""] after:-inset-3',
  'data-[hovered]:text-foreground',
  'data-[pressed]:opacity-70',
  'data-[focus-visible]:outline-1 data-[focus-visible]:outline-offset-2',
  'data-[focus-visible]:outline-ring',
].join(' ')

export interface ModalProps extends Omit<
  AriaDialogTriggerProps,
  'children' | 'className' | 'isOpen' | 'defaultOpen' | 'onOpenChange'
> {
  /**
   * Whether the dialog is open. This is a React Aria prop on the trigger — controlled state, so pass
   * `onOpenChange` with it.
   */
  isOpen?: AriaDialogTriggerProps['isOpen']
  /** Whether the dialog starts open, for uncontrolled use. */
  defaultOpen?: AriaDialogTriggerProps['defaultOpen']
  /** Called when the dialog asks to open or close. */
  onOpenChange?: AriaDialogTriggerProps['onOpenChange']

  /** The trigger, then a `Modal.Content`. */
  children?: React.ReactNode
}

export interface ModalContentProps extends Omit<
  AriaDialogProps,
  'children' | 'className'
> {
  className?: string
  /** A `Modal.Title`, the body, and a `Modal.Footer`. */
  children?: React.ReactNode
}

export interface ModalTitleProps extends AriaHeadingProps {
  children?: React.ReactNode
}

export interface ModalDescriptionProps extends AriaTextProps {
  children?: React.ReactNode
}

export interface ModalFooterProps {
  className?: string
  children?: React.ReactNode
}

export interface ModalCloseProps extends Omit<
  AriaButtonProps,
  'children' | 'className' | 'slot'
> {
  className?: string
  children?: React.ReactNode
}

/**
 * The description's id, shared between the dialog and the `Text` inside it. React Aria wires the
 * **title** to the dialog for you — `aria-labelledby` appears on its own — but it does not wire the
 * description, and a description nobody is pointed at is decoration. The id is generated here and
 * passed down rather than written by the consumer, who would have to keep two things in step.
 */
const DescriptionId = createContext<string | undefined>(undefined)

/**
 * The dialog's surface, its scrim and its placement, in one slot. Use it as `Modal.Content`, as the
 * second child of a `Modal`.
 *
 * Exported as `ModalContent` only so tooling can resolve it; consume the compound form
 * `Modal.Content`.
 */
export function ModalContent({
  className,
  children,
  ...props
}: ModalContentProps) {
  const descriptionId = useId()
  return (
    <AriaModalOverlay data-slot="modal" className={OVERLAY} isDismissable>
      <AriaModal className="w-full max-w-md">
        <DescriptionId.Provider value={descriptionId}>
          <AriaDialog
            // Points at the description whether or not one was passed. A dialog with a dangling
            // `aria-describedby` is a smaller thing than a description nobody reads.
            aria-describedby={descriptionId}
            className={[DIALOG, className].filter(Boolean).join(' ')}
            {...props}
          >
            {children}
          </AriaDialog>
        </DescriptionId.Provider>
      </AriaModal>
    </AriaModalOverlay>
  )
}

/**
 * What the dialog is about. Use it as `Modal.Title`. It is the sheet's `.ds-panel-title`, and it is
 * what names the dialog — React Aria wires it to the dialog's `aria-labelledby`, so the title is not
 * decoration.
 *
 * Exported as `ModalTitle` only so tooling can resolve it; consume the compound form `Modal.Title`.
 */
export function ModalTitle({ className, children, ...props }: ModalTitleProps) {
  return (
    <AriaHeading
      slot="title"
      className={[DIALOG_TITLE, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaHeading>
  )
}

/**
 * A sentence under the title. Use it as `Modal.Description` — it becomes the dialog's
 * `aria-describedby`, so a screen reader hears what the dialog is for before it hears the controls.
 *
 * Exported as `ModalDescription` only so tooling can resolve it; consume the compound form
 * `Modal.Description`.
 */
export function ModalDescription({
  className,
  children,
  ...props
}: ModalDescriptionProps) {
  const id = useContext(DescriptionId)
  return (
    <AriaText
      id={id}
      slot="description"
      className={[DIALOG_DESCRIPTION, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaText>
  )
}

/**
 * The actions, right-aligned. Use it as `Modal.Footer`.
 *
 * Exported as `ModalFooter` only so tooling can resolve it; consume the compound form
 * `Modal.Footer`.
 */
export function ModalFooter({ className, children }: ModalFooterProps) {
  return (
    <div className={[DIALOG_FOOTER, className].filter(Boolean).join(' ')}>
      {children}
    </div>
  )
}

/**
 * The **×** in the corner. Use it as `Modal.Close` — it is absolutely positioned, so it belongs to
 * the dialog rather than to a footer.
 *
 * Its `slot="close"` is what tells React Aria it is a dismiss control, and that attribute is the
 * whole mechanism: putting it on **any** button closes the dialog. A footer that says "Cancel"
 * rather than "×" therefore wants a plain `Button` with the same `slot`, not this — a first version of
 * the story used `Modal.Close` in its footer and the word flew to the top-right corner, because
 * `position: absolute` goes where it is told.
 *
 * Exported as `ModalClose` only so tooling can resolve it; consume the compound form
 * `Modal.Close`.
 */
export function ModalClose({ className, children, ...props }: ModalCloseProps) {
  return (
    <AriaButton
      slot="close"
      aria-label="Close"
      className={[DIALOG_CLOSE, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children ?? (
        <svg
          viewBox="0 0 10 10"
          fill="none"
          aria-hidden="true"
          className="size-2.5"
        >
          <path
            d="M1 1L9 9M9 1L1 9"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
          />
        </svg>
      )}
    </AriaButton>
  )
}

/**
 * Styled element. Not exported — `Modal` below is the public symbol, and docgen reads the JSDoc from
 * the *exported* declaration, not this one.
 */
function ModalRoot({ children, ...props }: ModalProps) {
  return <AriaDialogTrigger {...props}>{children}</AriaDialogTrigger>
}

/**
 * A dialog over the page: a short task that needs an answer before the page can be used again.
 *
 * ```tsx
 * <Modal>
 *   <Button>New monitor</Button>
 *   <Modal.Content>
 *     <Modal.Title>New monitor</Modal.Title>
 *     <Modal.Description>It starts checking as soon as you save.</Modal.Description>
 *     <Modal.Footer>
 *       <Modal.Close>Cancel</Modal.Close>
 *       <Button variant="primary">Save</Button>
 *     </Modal.Footer>
 *   </Modal.Content>
 * </Modal>
 * ```
 *
 * **A modal is a demand, so it should be rare.** It takes the page away, traps focus, and stops
 * anyone reading behind it — which is the right trade for a decision that has to be made now, and
 * the wrong one for a form someone might want to consult the page while filling in. A `Popover` is
 * the same dialog without that cost, and the sheet's own menus are popovers.
 *
 * React Aria does the parts a hand-rolled dialog gets wrong: the scrim, focus trapped inside and
 * restored to the trigger on close, Escape to dismiss, a click outside to dismiss, the page behind
 * made inert to a screen reader, and the scroll locked without the page jumping as the bar
 * disappears. `Modal.Close` writes its own `slot="close"` for the same reason `Toast.Close` does.
 *
 * The scrim is the one place in this system where the palette deliberately does not reach, and it
 * says so above.
 */
export const Modal = Object.assign(ModalRoot, {
  Content: ModalContent,
  Title: ModalTitle,
  Description: ModalDescription,
  Footer: ModalFooter,
  Close: ModalClose,
})

import {
  Button as AriaButton,
  FieldError as AriaFieldError,
  Group as AriaGroup,
  Input as AriaInput,
  Label as AriaLabel,
  NumberField as AriaNumberField,
  Text as AriaText,
} from 'react-aria-components'
import type {
  FieldErrorProps as AriaFieldErrorProps,
  GroupProps as AriaGroupProps,
  InputProps as AriaInputProps,
  LabelProps as AriaLabelProps,
  NumberFieldProps as AriaNumberFieldProps,
  TextProps as AriaTextProps,
} from 'react-aria-components'

import { ERROR, FIELD, FIELD_SIZES, GROUP, HINT, INPUT, LABEL } from '../field'
import type { FieldSize } from '../field'

/**
 * The sheet has no number field — only a number's *typography*, in `.ds-num`, `.ds-num-sm` and
 * `.ds-num-alt`. So the field is the shared anatomy every control here uses, and the sheet's
 * contribution is the type: its numbers are letterspaced and, being mono, already tabular, which is
 * what makes a column of figures line up.
 *
 * The yellow stays with the readouts. `.ds-num` is an accent because a number in the sheet's
 * dashboard *is* the point of the row; a number being typed is one value among the others on the
 * form, and a field that shouts is a field nobody can read alongside its neighbours.
 */
const NUMBER_INPUT = [
  INPUT,
  // Tabular and letterspaced, the sheet's numeric signature — so the digits do not shuffle sideways
  // as they are typed, and a column of them lines up.
  'tabular-nums tracking-[0.35px]',
].join(' ')

/**
 * The trailing unit, the way the sheet builds one.
 *
 * It is **inside** the field, not beside it: the sheet's `.ds-input--unit` pads the input on that
 * side and its `.ds-unit` sits over the padding. Putting the buttons *after* the input instead
 * pushes them outside the border, because the shared `INPUT` is `w-full` — the one class a control
 * cannot argue with in a flex row, since both are `width` utilities and Tailwind's order, not the
 * author's, decides between them.
 *
 * `data-slot="counter"` is what asks the Group for the padding, through a rule `NumberField` adds
 * for itself rather than one `field.ts` has to know about. The two halves **stack**, so the unit is
 * a column the height of the field: that is the shape a spinner is read in, and `+` is on top for
 * the same reason it is on every other one.
 */
const COUNTER = [
  'absolute inset-y-0 end-0 z-10 flex w-8 flex-col',
  'border-s border-(--field-border)',
].join(' ')

const STEPPER = [
  'flex flex-1 items-center justify-center',
  'cursor-pointer text-foreground/70',
  'transition-colors duration-(--duration-fast) ease-pulse',
  'data-[hovered]:bg-foreground/5 data-[hovered]:text-foreground',
  'data-[focus-visible]:outline-1 data-[focus-visible]:outline-offset-[-3px]',
  'data-[focus-visible]:outline-ring',
  'data-[disabled]:cursor-not-allowed data-[disabled]:opacity-35',
].join(' ')

/** The hairline between the two halves — the same divider the sheet draws between an input and its affix. */
const STEPPER_DIVIDE = 'border-b border-(--field-border)'

/** The sheet's caret, at 1.5 stroke, turned to point up and down. */
const ARROW = 'h-1 w-1.5'

function Stepper({ points }: { points: 'up' | 'down' }) {
  return (
    <svg viewBox="0 0 10 6" fill="none" aria-hidden="true" className={ARROW}>
      <path
        d="M1 1L5 5L9 1"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        transform={points === 'up' ? 'rotate(180 5 3)' : undefined}
      />
    </svg>
  )
}

export interface NumberFieldProps extends Omit<
  AriaNumberFieldProps,
  | 'isDisabled'
  | 'isReadOnly'
  | 'isRequired'
  | 'isInvalid'
  | 'children'
  | 'className'
> {
  /** React 19 passes `ref` as an ordinary prop, so no `forwardRef` wrapper. */
  ref?: React.Ref<HTMLDivElement>
  /** Sizes the control the same way a field is sized, through the shared tokens. */
  size?: FieldSize
  /** Disables the control. This is a React Aria prop — there is no `disabled`. */
  isDisabled?: AriaNumberFieldProps['isDisabled']
  isReadOnly?: AriaNumberFieldProps['isReadOnly']
  isRequired?: AriaNumberFieldProps['isRequired']
  isInvalid?: AriaNumberFieldProps['isInvalid']
  /** The value is a number, or `null` for empty. Not a string. */
  value?: AriaNumberFieldProps['value']
  defaultValue?: AriaNumberFieldProps['defaultValue']
  onChange?: AriaNumberFieldProps['onChange']
  /** What one press of a stepper, or one press of an arrow key, is worth. */
  step?: AriaNumberFieldProps['step']
  minValue?: AriaNumberFieldProps['minValue']
  maxValue?: AriaNumberFieldProps['maxValue']
  /** How the value is formatted when the field is not being edited — a currency, a percentage. */
  formatOptions?: AriaNumberFieldProps['formatOptions']
  /**
   * Stops a scroll over the field from changing it. Worth turning on inside anything scrollable,
   * where a wheel meant for the page silently edits a number on the way past.
   */
  isWheelDisabled?: AriaNumberFieldProps['isWheelDisabled']
  className?: string
  /** `NumberField.Label`, `NumberField.Group`, then the hint and error. */
  children?: React.ReactNode
}

export interface NumberFieldLabelProps extends AriaLabelProps {
  children?: React.ReactNode
}

/**
 * The room the counter takes. A rule `NumberField` owns rather than one in `field.ts`, because a
 * counter is this component's affix and a text field has no use for it. 36px against the counter's
 * 32, so the value never touches the divider.
 */
const COUNTER_GUTTER = 'has-[[data-slot=counter]]:[&>[data-slot=input]]:pe-9'

export interface NumberFieldGroupProps extends Omit<
  AriaGroupProps,
  'className'
> {
  className?: string
  children?: React.ReactNode
}

export interface NumberFieldInputProps extends Omit<
  AriaInputProps,
  'children' | 'className' | 'value' | 'defaultValue' | 'onChange'
> {
  className?: string
}

export interface NumberFieldCounterProps {
  className?: string
  /** Replaces the pair of arrows. Rarely wanted, and it is two children, not one. */
  children?: React.ReactNode
}

export interface NumberFieldHintProps extends AriaTextProps {
  children?: React.ReactNode
}

export interface NumberFieldFieldErrorProps extends AriaFieldErrorProps {
  /** The message, or a function of the field's validation result. */
  children?: AriaFieldErrorProps['children']
}

/**
 * The legend. Use it as `NumberField.Label`. The required marker comes from the field's own
 * `data-required`, so it cannot drift out of sync with `isRequired`.
 *
 * Exported as `NumberFieldLabel` only so tooling can resolve it; consume the compound form
 * `NumberField.Label`.
 */
export function NumberFieldLabel({
  className,
  children,
  ...props
}: NumberFieldLabelProps) {
  return (
    <AriaLabel
      className={[LABEL, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaLabel>
  )
}

/**
 * Wraps the input and its steppers. Use it as `NumberField.Group`.
 *
 * Exported as `NumberFieldGroup` only so tooling can resolve it; consume the compound form
 * `NumberField.Group`.
 */
export function NumberFieldGroup({
  className,
  children,
  ...props
}: NumberFieldGroupProps) {
  return (
    <AriaGroup
      className={[GROUP, COUNTER_GUTTER, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaGroup>
  )
}

/**
 * The number. Use it as `NumberField.Input`. It is a text input underneath, so it can be typed
 * into, selected and undone like one — React Aria does the parsing and the formatting around it.
 *
 * Exported as `NumberFieldInput` only so tooling can resolve it; consume the compound form
 * `NumberField.Input`.
 */
export function NumberFieldInput({
  className,
  ...props
}: NumberFieldInputProps) {
  return (
    <AriaInput
      data-slot="input"
      className={[NUMBER_INPUT, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * The steppers. Use it as `NumberField.Counter`: one slot rather than two, because they are one
 * control — two halves of a single column, which is how a spinner is read. Splitting them into
 * `.Increment` and `.Decrement` invited a consumer to lay them out side by side, which is a
 * different and worse thing.
 *
 * `slot="increment"` and `slot="decrement"` are written here rather than left to the consumer, for
 * the same reason `Table.Selection` writes `slot="selection"`: the one attribute that makes it work
 * is the one nobody remembers, and getting it wrong still renders.
 *
 * Exported as `NumberFieldCounter` only so tooling can resolve it; consume the compound form
 * `NumberField.Counter`.
 */
export function NumberFieldCounter({
  className,
  children,
}: NumberFieldCounterProps) {
  return (
    <div
      data-slot="counter"
      className={[COUNTER, className].filter(Boolean).join(' ')}
    >
      {children ?? (
        <>
          {/* Up on top, the way every other spinner on the platform does it. */}
          <AriaButton
            slot="increment"
            className={`${STEPPER} ${STEPPER_DIVIDE}`}
          >
            <Stepper points="up" />
          </AriaButton>
          <AriaButton slot="decrement" className={STEPPER}>
            <Stepper points="down" />
          </AriaButton>
        </>
      )}
    </div>
  )
}

/**
 * The guidance under the control. Use it as `NumberField.Hint`.
 *
 * Exported as `NumberFieldHint` only so tooling can resolve it; consume the compound form
 * `NumberField.Hint`.
 */
export function NumberFieldHint({
  className,
  children,
  ...props
}: NumberFieldHintProps) {
  return (
    <AriaText
      slot="description"
      className={[HINT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaText>
  )
}

/**
 * The message shown when the field is `isInvalid`. Use it as `NumberField.Error`.
 *
 * Exported as `NumberFieldFieldError` only so tooling can resolve it; consume the compound form
 * `NumberField.Error`.
 */
export function NumberFieldFieldError({
  className,
  ...props
}: NumberFieldFieldErrorProps) {
  return (
    <AriaFieldError
      className={[ERROR, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * Styled element. Not exported — `NumberField` below is the public symbol, and docgen reads the
 * JSDoc from the *exported* declaration, not this one.
 */
function NumberFieldRoot({
  ref,
  size = 'md',
  className,
  children,
  ...props
}: NumberFieldProps) {
  return (
    <AriaNumberField
      ref={ref}
      className={[FIELD, FIELD_SIZES[size], className]
        .filter(Boolean)
        .join(' ')}
      {...props}
    >
      {children}
    </AriaNumberField>
  )
}

/**
 * A number — typed, stepped, or scrolled. The sheet has no number field in it, only a number's
 * *typography*, so the field is the shared anatomy and the sheet supplies the type: its numbers are
 * letterspaced and tabular, which is what makes a column of figures line up.
 *
 * ```tsx
 * <NumberField defaultValue={60} minValue={5} maxValue={600}>
 *   <NumberField.Label>Interval</NumberField.Label>
 *   <NumberField.Group>
 *     <NumberField.Input />
 *     <NumberField.Counter />
 *   </NumberField.Group>
 *   <NumberField.Hint>Seconds between checks.</NumberField.Hint>
 * </NumberField>
 * ```
 *
 * **The value is a number, not a string.** `onChange` gives a number or `null` — `null` for empty,
 * which is a real state a field has to be able to hold rather than a zero it did not mean.
 *
 * Two things React Aria does that make this worth not hand-rolling: the field stays a **text input**
 * underneath, so it can be typed, selected and undone like one while the parsing and formatting
 * happen around it; and `formatOptions` is what turns that into a currency or a percentage, so the
 * same field is a money field when it needs to be.
 *
 * `isWheelDisabled` is worth turning on inside anything scrollable — a wheel meant for the page
 * silently editing a number as it goes past is a small trap with no undo.
 */
export const NumberField = Object.assign(NumberFieldRoot, {
  Label: NumberFieldLabel,
  Group: NumberFieldGroup,
  Input: NumberFieldInput,
  Counter: NumberFieldCounter,
  Hint: NumberFieldHint,
  Error: NumberFieldFieldError,
})

import {
  Dialog as AriaDialog,
  DialogTrigger as AriaDialogTrigger,
  Heading as AriaHeading,
  Popover as AriaPopover,
  Text as AriaText,
} from 'react-aria-components'
import type {
  DialogTriggerProps as AriaDialogTriggerProps,
  HeadingProps as AriaHeadingProps,
  PopoverProps as AriaPopoverProps,
  TextProps as AriaTextProps,
} from 'react-aria-components'
import { OverlayArrow } from '../OverlayArrow/OverlayArrow'

import { createContext, useContext, useId } from 'react'
import type { ReactNode } from 'react'

import { DIALOG_DESCRIPTION, DIALOG_TITLE } from '../Modal/Modal'
import { SURFACE } from '../popover'

export interface PopoverProps extends Omit<
  AriaDialogTriggerProps,
  'children' | 'className' | 'isOpen' | 'defaultOpen' | 'onOpenChange'
> {
  /**
   * Whether the panel is open. This is a React Aria prop on the trigger — controlled state, so pass
   * `onOpenChange` with it.
   */
  isOpen?: AriaDialogTriggerProps['isOpen']
  /** Whether the panel starts open, for uncontrolled use. */
  defaultOpen?: AriaDialogTriggerProps['defaultOpen']
  /** Called when the panel asks to open or close. */
  onOpenChange?: AriaDialogTriggerProps['onOpenChange']

  /** The trigger, then a `Popover.Content`. */
  children?: ReactNode
}

export interface PopoverContentProps extends Omit<
  AriaPopoverProps,
  'children' | 'className'
> {
  className?: string
  children?: ReactNode
}

export interface PopoverTitleProps extends Omit<AriaHeadingProps, 'className'> {
  className?: string
}

export interface PopoverDescriptionProps extends Omit<
  AriaTextProps,
  'className'
> {
  className?: string
}

/**
 * The id the panel is described by. React Aria wires `aria-labelledby` from the title on its own and
 * does **not** wire a description — the same gap the modal has, and the same fix.
 */
const DescriptionId = createContext<string | undefined>(undefined)

/**
 * The panel itself. Use it as `Popover.Content`, as the second child of a `Popover`.
 *
 * **It is a dialog that does not take the page.** React Aria's `Popover` is non-modal by default, so
 * focus is not trapped and the page behind stays readable and clickable — which is the whole reason to
 * reach for this over a `Modal`. Dismissing on Escape and on an outside click still works.
 *
 * The surface is `popover.ts`'s — the same hairline, square corners and one shadow the menus wear — but
 * **not** `POPOVER` itself, which is `w-(--trigger-width)`: that is right for a select matched to its
 * field and wrong for a panel with its own idea of how wide it should be.
 *
 * Exported as `PopoverContent` only so tooling can resolve it; consume the compound form
 * `Popover.Content`.
 */
export function PopoverContent({
  className,
  children,
  ...props
}: PopoverContentProps) {
  const id = useId()
  return (
    <AriaPopover
      data-slot="popover"
      className={[SURFACE, 'focus-visible:outline-ring', className]
        .filter(Boolean)
        .join(' ')}
      {...props}
    >
      <AriaDialog
        aria-describedby={id}
        className="flex flex-col gap-3 p-4 outline-1 -outline-offset-2 outline-transparent focus-visible:outline-ring"
      >
        <DescriptionId.Provider value={id}>{children}</DescriptionId.Provider>
      </AriaDialog>
    </AriaPopover>
  )
}

/**
 * The panel's title. Use it as `Popover.Title` — the modal's own title type, imported rather than
 * copied, because a popover and a dialog are the same thing at different weights.
 *
 * Exported as `PopoverTitle` only so tooling can resolve it; consume the compound form
 * `Popover.Title`.
 */
export function PopoverTitle({ className, ...props }: PopoverTitleProps) {
  return (
    <AriaHeading
      slot="title"
      className={[DIALOG_TITLE, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * A sentence under the title. Use it as `Popover.Description` — its id is wired to the panel's
 * `aria-describedby` here, because React Aria does not.
 *
 * Exported as `PopoverDescription` only so tooling can resolve it; consume the compound form
 * `Popover.Description`.
 */
export function PopoverDescription({
  className,
  ...props
}: PopoverDescriptionProps) {
  return (
    <AriaText
      slot="description"
      id={useContext(DescriptionId)}
      className={[DIALOG_DESCRIPTION, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

function PopoverRoot({ children, ...props }: PopoverProps) {
  return <AriaDialogTrigger {...props}>{children}</AriaDialogTrigger>
}

/**
 * A panel anchored to the thing that opened it, that does not take the page away.
 *
 * ```tsx
 * <Popover>
 *   <Button>Filters</Button>
 *   <Popover.Content placement="bottom start">
 *     <Popover.Title>Filters</Popover.Title>
 *     <Popover.Description>Applies to this view only.</Popover.Description>
 *   </Popover.Content>
 * </Popover>
 * ```
 *
 * **A popover is a modal that is not modal**, and that is the whole decision. It is dismissed by
 * Escape and by a click outside, but it traps nothing and hides nothing: the page behind it stays
 * readable and usable, so someone can consult it while they work. Reach for `Modal` when the page is
 * irrelevant to the decision and for this when it is the context.
 *
 * **Placement is React Aria's, and it flips by itself.** `placement="bottom start"` is a request rather
 * than an instruction: near the bottom of the viewport the panel opens upwards, and near the edge it
 * shifts along, so the screen reader announces where it actually landed.
 *
 * It is what `Menu`, `Select` and `ComboBox` are built on, each adding the list and the trigger
 * behaviour it needs. This is the same surface with no list at all — for an explanation, a filter form,
 * or a small action set that is not a menu.
 */

/**
 * The marker pointing back at the trigger. Use it as `Popover.Arrow`.
 *
 * **Opt-in, and nothing here uses it.** The design language's panels are flat and anchored by proximity;
 * see `OverlayArrow` for why the shape exists at all and what it is made of.
 */
export function PopoverArrow({ className }: { className?: string }) {
  return <OverlayArrow className={className} />
}

export const Popover = Object.assign(PopoverRoot, {
  Arrow: PopoverArrow,
  Content: PopoverContent,
  Title: PopoverTitle,
  Description: PopoverDescription,
})

import { ProgressBar as AriaProgressBar } from 'react-aria-components'
import type { ProgressBarProps as AriaProgressBarProps } from 'react-aria-components'

import { createContext, useContext, useId } from 'react'
import type { ReactNode } from 'react'

import {
  FILL,
  HEADER,
  INDETERMINATE,
  LABEL,
  PROGRESS,
  TONE,
  TRACK,
  VALUE,
} from '../progress'

export interface ProgressBarProps extends Omit<
  AriaProgressBarProps,
  'children' | 'className'
> {
  /** The value, or omit it for one that is still being worked out. */
  value?: AriaProgressBarProps['value']
  minValue?: AriaProgressBarProps['minValue']
  maxValue?: AriaProgressBarProps['maxValue']
  /** How the reading is written — a percentage by default, a byte count or a duration if you say so. */
  formatOptions?: AriaProgressBarProps['formatOptions']
  /** No value to show: the rail fills and pulses instead of measuring. */
  isIndeterminate?: AriaProgressBarProps['isIndeterminate']
  /** Extra props for the widget itself, `aria-label` among them. */
  className?: string
  /** A `ProgressBar.Label`, a `ProgressBar.Track`, and whatever else it says. */
  children?: ReactNode
}

export interface ProgressLabelProps {
  className?: string
  children?: ReactNode
}

export interface ProgressValueProps {
  className?: string
  /** Overrides what React Aria formatted. Rarely wanted. */
  children?: ReactNode
}

/** The label and the reading on one line — the sheet's own arrangement in a table row. */
export interface ProgressHeaderProps {
  className?: string
  children?: ReactNode
}

export interface ProgressTrackProps {
  className?: string
  children?: ReactNode
}

export interface ProgressFillProps {
  /** Overrides the value React Aria computed. Rarely wanted. */
  percentage?: number
  /** Which of the system's colours it is filled with. */
  tone?: keyof typeof TONE
  className?: string
}

/**
 * What the pieces inside a `ProgressBar` need from the one outside it: the fraction, the formatted
 * reading, and the id that ties the label to the widget.
 *
 * This is what lets the slots be ordinary children rather than a render-prop function. React Aria
 * hands `percentage` and `valueText` to a **function** child, which would make this the one
 * component here whose consumer writes a callback instead of slots — so the function lives inside
 * the component and the slots read the result from here. The same arrangement as `Nav.Label`
 * reading its chevron's state, for the same reason.
 */
interface ProgressContextValue {
  percentage?: number
  valueText?: string
  labelId: string
}

const ProgressContext = createContext<ProgressContextValue | null>(null)

/**
 * What the bar is measuring. Use it as `ProgressBar.Label`. Its id is what names the widget —
 * React Aria omits `label` on a progress bar and its `Label` child is a caption that does not
 * register itself, so the name is wired here.
 *
 * Exported as `ProgressLabel` only so tooling can resolve it; consume the compound form
 * `ProgressBar.Label`.
 */
export function ProgressLabel({ className, children }: ProgressLabelProps) {
  const ctx = useContext(ProgressContext)
  return (
    <span
      id={ctx?.labelId}
      className={[LABEL, className].filter(Boolean).join(' ')}
    >
      {children}
    </span>
  )
}

/**
 * The reading, as React Aria formats it. Use it as `ProgressBar.Value` — with no children it renders
 * the formatted value itself.
 *
 * Exported as `ProgressValue` only so tooling can resolve it; consume the compound form
 * `ProgressBar.Value`.
 */
export function ProgressValue({ className, children }: ProgressValueProps) {
  const ctx = useContext(ProgressContext)
  return (
    <span className={[VALUE, className].filter(Boolean).join(' ')}>
      {children ?? ctx?.valueText}
    </span>
  )
}

/**
 * The line above the rail: the label on the left, the reading on the right. Use it as
 * `ProgressBar.Header`. The arrangement is a slot rather than something the component does for you,
 * so a bar can be labelled any way its page needs one.
 *
 * Exported as `ProgressHeader` only so tooling can resolve it; consume the compound form
 * `ProgressBar.Header`.
 */
export function ProgressHeader({ className, children }: ProgressHeaderProps) {
  return (
    <div className={[HEADER, className].filter(Boolean).join(' ')}>
      {children}
    </div>
  )
}

/**
 * The rail. Use it as `ProgressBar.Track`, around a `ProgressBar.Fill`.
 *
 * Exported as `ProgressTrack` only so tooling can resolve it; consume the compound form
 * `ProgressBar.Track`.
 */
export function ProgressTrack({ className, children }: ProgressTrackProps) {
  return (
    <div className={[TRACK, className].filter(Boolean).join(' ')}>
      {children}
    </div>
  )
}

/**
 * The bar itself. Use it as `ProgressBar.Fill`, inside a `ProgressBar.Track`. Its width is the
 * percentage React Aria computed, handed over as `--fill` so the width stays a utility and the only
 * thing written inline is the number.
 *
 * Exported as `ProgressFill` only so tooling can resolve it; consume the compound form
 * `ProgressBar.Fill`.
 */
export function ProgressFill({
  percentage,
  tone = 'accent',
  className,
}: ProgressFillProps) {
  const ctx = useContext(ProgressContext)
  const value = percentage ?? ctx?.percentage
  return (
    <div
      data-slot="fill"
      // A custom property needs the cast: React's `CSSProperties` has no index signature, and its
      // absence would mean writing the width as an inline style — a measurement in the one place
      // this system keeps them all in classes.
      style={{ '--fill': `${value ?? 100}%` } as React.CSSProperties}
      className={[
        FILL,
        TONE[tone] ?? TONE.accent,
        value === undefined ? INDETERMINATE : '',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
    />
  )
}

/**
 * Styled element. Not exported — `ProgressBar` below is the public symbol, and docgen reads the
 * JSDoc from the *exported* declaration, not this one.
 */
function ProgressBarRoot({ className, children, ...props }: ProgressBarProps) {
  const labelId = useId()
  return (
    <AriaProgressBar
      // Points at the label slot whether or not one was written, for the reason the modal does the
      // same with its description: a dangling id is a smaller thing than an unnamed widget.
      aria-labelledby={labelId}
      className={[PROGRESS, className].filter(Boolean).join(' ')}
      {...props}
    >
      {({ percentage, valueText }) => (
        <ProgressContext.Provider value={{ percentage, valueText, labelId }}>
          {children}
        </ProgressContext.Provider>
      )}
    </AriaProgressBar>
  )
}

/**
 * How far along something is. **The sheet has no bar in it**, so this is an invention — a small one
 * that borrows its language: square, 4px, and the system's own accent.
 *
 * ```tsx
 * <ProgressBar value={72} className="w-72">
 *   <ProgressBar.Label>Uptime</ProgressBar.Label>
 *   <ProgressBar.Track>
 *     <ProgressBar.Fill />
 *   </ProgressBar.Track>
 * </ProgressBar>
 * ```
 *
 * **A progress bar is not a meter**, and the difference is not decoration. A progress bar says how
 * far along an operation is, and its maximum is almost always 100% — it wears the accent, because
 * finishing is the good news. A `Meter` says how much of something there is, and how much is *not*
 * the good news: that is what the four semantic colours are for.
 *
 * The `percentage` and the formatted `valueText` come from React Aria as render props, and this
 * component is the one place they are read: it puts them in a context so `ProgressBar.Fill` and
 * `ProgressBar.Value` are ordinary slots rather than a callback the consumer has to write. A first
 * version took a `label` prop and rendered every piece itself, which made this the only component
 * here whose consumer did not write the slots.
 *
 * `value` is a **number, not a string**, and `undefined` is a real state rather than a zero: React
 * Aria renders `isIndeterminate` as the absence of `aria-valuenow`, which is exactly how a screen
 * reader tells "we do not know yet" from "nothing has happened".
 */
export const ProgressBar = Object.assign(ProgressBarRoot, {
  Label: ProgressLabel,
  Header: ProgressHeader,
  Value: ProgressValue,
  Track: ProgressTrack,
  Fill: ProgressFill,
})

import {
  FieldError as AriaFieldError,
  Label as AriaLabel,
  Radio as AriaRadio,
  RadioGroup as AriaRadioGroup,
  Text as AriaText,
} from 'react-aria-components'
import type {
  FieldErrorProps as AriaFieldErrorProps,
  LabelProps as AriaLabelProps,
  RadioGroupProps as AriaRadioGroupProps,
  RadioProps as AriaRadioProps,
  TextProps as AriaTextProps,
} from 'react-aria-components'

import { ERROR, HINT, LABEL } from '../field'

/**
 * The sheet's `.ds-radio`. The dot is a circle where the checkbox is a 2px-radius
 * square — the two exceptions to this system's `rounded-none`.
 *
 * States are published as custom properties here and read by the indicator, rather
 * than applied to it through a group variant. A group variant sorts at the same
 * specificity as a plain utility, so it silently loses to the indicator's own
 * `border-input`; a property set on this element wins the ordinary cascade.
 * See the longer note in `Checkbox.tsx`.
 *
 * The names are shared with `Checkbox` deliberately, so the two read the same set
 * and neither has to know which it is.
 */
const CONTROL = [
  'group/selection inline-flex items-center gap-2.5',
  'cursor-pointer select-none',
  'data-[disabled]:cursor-not-allowed data-[disabled]:opacity-35',
  // rest
  '[--selection-border:var(--color-input)]',
  '[--selection-mark:0]',
  '[--selection-scale:0.4]',
  '[--selection-ring:transparent]',
  // Hover only brightens the ring; there is nothing to invert, because the centre
  // is empty until the radio is selected.
  'data-[hovered]:[--selection-border:var(--color-foreground)]',
  'data-[selected]:[--selection-border:var(--color-primary)]',
  'data-[selected]:[--selection-mark:1]',
  'data-[selected]:[--selection-scale:1]',
  'data-[focus-visible]:[--selection-ring:var(--color-primary)]',
  // The centre scales in, which is motion, so under reduced motion it stays at
  // full size and cross-fades instead — a fade is not motion and needs no query.
  'motion-reduce:[--selection-scale:1]',
].join(' ')

const DOT = [
  'relative size-[18px] flex-none rounded-full',
  'border border-(--selection-border) bg-transparent',
  'outline-1 outline-offset-[3px] outline-(--selection-ring)',
  'transition-[border-color,outline-color] duration-(--duration-fast) ease-pulse',
].join(' ')

/** The 10px centre, the sheet's `::after` at `inset: 4px`. */
const CENTRE = [
  'absolute inset-[3px] rounded-full bg-primary',
  'opacity-(--selection-mark) scale-(--selection-scale)',
  // **`scale`, not `transform`.** The property this animates is the CSS `scale` at `:62`, and a
  // transition that names `transform` does not cover it — the centre popped in while only the
  // fade ran. The `motion-reduce` rule above keeps it still for anyone who asked for that.
  'transition-[opacity,scale] duration-(--duration-fast) ease-pulse',
].join(' ')

/** The sheet shares `.ds-check-label` between the two controls: 13px, 80%. */
const TEXT = 'text-[13px] text-foreground/80'

/** The sheet's `<fieldset class="stack ds-field">`: legend, controls, hint. */
const GROUP = 'group flex'

export interface RadioProps extends Omit<
  AriaRadioProps,
  'isDisabled' | 'children' | 'className' | 'ref'
> {
  /** React 19 passes `ref` as an ordinary prop, so no `forwardRef` wrapper. */
  ref?: React.Ref<HTMLLabelElement>
  /** Disables the control. This is a React Aria prop — there is no `disabled`. */
  isDisabled?: AriaRadioProps['isDisabled']
  /**
   * Identifies this radio to its `Radio.Group`, which owns the selection. A
   * `Radio` outside a group has no group state to read, so it is always used
   * inside one. `isRequired` and `isInvalid` belong to the group, not here.
   */
  value: AriaRadioProps['value']
  className?: string
  /** `Radio.Indicator` and `Radio.Text`, in that order. */
  children?: React.ReactNode
}

export interface RadioGroupProps extends Omit<
  AriaRadioGroupProps,
  | 'isDisabled'
  | 'isReadOnly'
  | 'isRequired'
  | 'isInvalid'
  | 'value'
  | 'defaultValue'
  | 'onChange'
  | 'orientation'
  | 'children'
  | 'className'
  | 'ref'
> {
  ref?: React.Ref<HTMLDivElement>
  isDisabled?: AriaRadioGroupProps['isDisabled']
  isReadOnly?: AriaRadioGroupProps['isReadOnly']
  isRequired?: AriaRadioGroupProps['isRequired']
  isInvalid?: AriaRadioGroupProps['isInvalid']
  /** The group owns the selection: one `value` from its radios. */
  value?: AriaRadioGroupProps['value']
  defaultValue?: AriaRadioGroupProps['defaultValue']
  onChange?: AriaRadioGroupProps['onChange']
  /** Lays the radios in a row instead of the sheet's default column. */
  orientation?: AriaRadioGroupProps['orientation']
  className?: string
  /** `Radio.Label`, the radios, then `Radio.Hint` and `Radio.Error`. */
  children?: React.ReactNode
}

export interface RadioIndicatorProps extends React.HTMLAttributes<HTMLSpanElement> {
  className?: string
}

export interface RadioTextProps extends React.HTMLAttributes<HTMLSpanElement> {
  children?: React.ReactNode
}

export interface RadioLabelProps extends AriaLabelProps {
  children?: React.ReactNode
}

export interface RadioHintProps extends AriaTextProps {
  children?: React.ReactNode
}

export interface RadioFieldErrorProps extends AriaFieldErrorProps {
  /** The message, or a function of the field's validation result. */
  children?: AriaFieldErrorProps['children']
}

/**
 * The dot, with its 10px centre. Use it as `Radio.Indicator`, inside a `Radio`.
 *
 * Exported as `RadioIndicator` only so tooling can resolve it; consume the
 * compound form `Radio.Indicator`.
 */
export function RadioIndicator({ className, ...props }: RadioIndicatorProps) {
  return (
    <span
      data-slot="indicator"
      aria-hidden="true"
      className={[DOT, className].filter(Boolean).join(' ')}
      {...props}
    >
      <span data-slot="centre" className={CENTRE} />
    </span>
  )
}

/**
 * The label of a single radio. Use it as `Radio.Text`, beside `Radio.Indicator`.
 * A bare text child renders too, just without the label styling.
 *
 * Exported as `RadioText` only so tooling can resolve it; consume the compound
 * form `Radio.Text`.
 */
export function RadioText({ className, children, ...props }: RadioTextProps) {
  return (
    <span
      data-slot="text"
      className={[TEXT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </span>
  )
}

/**
 * The legend for the group. Use it as `Radio.Label`, inside `Radio.Group`.
 *
 * Exported as `RadioLabel` only so tooling can resolve it; consume the compound
 * form `Radio.Label`.
 */
export function RadioLabel({ className, children, ...props }: RadioLabelProps) {
  return (
    <AriaLabel
      className={[LABEL, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaLabel>
  )
}

/**
 * The guidance under the group. Use it as `Radio.Hint`. React Aria wires it to the
 * group's `aria-describedby`.
 *
 * Exported as `RadioHint` only so tooling can resolve it; consume the compound
 * form `Radio.Hint`.
 */
export function RadioHint({ className, children, ...props }: RadioHintProps) {
  return (
    <AriaText
      slot="description"
      className={[HINT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaText>
  )
}

/**
 * The message shown when the group is `isInvalid`. Use it as `Radio.Error`;
 * React Aria renders nothing while the group is valid.
 *
 * Exported as `RadioFieldError` only so tooling can resolve it; consume the
 * compound form `Radio.Error`.
 */
export function RadioFieldError({ className, ...props }: RadioFieldErrorProps) {
  return (
    <AriaFieldError
      className={[ERROR, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * The group. Use it as `Radio.Group`. It owns the value, and every radio inside it
 * shares one tab stop, with the arrow keys moving between them.
 *
 * Exported as `RadioGroup` only so tooling can resolve it; consume the compound
 * form `Radio.Group`.
 */
export function RadioGroup({
  ref,
  orientation = 'vertical',
  className,
  children,
  ...props
}: RadioGroupProps) {
  return (
    <AriaRadioGroup
      ref={ref}
      orientation={orientation}
      className={[
        GROUP,
        // **One direction, chosen — never both.** This used to be a `flex-col` in `GROUP` with a
        // `flex-row` added here for the horizontal case, so the element carried two conflicting
        // utilities and which one won depended on Tailwind's generated order rather than on the class
        // list. The direction is decided in one place now.
        orientation === 'horizontal' ? 'flex-row gap-5' : 'flex-col gap-2.5',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
      {...props}
    >
      {children}
    </AriaRadioGroup>
  )
}

/**
 * Styled element. Not exported — `Radio` below is the public symbol, and docgen
 * reads the JSDoc from the *exported* declaration, not this one.
 */
function RadioControl({ ref, className, children, ...props }: RadioProps) {
  return (
    <AriaRadio
      ref={ref}
      className={[CONTROL, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaRadio>
  )
}

/**
 * A radio, and the group it belongs to — the sheet's `.ds-radio`.
 *
 * ```tsx
 * <Radio.Group defaultValue="https">
 *   <Radio.Label>Protocol</Radio.Label>
 *   <Radio value="http">
 *     <Radio.Indicator />
 *     <Radio.Text>HTTP</Radio.Text>
 *   </Radio>
 *   <Radio value="https">
 *     <Radio.Indicator />
 *     <Radio.Text>HTTPS</Radio.Text>
 *   </Radio>
 *   <Radio.Hint>Applies to every check.</Radio.Hint>
 *   <Radio.Error>Choose a protocol.</Radio.Error>
 * </Radio.Group>
 * ```
 *
 * The slots are explicit, like `Button.Icon` and `Button.Text`: `Radio.Indicator`
 * draws the dot and its centre, and `Radio.Text` the label. A bare text child still
 * renders, it just misses the label styling, so a missing slot degrades rather than
 * disappears.
 *
 * `Radio.Group` owns the value. A `Radio` outside one has no group state to read,
 * which is why `isRequired` and `isInvalid` live on the group rather than on the
 * control.
 */
export const Radio = Object.assign(RadioControl, {
  Group: RadioGroup,
  Indicator: RadioIndicator,
  Text: RadioText,
  Label: RadioLabel,
  Hint: RadioHint,
  Error: RadioFieldError,
})

import {
  RangeCalendar as AriaRangeCalendar,
  CalendarCell as AriaCalendarCell,
  RangeCalendarStateContext,
} from 'react-aria-components'
import type {
  CalendarCellProps as AriaCalendarCellProps,
  DateValue,
  RangeCalendarProps as AriaRangeCalendarProps,
} from 'react-aria-components'

import { useContext } from 'react'
import type { ReactNode } from 'react'

import {
  DATE_CELL,
  DATE_HEADING,
  DateCalendarChrome,
  useVisibleRangeLabel,
} from '../date'

export interface RangeCalendarProps extends Omit<
  AriaRangeCalendarProps<DateValue>,
  | 'children'
  | 'className'
  | 'value'
  | 'defaultValue'
  | 'onChange'
  | 'isDisabled'
  | 'isReadOnly'
  | 'minValue'
  | 'maxValue'
  | 'allowsNonContiguousRanges'
> {
  /** The range as `{ start, end }`. Controlled. */
  value?: AriaRangeCalendarProps<DateValue>['value']
  /** The range it starts with, for uncontrolled use. */
  defaultValue?: AriaRangeCalendarProps<DateValue>['defaultValue']
  /** Called with the range as its ends move. */
  onChange?: AriaRangeCalendarProps<DateValue>['onChange']
  /** Disables the whole grid. */
  isDisabled?: AriaRangeCalendarProps<DateValue>['isDisabled']
  /** Shows it without letting a day be chosen. */
  isReadOnly?: AriaRangeCalendarProps<DateValue>['isReadOnly']
  /** The earliest selectable day. */
  minValue?: AriaRangeCalendarProps<DateValue>['minValue']
  /** The latest selectable day. */
  maxValue?: AriaRangeCalendarProps<DateValue>['maxValue']
  /** Lets the range skip days inside it, for a set of visits rather than a span. */
  allowsNonContiguousRanges?: AriaRangeCalendarProps<DateValue>['allowsNonContiguousRanges']

  /** How many months are on screen at once. A range shows two by default. */
  months?: number
  className?: string
  /** Overrides the whole grid. Rarely wanted — the chrome below is the sheet's own. */
  children?: ReactNode
}

export interface RangeCalendarHeadingProps {
  className?: string
  children?: ReactNode
}

export interface RangeCalendarCellProps extends Omit<
  AriaCalendarCellProps,
  'className'
> {
  className?: string
}

/**
 * The month's name. Use it as `RangeCalendar.Heading` when you are building your own grid.
 *
 * **It is `aria-hidden`, because React Aria renders its own heading for assistive tech just above
 * it** — and that one is correct for any number of visible months. This is the copy the eye reads.
 *
 * Exported as `RangeCalendarHeading` only so tooling can resolve it; consume the compound form
 * `RangeCalendar.Heading`.
 */
export function RangeCalendarHeading({
  className,
  children,
}: RangeCalendarHeadingProps) {
  // **A range calendar has its own state context.** `CalendarStateContext` is provided too, but it
  // carries no `visibleRange`, so the heading rendered empty — a blank caption above a correct grid.
  const state = useContext(RangeCalendarStateContext)
  const label = useVisibleRangeLabel(state?.visibleRange ?? null)

  return (
    <h2
      data-slot="heading"
      aria-hidden="true"
      className={[DATE_HEADING, className].filter(Boolean).join(' ')}
    >
      {children ?? label}
    </h2>
  )
}

/**
 * One day. Use it as `RangeCalendar.Cell` when you are building your own grid.
 *
 * Exported as `RangeCalendarCell` only so tooling can resolve it; consume the compound form
 * `RangeCalendar.Cell`.
 */
export function RangeCalendarCell({
  className,
  ...props
}: RangeCalendarCellProps) {
  return (
    <AriaCalendarCell
      data-slot="cell"
      className={[DATE_CELL, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * Two months at once, with a span of days between them.
 *
 * ```tsx
 * <RangeCalendar aria-label="Range" />
 * <RangeCalendar aria-label="Range" defaultValue={{ start, end }} />
 * ```
 *
 * **`DateRangePicker` is this inside a popover**, and the three date components share one set of
 * segments, one chrome and one day cell — so a day looks the same wherever it is drawn. Reach for
 * this when the range *is* the screen: a retention window, an incident's span, an availability view.
 *
 * **A range is two endpoints and everything between them**, which is more state than a single date:
 * the first click sets where it starts and the calendar waits, the second sets where it ends, and a
 * third starts over. `CalendarCell` renders `data-selection-start` and `data-selection-end` on the
 * two ends, so the ends and the days between them can be styled differently — the span is what makes
 * a range readable at a glance rather than two loose dates.
 *
 * **The default is two months.** A range that crosses a month boundary is the normal case, not the
 * exception, and a single month makes the user page back and forth to see what they just selected.
 */
function RangeCalendarRoot({
  months = 2,
  className,
  children,
  ...props
}: RangeCalendarProps) {
  return (
    <AriaRangeCalendar
      className={className}
      {...props}
      visibleDuration={{ months }}
    >
      {children ?? (
        <DateCalendarChrome
          Heading={RangeCalendarHeading}
          Cell={RangeCalendarCell}
          months={months}
        />
      )}
    </AriaRangeCalendar>
  )
}

/**
 * The compound export. A plain `function` decorated with `Object.assign` leaves TypeScript unaware of
 * the slots, which is why the root is named apart and only the decorated const is exported.
 */
export const RangeCalendar = Object.assign(RangeCalendarRoot, {
  Heading: RangeCalendarHeading,
  Cell: RangeCalendarCell,
})

import {
  FieldError as AriaFieldError,
  Group as AriaGroup,
  Input as AriaInput,
  Label as AriaLabel,
  SearchField as AriaSearchField,
  Text as AriaText,
} from 'react-aria-components'
import type {
  FieldErrorProps as AriaFieldErrorProps,
  GroupProps as AriaGroupProps,
  InputProps as AriaInputProps,
  LabelProps as AriaLabelProps,
  SearchFieldProps as AriaSearchFieldProps,
  TextProps as AriaTextProps,
} from 'react-aria-components'

import {
  ERROR,
  FIELD,
  FIELD_SIZES,
  GROUP,
  HINT,
  ICON,
  ICON_POSITIONS,
  INPUT,
  LABEL,
} from '../field'
import type { FieldSize, IconPosition } from '../field'

/**
 * The sheet's own magnifier, traced from `.ds-affix--search` in `components.html`
 * — same `viewBox`, same radii, same 1.5 stroke. It carries no width or height so
 * `SearchField.Icon` can size it in `cap` and have it track the field's `size`.
 */
const Magnifier = (
  <svg viewBox="0 0 16 16" fill="none" aria-hidden="true">
    <circle cx="6.8" cy="6.8" r="5.1" stroke="currentColor" strokeWidth="1.5" />
    <line
      x1="10.7"
      y1="10.7"
      x2="14.6"
      y2="14.6"
      stroke="currentColor"
      strokeWidth="1.5"
    />
  </svg>
)

export interface SearchFieldProps extends Omit<
  AriaSearchFieldProps,
  | 'isDisabled'
  | 'isReadOnly'
  | 'isRequired'
  | 'isInvalid'
  | 'value'
  | 'defaultValue'
  | 'onChange'
  | 'onClear'
  | 'onSubmit'
  | 'children'
  | 'className'
  | 'ref'
> {
  /** React 19 passes `ref` as an ordinary prop, so no `forwardRef` wrapper. */
  ref?: React.Ref<HTMLDivElement>
  /** Height and type size of the control, inherited by anything inside it. */
  size?: FieldSize
  /** Disables the whole field. This is a React Aria prop — there is no `disabled`. */
  isDisabled?: AriaSearchFieldProps['isDisabled']
  /** Makes the value readable but not editable. Styles like disabled. */
  isReadOnly?: AriaSearchFieldProps['isReadOnly']
  isRequired?: AriaSearchFieldProps['isRequired']
  /** Puts the field in its error state and reveals `SearchField.Error`. */
  isInvalid?: AriaSearchFieldProps['isInvalid']
  /**
   * The field owns its value, so these live here and not on `SearchField.Input`.
   * React Aria's `onChange` takes the string directly, not an event.
   */
  value?: AriaSearchFieldProps['value']
  defaultValue?: AriaSearchFieldProps['defaultValue']
  onChange?: AriaSearchFieldProps['onChange']
  /** Fires on Enter, and when the clear affordance is used. */
  onSubmit?: AriaSearchFieldProps['onSubmit']
  onClear?: AriaSearchFieldProps['onClear']
  className?: string
  children?: React.ReactNode
}

export interface SearchFieldLabelProps extends AriaLabelProps {
  children?: React.ReactNode
}

/**
 * `value`, `defaultValue`, `onChange` and `onSubmit` are omitted on purpose:
 * React Aria's field is the single source of truth for the value, so accepting
 * them here would silently do nothing. They belong on `SearchField`.
 */
export interface SearchFieldInputProps extends Omit<
  AriaInputProps,
  'size' | 'value' | 'defaultValue' | 'onChange' | 'children'
> {
  className?: string
}

export interface SearchFieldGroupProps extends AriaGroupProps {
  children?: React.ReactNode
}

export interface SearchFieldHintProps extends AriaTextProps {
  children?: React.ReactNode
}

export interface SearchFieldErrorProps extends AriaFieldErrorProps {
  /** The message, or a function of the field's validation result. */
  children?: AriaFieldErrorProps['children']
}

export interface SearchFieldIconProps extends React.HTMLAttributes<HTMLSpanElement> {
  /**
   * Which edge to pin the magnifier to. `start` matches the sheet; a prop rather
   * than document order, unlike `Button.Icon`, because this is absolutely
   * positioned and markup order cannot decide.
   */
  position?: IconPosition
  /** Defaults to the sheet's magnifier; pass a glyph to replace it. */
  children?: React.ReactNode
}

/**
 * Layout slot for a `SearchField` label. Use it as `SearchField.Label`.
 *
 * Exported as `SearchFieldLabel` only so tooling can resolve it; consume the
 * compound form `SearchField.Label`.
 */
export function SearchFieldLabel({
  className,
  children,
  ...props
}: SearchFieldLabelProps) {
  return (
    <AriaLabel
      className={[LABEL, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaLabel>
  )
}

/**
 * Wraps the control so the magnifier has a box to sit in. Use it as
 * `SearchField.Group`, and put `SearchField.Icon` inside it beside
 * `SearchField.Input`.
 *
 * Exported as `SearchFieldGroup` only so tooling can resolve it; consume the
 * compound form `SearchField.Group`.
 */
export function SearchFieldGroup({
  className,
  children,
  ...props
}: SearchFieldGroupProps) {
  return (
    <AriaGroup
      data-slot="control"
      className={[GROUP, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaGroup>
  )
}

/**
 * The search control. Use it as `SearchField.Input`. Inherits its height and type
 * size from `SearchField`.
 *
 * Exported as `SearchFieldInput` only so tooling can resolve it; consume the
 * compound form `SearchField.Input`.
 */
export function SearchFieldInput({
  className,
  ...props
}: SearchFieldInputProps) {
  return (
    <AriaInput
      data-slot="input"
      className={[INPUT, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * The magnifier, pinned inside the control. Use it as `SearchField.Icon`. It
 * defaults to the glyph the sheet draws, so the common case needs no markup:
 * `<SearchField.Icon />`.
 *
 * Exported as `SearchFieldIcon` only so tooling can resolve it; consume the
 * compound form `SearchField.Icon`.
 */
export function SearchFieldIcon({
  position = 'start',
  className,
  children,
  ...props
}: SearchFieldIconProps) {
  return (
    <span
      data-slot={position === 'start' ? 'icon-start' : 'icon-end'}
      aria-hidden="true"
      className={[ICON, ICON_POSITIONS[position], className]
        .filter(Boolean)
        .join(' ')}
      {...props}
    >
      {children ?? Magnifier}
    </span>
  )
}

/**
 * The guidance under the control — the sheet uses it for the live result count.
 * Use it as `SearchField.Hint`. React Aria wires it to the input's
 * `aria-describedby`, so it is read out with the field rather than announced on
 * its own.
 *
 * Exported as `SearchFieldHint` only so tooling can resolve it; consume the
 * compound form `SearchField.Hint`.
 */
export function SearchFieldHint({
  className,
  children,
  ...props
}: SearchFieldHintProps) {
  return (
    <AriaText
      slot="description"
      className={[HINT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaText>
  )
}

/**
 * The message shown when the field is `isInvalid`. Use it as `SearchField.Error`.
 * React Aria renders nothing while the field is valid, so it is always safe to
 * include.
 *
 * Exported as `SearchFieldError` only so tooling can resolve it; consume the
 * compound form `SearchField.Error`.
 */
export function SearchFieldError({
  className,
  ...props
}: SearchFieldErrorProps) {
  return (
    <AriaFieldError
      className={[ERROR, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * Styled element. Not exported — `SearchField` below is the public symbol, and
 * docgen reads the JSDoc from the *exported* declaration, not this one.
 */
function SearchFieldRoot({
  ref,
  size = 'md',
  className,
  children,
  isDisabled,
  isReadOnly,
  isRequired,
  isInvalid,
  ...rest
}: SearchFieldProps) {
  return (
    <AriaSearchField
      ref={ref}
      isDisabled={isDisabled}
      isReadOnly={isReadOnly}
      isRequired={isRequired}
      isInvalid={isInvalid}
      className={[FIELD, FIELD_SIZES[size], className]
        .filter(Boolean)
        .join(' ')}
      {...rest}
    >
      {children}
    </AriaSearchField>
  )
}

/**
 * A search control — the sheet's `.ds-affix--search`. Same field anatomy as
 * `TextField`, but on React Aria's `SearchField`, so the input has the searchbox
 * role, submits on Enter, and reports whether it is empty.
 *
 * ```tsx
 * <SearchField onSubmit={(term) => filter(term)}>
 *   <SearchField.Label>Search monitors</SearchField.Label>
 *   <SearchField.Group>
 *     <SearchField.Icon />
 *     <SearchField.Input placeholder="Filter by name or URL…" />
 *   </SearchField.Group>
 *   <SearchField.Hint>12 of 24 monitors match</SearchField.Hint>
 *   <SearchField.Error>Enter at least two characters.</SearchField.Error>
 * </SearchField>
 * ```
 *
 * `SearchField.Icon` draws the sheet's magnifier by default, so the usual case is
 * an empty tag. Reach for `TextField` instead when the field is not a search.
 */
export const SearchField = Object.assign(SearchFieldRoot, {
  Label: SearchFieldLabel,
  Group: SearchFieldGroup,
  Input: SearchFieldInput,
  Icon: SearchFieldIcon,
  Hint: SearchFieldHint,
  Error: SearchFieldError,
})

import {
  SharedElement as AriaSharedElement,
  SharedElementTransition as AriaSharedElementTransition,
} from 'react-aria-components'
import type {
  SharedElementProps as AriaSharedElementProps,
  SharedElementTransitionProps as AriaSharedElementTransitionProps,
} from 'react-aria-components'

export interface SharedElementTransitionProps extends AriaSharedElementTransitionProps {}
export interface SharedElementProps extends Omit<
  AriaSharedElementProps,
  'className'
> {
  className?: string
}

/**
 * The scope a moving element lives in.
 *
 * **It renders nothing at all** — it is a context provider with no element of its own — so there is no
 * class list here and nothing to style. What it does is give its `SharedElement`s a shared registry to
 * animate through.
 *
 * The two are a pair: a `SharedElement` **throws** without one — *"`<SharedElement>` must be rendered
 * inside a `SharedElementTransition`"* — which is the same shape as `ColumnResizer` without its
 * `ResizableTableContainer`. So this is not an optional wrapper.
 */
export function SharedElementTransition({
  children,
}: SharedElementTransitionProps) {
  return <AriaSharedElementTransition>{children}</AriaSharedElementTransition>
}

/**
 * One element that moves between parents, animating from where it was to where it goes.
 *
 * ```tsx
 * <SharedElementTransition>
 *   {atTop ? <header><SharedElement name="dot" className="size-2 bg-primary" /></header>
 *           : <footer><SharedElement name="dot" className="size-2 bg-primary" /></footer>}
 * </SharedElementTransition>
 * ```
 *
 * **`name` is what ties the two together, not a ref or a key.** Render the same `name` in a different
 * place and React Aria treats it as one thing that moved, carrying its animation with it; render it with
 * `isVisible={false}` and it animates out rather than vanishing. It reports `data-entering` and
 * `data-exiting` while it does.
 *
 * **Nothing here uses it in the default styling of another component, and one already uses it
 * internally.** React Aria's own `ToggleButtonGroup` — which this repo wraps — puts a
 * `SharedElementTransition` around its children, so a selected segment's fill can travel rather than blink.
 * This exists for a consumer laying out its own moving thing: a marker that follows the current view, a
 * chip that changes columns.
 */
export function SharedElement({ className, ...props }: SharedElementProps) {
  return (
    <AriaSharedElement
      data-slot="shared-element"
      className={className}
      {...props}
    />
  )
}

import {
  SheetTrigger as AriaSheetTrigger,
  Heading as AriaHeading,
  Sheet as AriaSheet,
  SheetContent as AriaSheetContent,
  SheetOverlay as AriaSheetOverlay,
  Text as AriaText,
} from 'react-aria-components'
import type {
  DialogTriggerProps as AriaDialogTriggerProps,
  HeadingProps as AriaHeadingProps,
  SheetOverlayProps as AriaSheetOverlayProps,
  TextProps as AriaTextProps,
} from 'react-aria-components'

import { createContext, useContext, useId } from 'react'
import type { ReactNode } from 'react'

import { Button } from '../Button/Button'
import { DIALOG_DESCRIPTION, DIALOG_FOOTER, DIALOG_TITLE } from '../Modal/Modal'
import { SURFACE } from '../popover'

/** Which edge the panel comes in from. `start` and `end` resolve to left or right by the locale. */
export type SheetSide = 'top' | 'bottom' | 'left' | 'right' | 'start' | 'end'

/**
 * How big the panel is, per edge — **chosen in JavaScript, not in CSS**.
 *
 * It is applied to the `Sheet` layer rather than to the panel, because the panel cannot be sized from
 * outside at all — see the note in `SheetContent`.
 */
const SIZES: Record<SheetSide, string> = {
  right: 'h-full w-96',
  left: 'h-full w-96',
  start: 'h-full w-96',
  end: 'h-full w-96',
  // An edge-anchored sheet meets the home indicator and the notch, so its panel is inset from
  // them. The insets are `0px` until the document asks for `viewport-fit=cover`, which the root
  // route now does.
  bottom:
    'max-h-[80vh] w-full [padding-block-end:env(safe-area-inset-bottom,0px)]',
  top: 'max-h-[80vh] w-full [padding-block-start:env(safe-area-inset-top,0px)]',
}

export interface SheetProps extends Omit<
  AriaDialogTriggerProps,
  'children' | 'className' | 'isOpen' | 'defaultOpen' | 'onOpenChange'
> {
  /** Whether the sheet is open. Controlled, so pass `onOpenChange` with it. */
  isOpen?: AriaDialogTriggerProps['isOpen']
  /** Whether it starts open, for uncontrolled use. */
  defaultOpen?: AriaDialogTriggerProps['defaultOpen']
  /** Called when the sheet asks to open or close. */
  onOpenChange?: AriaDialogTriggerProps['onOpenChange']
  /** The trigger, then a `Sheet.Content`. */
  children?: ReactNode
}

export interface SheetContentProps extends Omit<
  AriaSheetOverlayProps,
  'children' | 'className' | 'position'
> {
  /** Which edge the panel slides in from. It also becomes the swipe direction. */
  side?: SheetSide
  className?: string
  children?: ReactNode
}

export interface SheetTitleProps extends Omit<AriaHeadingProps, 'className'> {
  className?: string
}

export interface SheetDescriptionProps extends Omit<
  AriaTextProps,
  'className'
> {
  className?: string
}

export interface SheetFooterProps {
  className?: string
  children?: ReactNode
}

export interface SheetCloseProps {
  className?: string
  children?: ReactNode
}

/**
 * The id the panel is described by. React Aria wires `aria-labelledby` from the title on its own and
 * does **not** wire a description — the same gap the modal has, and the same fix.
 */
const DescriptionId = createContext<string | undefined>(undefined)

/**
 * The panel: the scrim, the edge, and the swipe. Use it as `Sheet.Content`.
 *
 * **Three layers, and none of them is optional.** `SheetOverlay` owns the state and draws the scrim,
 * `Sheet` reads that state and decides the edge, and `SheetContent` reads *its* result. Putting the
 * content straight inside `Sheet` leaves `SheetContext` null and the story fails with
 * `Cannot destructure property 'position' of useContext(...)` — which reads like a React bug and is a
 * missing layer.
 *
 * **`position` is a `SheetOverlay` prop** — not `Sheet`, not `SheetContent`. It is `side` here because
 * that is the word a consumer reaches for; it is handed to the overlay, which is the layer that wants it.
 *
 * The surface is `popover.ts`'s, so a sheet and a menu read as the same material arriving by different
 * routes.
 *
 * Exported as `SheetContent` only so tooling can resolve it; consume the compound form `Sheet.Content`.
 */
export function SheetContent({
  side = 'right',
  className,
  children,
  ...props
}: SheetContentProps) {
  const id = useId()
  return (
    <AriaSheetOverlay
      position={side}
      data-slot="sheet-overlay"
      className={[
        'fixed inset-0 z-50 bg-black/50',
        // The scrim is the one place the palette deliberately does not reach: no token darkens in both
        // themes, so this is Tailwind's own black at half, by design.
        'flex',
        side === 'bottom' || side === 'top' ? 'items-end' : 'items-stretch',
        side === 'left' || side === 'start' ? 'justify-start' : 'justify-end',
        side === 'top' ? '!items-start' : '',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
      {...props}
    >
      {/*
        **The size goes here, on `Sheet` — not on `SheetContent`.** React Aria's `SheetContent`
        renders a `Dialog` with `style={{ width: '100%', height: '100%' }}` written *after* the props,
        and an inline style outranks every class. So the panel is always exactly as big as the layer
        above it, and a `w-96` passed to it silently does nothing — the first version of this component
        did that and rendered a 250×149 panel while the class list looked correct.
      */}
      <AriaSheet
        data-slot="sheet"
        className={[
          'flex outline-1 outline-offset-[-2px] outline-transparent',
          // React Aria renders this surface without a `data-focus-visible`, so the ring is keyed on
          // the pseudo-class the browser gives it rather than on an attribute that never arrives.
          'focus-visible:outline-ring',
          SIZES[side],
        ].join(' ')}
      >
        <AriaSheetContent
          aria-describedby={id}
          className={[
            // Scrolling lives on the panel, because the layer above is pinned to `height: 100%`
            // and cannot be sized from outside. Without it a sheet taller than the viewport had
            // no scrollbar anywhere: `mt-auto` on the footer had no free space to claim, and the
            // content below the fold was unreachable.
            SURFACE,
            'flex min-h-0 flex-col overflow-y-auto overscroll-contain p-6',
          ]
            .filter(Boolean)
            .join(' ')}
        >
          <DescriptionId.Provider value={id}>{children}</DescriptionId.Provider>
        </AriaSheetContent>
      </AriaSheet>
    </AriaSheetOverlay>
  )
}

/**
 * The panel's title. Use it as `Sheet.Title` — the modal's own title type, imported rather than copied,
 * because the two are the same short task arriving by a different route.
 *
 * Exported as `SheetTitle` only so tooling can resolve it; consume the compound form `Sheet.Title`.
 */
export function SheetTitle({ className, ...props }: SheetTitleProps) {
  return (
    <AriaHeading
      slot="title"
      className={[DIALOG_TITLE, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * A sentence under the title. Use it as `Sheet.Description` — its id is wired to the panel's
 * `aria-describedby` here, because React Aria does not.
 *
 * Exported as `SheetDescription` only so tooling can resolve it; consume the compound form
 * `Sheet.Description`.
 */
export function SheetDescription({
  className,
  ...props
}: SheetDescriptionProps) {
  return (
    <AriaText
      slot="description"
      id={useContext(DescriptionId)}
      className={[DIALOG_DESCRIPTION, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * The actions at the foot of the panel. Use it as `Sheet.Footer`.
 *
 * Exported as `SheetFooter` only so tooling can resolve it; consume the compound form `Sheet.Footer`.
 */
export function SheetFooter({ className, children }: SheetFooterProps) {
  return (
    <div
      className={[DIALOG_FOOTER, 'mbs-auto', className]
        .filter(Boolean)
        .join(' ')}
    >
      {children}
    </div>
  )
}

/**
 * A button that closes the panel. Use it as `Sheet.Close` — a plain button carrying `slot="close"`,
 * which is the whole mechanism, as it is on the modal.
 *
 * Exported as `SheetClose` only so tooling can resolve it; consume the compound form `Sheet.Close`.
 */
export function SheetClose({ className, children }: SheetCloseProps) {
  return (
    <Button slot="close" variant="ghost" className={className}>
      {children}
    </Button>
  )
}

function SheetRoot({ children, ...props }: SheetProps) {
  // **`SheetTrigger`, not `DialogTrigger`.** They take the same props, but React Aria's `SheetTrigger` wraps
  // its children in a `PressResponder` with `isPressed={false}` — "prevent the trigger element from
  // appearing stuck while the sheet is open". A plain `DialogTrigger` leaves the button that opened the
  // sheet looking pressed for as long as the sheet is up, which is exactly what a press-and-hold looks like
  // and is wrong.
  return <AriaSheetTrigger {...props}>{children}</AriaSheetTrigger>
}

/**
 * A panel that slides in from an edge — a task's details without leaving the page.
 *
 * ```tsx
 * <Sheet>
 *   <Button>Details</Button>
 *   <Sheet.Content side="right">
 *     <Sheet.Title>fra1 · Frankfurt</Sheet.Title>
 *     <Sheet.Description>Checked every 60 seconds.</Sheet.Description>
 *     <Sheet.Footer>
 *       <Sheet.Close>Close</Sheet.Close>
 *     </Sheet.Footer>
 *   </Sheet.Content>
 * </Sheet>
 * ```
 *
 * **A sheet is a modal that kept the page visible.** It takes the pointer and traps focus exactly as a
 * `Modal` does, but covers one edge instead of the middle — so the row you opened it from is still on
 * screen behind it, which is the reason to reach for it over a dialog. Its title and footer are the
 * modal's own, imported rather than copied, so the two cannot drift.
 *
 * **It is also a swipe target on touch**, which is why `side` is not merely a layout prop: React Aria
 * turns it into the swipe direction, so a right-hand panel is dismissed by dragging right. A panel that
 * arrives with a gesture should leave the same way.
 */
export const Sheet = Object.assign(SheetRoot, {
  Content: SheetContent,
  Title: SheetTitle,
  Description: SheetDescription,
  Footer: SheetFooter,
  Close: SheetClose,
})

import {
  FieldError as AriaFieldError,
  FieldErrorContext as AriaFieldErrorContext,
  Label as AriaLabel,
  Slider as AriaSlider,
  SliderFill as AriaSliderFill,
  SliderOutput as AriaSliderOutput,
  SliderThumb as AriaSliderThumb,
  SliderTrack as AriaSliderTrack,
} from 'react-aria-components'
import type {
  FieldErrorProps as AriaFieldErrorProps,
  LabelProps as AriaLabelProps,
  SliderFillProps as AriaSliderFillProps,
  SliderOutputProps as AriaSliderOutputProps,
  SliderProps as AriaSliderProps,
  SliderThumbProps as AriaSliderThumbProps,
  SliderTrackProps as AriaSliderTrackProps,
} from 'react-aria-components'

import { useContext, useId } from 'react'

import { ERROR, FIELD_SIZES, FieldValidationContext, VALID } from '../field'
import type { FieldSize } from '../field'
import { FILL, HEADER, TONE, TRACK_WASH } from '../progress'

export interface SliderProps extends Omit<
  AriaSliderProps,
  | 'children'
  | 'className'
  | 'orientation'
  | 'value'
  | 'defaultValue'
  | 'onChange'
  | 'isDisabled'
  | 'minValue'
  | 'maxValue'
  | 'formatOptions'
> {
  /** The current value, as a single number or one per thumb. Controlled. */
  value?: AriaSliderProps['value']
  /** The value it starts at, for uncontrolled use. */
  defaultValue?: AriaSliderProps['defaultValue']
  /** Called as the handle moves. */
  onChange?: AriaSliderProps['onChange']
  /** Disables the whole rail. */
  isDisabled?: AriaSliderProps['isDisabled']
  /** The bottom of the range. */
  minValue?: AriaSliderProps['minValue']
  /** The top of the range. */
  maxValue?: AriaSliderProps['maxValue']
  /** How the value is written — `{ style: 'percent' }`, for instance. */
  formatOptions?: AriaSliderProps['formatOptions']

  /** `sm | md | lg`. The rail thickens with it, so the target grows with the type. */
  size?: FieldSize
  /** Keep it horizontal or stand it up; the rail and the thumb turn with it. */
  orientation?: AriaSliderProps['orientation']
  /**
   * Whether the value is invalid. **This one is ours, not React Aria's** — a slider is not a field
   * there, so nothing else can tell it. See `Slider.Error`.
   */
  isInvalid?: boolean
  className?: string
  /** A `Slider.Label`, a `Slider.Value`, and a `Slider.Track` of one or more thumbs. */
  children?: React.ReactNode
}

/** The label and the reading on one line, the same slot `ProgressBar` and `Meter` have. */
export interface SliderHeaderProps {
  className?: string
  children?: React.ReactNode
}

export interface SliderLabelProps extends Omit<AriaLabelProps, 'className'> {
  className?: string
}

export interface SliderValueProps extends Omit<
  AriaSliderOutputProps,
  'className' | 'children'
> {
  className?: string
  children?: React.ReactNode
}

export interface SliderTrackProps extends Omit<
  AriaSliderTrackProps,
  'className'
> {
  className?: string
}

export interface SliderFillProps extends Omit<
  AriaSliderFillProps,
  'className'
> {
  className?: string
  tone?: keyof typeof TONE
}

export interface SliderErrorProps extends AriaFieldErrorProps {
  /** The message, or a function of the field's validation result. */
  children?: AriaFieldErrorProps['children']
}

export interface SliderThumbProps extends Omit<
  AriaSliderThumbProps,
  'className'
> {
  className?: string
  /**
   * A name for one handle of a range. The thumb needs it; the handle does not show it.
   *
   * It travels as `aria-label` rather than as an `.sr-only` child, because React Aria's thumb renders
   * no children of its own — a `<span>` passed to it disappeared and both handles of a range came out
   * unnamed, which is exactly what a range must not be.
   */
  label?: string
}

/**
 * The rail. Taller than a progress bar's, because it has to be aimed at: the sheet's 4px bar is a
 * reading, and this is a control.
 *
 * Turned with the slider: `h-1 w-full` lying down, `h-full w-1` standing up. A rail is one dimension
 * short and one long, and which one changes with the orientation — a rule that only ever sets a
 * height paints a 1px line across a vertical slider and looks like a rendering fault.
 */
const RAIL = [
  // **Not `TRACK`, and the difference is the whole of a bug.** That rail clips (`overflow-clip`), which
  // the bar can afford — its fill is the whole drawing. A slider's handle is 20px square on a 4px rail,
  // so the clip painted it as a **4px sliver**: a white notch at the end of the fill instead of a grip.
  //
  // Nothing caught it for as long as the component has existed, because every assertion in the story
  // measures `getBoundingClientRect`, which reports a layout box whether or not an ancestor clips it.
  // The handle measured 20×20 while painting four pixels tall. It took a 3× screenshot of the rendered
  // control — the thing the eye reads — to see it, and an `overflow` assertion now to keep it.
  TRACK_WASH,
  'relative w-full rounded-none',
  // The thickness is a variable the slider publishes per size, so it stays a literal class Tailwind
  // can see — `h-(--slider-rail)` — rather than a value computed at runtime and invisible to it.
  'data-[orientation=vertical]:h-full data-[orientation=vertical]:w-(--slider-rail)',
  'data-[orientation=horizontal]:h-(--slider-rail) data-[orientation=horizontal]:w-full',
].join(' ')

/**
 * The rail's thickness, the grip's width and the grip's height, per `size`.
 *
 * **The first version set `h-1` outright**, so the `size` prop changed the legend's type and nothing
 * else — the `Sizes` story found three identical rails where it expected three different ones. A size
 * that does not reach the control is a size that lies, and this is the same mistake the number
 * field's steppers made one component ago: the prop was accepted and ignored.
 *
 * The handle grows with the rail, because the handle is what has to be hit.
 *
 * **The handle is square, and it is one size rather than two.** It used to be a narrow tall bar — 7×18px
 * at `md`, then 10×24px — and a reader looking at it twice said it still did not look right. They were
 * right, and the reason is proportion: a bar a hairline wide and several rails tall reads as a **cursor**,
 * not as something a hand closes around. Making it taller and narrower to look less like "a bullet sitting
 * on a line" fixed the wrong problem — what made the original square look wrong was its **border** and its
 * `bg-background` fill, a black box showing nothing but its own hairline, not its being square.
 *
 * So it is square again, solid, and larger: `sm`, `md` and `lg` are 14/16/20px against rails of 3/4/6px.
 * Nothing here is taller than it is wide, which is what the `ThumbPosition` story now actually checks.
 */
const RAIL_SIZE: Record<FieldSize, string> = {
  sm: '[--slider-rail:3px] [--slider-thumb:1rem]',
  md: '[--slider-rail:4px] [--slider-thumb:1.25rem]',
  lg: '[--slider-rail:6px] [--slider-thumb:1.5rem]',
}

/**
 * The handle. **Square**, like every other control in this system.
 *
 * A round thumb is what years of iOS sliders have trained everyone to expect, and it is the
 * temptation here. The sheet squares its buttons, its inputs and its fields, and gives only the
 * checkbox and the radio the radius users expect of a *selection* control. A slider handle is not a
 * selection control — it is a grip — so it stays square, and the affordance comes from its size and
 * the focus ring instead. Making it round would quietly add a third exception to a rule that has
 * exactly two.
 */
const THUMB = [
  // **React Aria positions the handle along the rail and expects the *recipe* to centre it in the
  // other axis.** Its inline style is `position:absolute; left: X%; transform: translate(-50%,-50%)`,
  // and that `-50%` assumes the box it translates already starts at the rail's centre — which it does
  // not, because `top` is `auto`. Measured on a 4px rail, the handle sat **10px above it**, hanging
  // over the fill like a tab. React Aria's own docs CSS carries the missing line: `top: 50%` when the
  // rail lies down, `left: 50%` when it stands up. This is that line, taken from the track rather than
  // from the handle, because the orientation is published on the track and not on the thumb.
  'group-data-[orientation=horizontal]:top-1/2',
  'group-data-[orientation=vertical]:left-1/2',
  // **Square, and written as two utilities rather than `size-(--)`** — that form silently produced
  // nothing here, which is how the handle first ended up with no height at all. Both sides read the same
  // variable, so they cannot drift out of square.
  'h-(--slider-thumb) w-(--slider-thumb) shrink-0 rounded-none',
  // No border. The first version was a bordered `bg-background` square, which on the dark page was a black
  // box showing nothing but its own hairline — it read as a rendering artifact sitting on the rail
  // rather than as something to grab. A border also muddies a shape this small, where the border is a
  // fifth of the width.
  //
  // So the handle is a **solid grip** in a token that already exists, and its states move that colour
  // the way every other control here does: quiet at rest, up to full strength on hover, and the
  // accent only while it is actually being dragged. The accent is already spent on the fill; a second
  // accent block beside it would say nothing new.
  // **Full strength, not 70%.** At 70% the handle was a pale grey — measurably lighter than the page
  // but *duller than the teal fill it sits on*, so on the filled half of the rail it receded and a
  // reader said it was hard to see. It is the thing you grab; it should be the loudest mark on the
  // rail, not the quietest. `--slider-mark` is white in this theme, and white reads against both
  // the teal fill and the dark track without a border or a ring.
  //
  // It is a variable rather than a utility because the handle is *also* where the invalid state has
  // to show, and `data-invalid` is on the root — the fourth time a state on a parent travels this
  // way, after `--slider-dim` two lines down.
  'bg-(--slider-mark)',
  'data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-2 data-[focus-visible]:outline-ring',
  'data-[disabled]:cursor-not-allowed',
  // Read from the slider, not from the handle: `data-disabled` is on the **root** while the handle is
  // a descendant, and a `data-[disabled]:` rule on the handle therefore never matches. This is the
  // fourth time this session that a state on a parent had to travel as a custom property — the same
  // shape as `Checkbox`'s indicator and `Select`'s trigger.
  'opacity-(--slider-dim)',
  // Hover is on the browser's pseudo-class rather than `data-hovered`: the handle is a 14px target and
  // the state has to arrive the moment the pointer is over it, which is what `:hover` guarantees.
  'motion-safe:transition-[background-color,scale] motion-safe:duration-(--duration-fast) ease-pulse',
  // **The state signals are scale, not colour.** With the handle already white at rest, hover and drag
  // have nothing left to brighten — so they grow. Dragging used to turn the handle teal, which is the
  // exact colour of the fill underneath it: invisible on the filled half of the rail, the same mistake
  // the resting colour made.
  'hover:scale-105 data-[dragging]:scale-110 active:scale-110',
  // The handle is the target, and 14px is a small one. The padding is on the thumb's own box so the
  // pointer reaches it without moving the rail.
  'before:absolute before:-inset-2 before:content-[""]',
].join(' ')

/**
 * The value, as React Aria formats it — one figure, or a pair for a range.
 *
 * `SliderOutput` is a `<output>`, which is the element for exactly this: the result of a control
 * rather than a control itself. It is `aria-live` for free, so a keyboard user hears the value move
 * as they arrow along the rail.
 */
const OUTPUT = [
  'font-mono text-[13px] tabular-nums text-foreground',
  'data-[disabled]:opacity-30',
].join(' ')

/**
 * A value chosen by dragging a handle along a rail.
 *
 * **The sheet has no slider in it**, so this is an invention. It is the progress bar's drawing made
 * interactive — the same 4px rail, the same accent fill, the same `progress.ts` — because a slider
 * *is* a bar with a handle on it, and two drawings of one idea is exactly the drift that file
 * exists to prevent.
 *
 * ```tsx
 * <Slider defaultValue={60}>
 *   <Slider.Label>Alert threshold</Slider.Label>
 *   <Slider.Value />
 *   <Slider.Track>
 *     <Slider.Fill />
 *     <Slider.Thumb />
 *   </Slider.Track>
 * </Slider>
 * ```
 *
 * A **range** is the same component with two thumbs and an array of values — `Slider.Track` holds as
 * many as you write, and React Aria keeps them from crossing:
 *
 * ```tsx
 * <Slider defaultValue={[20, 80]}>
 *   <Slider.Track>
 *     <Slider.Fill />
 *     <Slider.Thumb index={0} label="From" />
 *     <Slider.Thumb index={1} label="To" />
 *   </Slider.Track>
 * </Slider>
 * ```
 *
 * The keyboard is the reason to use this rather than a `div`: arrow keys step, Page Up and Down jump,
 * Home and End reach the ends, and every one of those is announced with the value it produced. A
 * slider that only responds to a pointer is unusable with a keyboard and invisible to a screen
 * reader, which is most of what a hand-rolled one gets wrong.
 *
 * **A slider is the one field here React Aria does not treat as a field**, so `isInvalid` and
 * `Slider.Error` are this library's own: React Aria gives a slider no validation at all, and a
 * slider bound to a form still has to be able to say what failed. `isInvalid` is what says so, and
 * the thumb carries it to its range input — the element a screen reader reads — as `aria-invalid`
 * plus a reference to the message.
 */
function SliderRoot({
  size = 'md',
  orientation = 'horizontal',
  isInvalid = false,
  className,
  children,
  ...props
}: SliderProps) {
  // **The error's id is minted here, and not in `Slider.Error`.** The message and the thumb that is
  // described by it are two different slots, and only a component above both of them can own the
  // name they share.
  const errorId = useId()

  return (
    // **A slider is not a field in React Aria, so it publishes the field contexts itself.** See
    // `FieldValidationContext`. This is what makes `Slider.Error` possible at all: a
    // `FieldError` renders nothing without a provider, and a `Slider` provides none.
    <AriaFieldErrorContext.Provider
      value={{ isInvalid, validationErrors: [], validationDetails: VALID }}
    >
      <FieldValidationContext.Provider value={{ isInvalid, errorId }}>
        <AriaSlider
          orientation={orientation}
          data-invalid={isInvalid || undefined}
          className={[
            FIELD_SIZES[size],
            RAIL_SIZE[size],
            // Declared on the element that owns the attribute, and read by the handle below it.
            '[--slider-dim:1] data-[disabled]:[--slider-dim:0.3]',
            // The handle's colour, for the same reason: invalid is on the root and the mark is a
            // descendant. The grip is the loudest thing on the rail, so a slider that failed turns
            // the thing you look at — rather than the accent fill, which says how far along it is.
            '[--slider-mark:var(--color-foreground)] data-[invalid]:[--slider-mark:var(--color-destructive)]',
            'flex flex-col gap-2',
            'data-[orientation=horizontal]:w-64',
            'data-[orientation=vertical]:h-40 data-[orientation=vertical]:w-fit',
            'data-[disabled]:cursor-default',
            className,
          ]
            .filter(Boolean)
            .join(' ')}
          {...props}
        >
          {children}
        </AriaSlider>
      </FieldValidationContext.Provider>
    </AriaFieldErrorContext.Provider>
  )
}

/** Assigned below; declared after the slots so the compound object can reference them. */

/**
 * What the slider sets. Use it as `Slider.Label` — React Aria wires it to the rail as the slider's
 * accessible name, so there is no `label` prop to keep in sync with it.
 *
 * Exported as `SliderLabel` only so tooling can resolve it; consume the compound form `Slider.Label`.
 */
export function SliderLabel({ className, ...props }: SliderLabelProps) {
  return (
    <AriaLabel
      className={[
        'font-mono text-[11px] uppercase tracking-[0.04em] text-foreground/70',
        'data-[disabled]:opacity-30',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
      {...props}
    />
  )
}

/**
 * The line above the rail: the label on the left, the reading on the right. Use it as
 * `Slider.Header` — the same slot `ProgressBar` and `Meter` have, for the same reason.
 *
 * Exported as `SliderHeader` only so tooling can resolve it; consume the compound form
 * `Slider.Header`.
 */
export function SliderHeader({ className, children }: SliderHeaderProps) {
  return (
    <div className={[HEADER, className].filter(Boolean).join(' ')}>
      {children}
    </div>
  )
}

/**
 * The reading. Use it as `Slider.Value` — an `<output>` that announces itself as the value changes.
 *
 * Exported as `SliderValue` only so tooling can resolve it; consume the compound form `Slider.Value`.
 */
export function SliderValue({ className, ...props }: SliderValueProps) {
  return (
    <AriaSliderOutput
      className={[OUTPUT, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * The rail. Use it as `Slider.Track`, around a `Slider.Fill` and one or more `Slider.Thumb`s.
 *
 * Exported as `SliderTrack` only so tooling can resolve it; consume the compound form
 * `Slider.Track`.
 */
export function SliderTrack({ className, ...props }: SliderTrackProps) {
  return (
    <AriaSliderTrack
      data-slot="track"
      className={[
        RAIL,
        // `group` so the handle can read the orientation: React Aria publishes it on the track and not
        // on the thumb, and the thumb needs it to centre itself in the cross axis.
        'group relative flex touch-none items-center',
        'data-[orientation=vertical]:flex-col',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
      {...props}
    />
  )
}

/**
 * The filled part of the rail — from the start to the thumb, or between the two thumbs of a range.
 * Use it as `Slider.Fill`.
 *
 * Exported as `SliderFill` only so tooling can resolve it; consume the compound form
 * `Slider.Fill`.
 */
export function SliderFill({
  className,
  tone = 'accent',
  ...props
}: SliderFillProps) {
  return (
    <AriaSliderFill
      data-slot="fill"
      className={[FILL, TONE[tone] ?? TONE.accent, className]
        .filter(Boolean)
        .join(' ')}
      {...props}
    />
  )
}

/**
 * The message shown while the slider is `isInvalid`. Use it as `Slider.Error`.
 *
 * **React Aria's slider is not a field, so this slot is this library's rather than React Aria's.**
 * `Slider` has no `isInvalid` to read and no `FieldError` to render into — the two are the same
 * fact, because a `FieldError` renders only from the context a field publishes. `Slider`
 * publishes that context itself, from the `isInvalid` prop above it, which is what lets a slider
 * bound to a form say what failed instead of only refusing to submit.
 *
 * What that costs is worth stating: the message is **the caller's**. Every other `Error` slot in
 * this library can be left empty and will render whatever React Aria's own validation produced;
 * this one renders its children. That is not a gap to close later — there is no React Aria
 * validation for a slider to surface, and this is the whole of what one can be given.
 *
 * Exported as `SliderError` only so tooling can resolve it; consume the compound form
 * `Slider.Error`.
 */
export function SliderError({ className, ...props }: SliderErrorProps) {
  const validation = useContext(FieldValidationContext)
  return (
    <AriaFieldError
      // The id the thumb points its `aria-describedby` at. It belongs to the control rather than
      // to this slot, so that the message and the reference to it cannot drift apart.
      id={validation?.errorId}
      data-slot="error"
      className={[ERROR, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * A handle. Use it as `Slider.Thumb` — once for a value, twice for a range, with an `index` and a
 * `label` each so a screen reader can tell the two apart.
 *
 * Exported as `SliderThumb` only so tooling can resolve it; consume the compound form
 * `Slider.Thumb`.
 */
export function SliderThumb({ className, label, ...props }: SliderThumbProps) {
  const validation = useContext(FieldValidationContext)
  return (
    <AriaSliderThumb
      // React Aria renders an inner wrapper around the input, so the input's parent is *not* the
      // styled handle. `data-slot` is the hook, as it is on the fill.
      data-slot="thumb"
      aria-label={label}
      // **`isInvalid` is deprecated on a React Aria slider thumb, with no replacement — and it is
      // still the only thing that reaches the range input.** The grip is a picture; the input is
      // what a screen reader reads the value from, and it is what `aria-describedby` has to be
      // put on. Dropping the prop would paint a red message at nobody who cannot see it, so it is
      // used knowingly, and the assertion that keeps it honest is on the input's own attributes.
      isInvalid={validation?.isInvalid || undefined}
      aria-describedby={validation?.isInvalid ? validation.errorId : undefined}
      className={[THUMB, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * A slider is a compound because its parts are addressable: the label names it, the value announces
 * it, the track takes the pointer, the fill shows how far, and the thumb is what you drag. A
 * consumer restyling the rail should not have to reach into a component that has an opinion about
 * the thumb.
 */
export const Slider = Object.assign(SliderRoot, {
  Header: SliderHeader,
  Label: SliderLabel,
  Value: SliderValue,
  Track: SliderTrack,
  Fill: SliderFill,
  Thumb: SliderThumb,
  Error: SliderError,
})

import { useId } from 'react'

/**
 * A single series over time, with no axes and no labels — the shape of the last N readings, sized to sit
 * in a table cell.
 *
 * ```tsx
 * <Sparkline data={[12, 18, 15, 24, 21, 30]} label="Requests, last 6 hours" />
 * ```
 *
 * **This is the replica's own chart, not an invention.** `pulse-replica/js/system.js` draws it in
 * `drawSpark`: a teal polyline with round joins over a **dot-grid zone**, the line inset from the top and
 * the zone stopping short of the bottom so the two do not share an edge. The dashboard uses it at
 * `300×84` in a monitor row and the sheet at `306×52`; both are the same drawing at different sizes, which
 * is why every measurement here is a fraction of the box rather than a pixel value.
 *
 * Three things it inherits from the sheet and one it does not:
 *
 * - The stroke is `var(--color-primary)` rather than the replica's `#71FFF6`. Same colour in the dark theme,
 *   and it follows the token into the light one — the replica is dark-only, so it can afford the literal.
 * - The dots are `rgba(255,255,255,.32)` at a 0.9 radius on a 7.7px pitch, which is `.ds-dotgrid`'s texture
 *   at a heavier weight, drawn as an SVG `<pattern>` because a `<rect>` cannot take a CSS background.
 * - `preserveAspectRatio="none"` so the drawing stretches to whatever box it is given — the replica sets it
 *   for the same reason, and it is what lets one component serve a 300px cell and a 52px one.
 *
 * **It is a picture, not a control.** There is no hover, no tooltip and no focus: the numbers behind it are
 * a chart's job, and this is the thumbnail. The `<svg>` carries `role="img"` and a `label`, because the
 * replica marks its own sparklines `aria-hidden` and a screen reader is then told nothing at all — a
 * monitor's trend is the point of the cell.
 */
export interface SparklineProps {
  /** The series, oldest first. One point per reading. */
  data: number[]
  /** Width in user units. Stretches to the box it is given. */
  width?: number
  /** Height in user units. Stretches to the box it is given. */
  height?: number
  /** What this series is, for a screen reader. A sparkline has no other text. */
  label: string
  className?: string
}

/** Where the dot-grid zone starts, as a fraction of the height — 26/84 in the replica. */
const DOT_TOP = 26 / 84
/** Where it stops, as a fraction — the replica leaves 14/84 clear below it. */
const DOT_BOTTOM = 14 / 84

/** Half the 2px stroke, so a point on the edge of the data range is not clipped by the viewBox. */
const INSET = 1

function toPath(data: number[], width: number, height: number) {
  const min = Math.min(...data)
  const max = Math.max(...data)
  // A flat series has no range to scale into; draw it down the middle rather than dividing by zero.
  const span = max - min || 1
  const usableHeight = height - INSET * 2
  return data
    .map((value, index) => {
      const x =
        data.length === 1
          ? width / 2
          : INSET + (index / (data.length - 1)) * (width - INSET * 2)
      const y = INSET + (1 - (value - min) / span) * usableHeight
      return `${index === 0 ? 'M' : 'L'}${x.toFixed(1)} ${y.toFixed(1)}`
    })
    .join(' ')
}

export function Sparkline({
  data,
  width = 300,
  height = 84,
  label,
  className,
}: SparklineProps) {
  // `<pattern>` ids are document-global, so two sparklines on a page would otherwise share the first
  // one's dots — and the second would disappear when the first unmounted.
  const id = useId()
  const patternId = `sparkline-dots-${id}`
  const zoneTop = height * DOT_TOP
  const zoneHeight = height - zoneTop - height * DOT_BOTTOM

  return (
    <svg
      data-slot="sparkline"
      // **The width and height are rendered, not only declared in the viewBox.** An inline `<svg>`
      // carrying a viewBox and no CSS size collapses to nothing in a flex context — the first version of
      // this component did exactly that, drew a perfectly correct path into invisible space, and passed
      // its own tests, which checked the `d` attribute and never the box. The replica writes
      // `width="300" height="84"` on the element for the same reason; a `className` can still stretch it,
      // which is what `preserveAspectRatio="none"` is for.
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      preserveAspectRatio="none"
      role="img"
      aria-label={label}
      className={className}
    >
      <defs>
        <pattern
          id={patternId}
          width="7.7"
          height="7.7"
          patternUnits="userSpaceOnUse"
        >
          <circle cx="0.9" cy="0.9" r="0.9" fill="rgba(255,255,255,0.32)" />
        </pattern>
      </defs>
      <rect
        data-slot="sparkline-zone"
        x="0"
        y={zoneTop}
        width={width}
        height={zoneHeight}
        fill={`url(#${patternId})`}
      />
      <path
        data-slot="sparkline-line"
        d={toPath(data, width, height)}
        fill="none"
        stroke="var(--color-primary)"
        strokeWidth="2"
        strokeLinejoin="round"
        strokeLinecap="round"
        vectorEffect="non-scaling-stroke"
      />
    </svg>
  )
}

import {
  FieldError as AriaFieldError,
  SwitchButton as AriaSwitchButton,
  SwitchField as AriaSwitchField,
} from 'react-aria-components'
import type {
  FieldErrorProps as AriaFieldErrorProps,
  SwitchButtonProps as AriaSwitchButtonProps,
  SwitchFieldProps as AriaSwitchFieldProps,
} from 'react-aria-components'

import { ERROR } from '../field'

/**
 * The sheet's `.ds-switch`.
 *
 * React Aria splits a switch in two: `SwitchField` is the wrapper that owns the value
 * and provides the validation and help-text contexts, and `SwitchButton` is the
 * `<label>` you actually click. The `<label>` is therefore the control root, which is
 * where every state lands — `data-selected`, `data-hovered`, `data-focus-visible` and
 * the rest all sit on it, exactly as they do on `Checkbox` and `Radio`.
 *
 * So the same rule applies: publish the state here as custom properties and let the
 * track read them, rather than reaching a child through a group variant. A group
 * variant sorts at the same specificity as a plain utility, so it would silently lose
 * to the track's own resting edge. See the longer note in `Checkbox.tsx`.
 *
 * The four edge rules are deliberately built so that no two can match at once: hover
 * excludes invalid and read-only, and invalid is one step more specific than selected.
 * That leaves the cascade decided by specificity rather than by source order, which is
 * the only way it stays predictable when Tailwind sorts these for us.
 */
const CONTROL = [
  'inline-flex items-center gap-2.5 cursor-pointer select-none',
  'data-[disabled]:cursor-not-allowed data-[disabled]:opacity-35',
  // Read-only keeps its state at full strength, as a read-only field does: the
  // position of the knob is the content, and the only affordance it loses is the
  // hover, which is dropped on it below.
  'data-[readonly]:cursor-not-allowed',
  // rest
  '[--switch-edge:var(--color-input)]',
  '[--switch-fill:transparent]',
  '[--switch-knob:var(--color-muted-foreground)]',
  '[--switch-knob-x:0px]',
  '[--switch-ring:transparent]',
  'data-[selected]:[--switch-fill:var(--color-primary)]',
  'data-[selected]:[--switch-knob:var(--color-ink)]',
  'data-[selected]:[--switch-knob-x:20px]',
  'data-[selected]:[--switch-edge:var(--color-primary)]',
  // Invalid is a failure the user has to see, so it outranks the selected fill.
  'data-[invalid]:not-data-[disabled]:[--switch-edge:var(--color-destructive)]',
  // Hover only brightens the edge — the fill stays put, which is the sheet's own
  // pair: a selected switch keeps its teal and gains a white rim, rather than
  // inverting the way a checked checkbox does.
  'data-[hovered]:not-data-[invalid]:not-data-[readonly]:[--switch-edge:var(--color-foreground)]',
  // The ring is drawn on the track, because the control is a 1x1 hidden input.
  'data-[focus-visible]:[--switch-ring:var(--color-primary)]',
].join(' ')

/**
 * The sheet's `.ds-switch-track`: 40x20, fully rounded, a transparent fill and a
 * hairline edge. `--input` rather than the sheet's 40% white, for the
 * same reason the inputs use it — a control boundary needs 3:1 on *both* pages, and
 * 40% measures 2.85:1 on the light one.
 */
const TRACK = [
  'relative h-5 w-10 flex-none rounded-full',
  'border border-(--switch-edge) bg-(--switch-fill)',
  // Transparent at rest rather than `outline-none`, so the ring fades in with the
  // track's own colours instead of switching on and off.
  'outline-1 outline-offset-[3px] outline-(--switch-ring)',
  'transition-[background-color,border-color,outline-color] duration-(--duration-base) ease-pulse',
].join(' ')

/**
 * The sheet's `.ds-switch-knob`: 14px, inset 2px. The sheet's `translate: 20px` is
 * exactly the track's inner width minus the knob and both insets — 40 - 2 (border) -
 * 2 - 14 - 2 = 20 — so the off and on positions are symmetric, not eyeballed.
 *
 * The travel is the whole state, so under `prefers-reduced-motion` it still moves;
 * only the animation goes. Sliding the knob is not decoration.
 */
const KNOB = [
  'absolute top-0.5 left-0.5 size-3.5 rounded-full',
  'bg-(--switch-knob) translate-x-(--switch-knob-x)',
  'transition-[translate,background-color] duration-(--duration-base) ease-pulse',
  'motion-reduce:transition-none',
].join(' ')

/**
 * The sheet shares `.ds-check-label` between the selection controls, so the switch
 * takes the same 13px at 80% rather than inventing a third label style.
 */
const TEXT = 'text-[13px] text-foreground/80'

/**
 * The wrapper `SwitchField` renders. It stretches to its container by default, so it
 * is held to its content instead — the label inside is what carries the hit area, and
 * a stretched wrapper would put the click target out of step with what is drawn.
 */
const FIELD = 'flex w-fit flex-col gap-2'

export interface SwitchProps extends Omit<
  AriaSwitchFieldProps,
  | 'isDisabled'
  | 'isReadOnly'
  | 'isRequired'
  | 'isInvalid'
  | 'isSelected'
  | 'defaultSelected'
  | 'onChange'
  | 'children'
  | 'className'
> {
  /** React 19 passes `ref` as an ordinary prop, so no `forwardRef` wrapper. */
  ref?: React.Ref<HTMLDivElement>
  /** Disables the control. This is a React Aria prop — there is no `disabled`. */
  isDisabled?: AriaSwitchFieldProps['isDisabled']
  /** Makes the state visible but not changeable. */
  isReadOnly?: AriaSwitchFieldProps['isReadOnly']
  isRequired?: AriaSwitchFieldProps['isRequired']
  isInvalid?: AriaSwitchFieldProps['isInvalid']
  /** The switch owns its state, so it lives here. `onChange(boolean)`. */
  isSelected?: AriaSwitchFieldProps['isSelected']
  defaultSelected?: AriaSwitchFieldProps['defaultSelected']
  onChange?: AriaSwitchFieldProps['onChange']
  /** The name the state is submitted under. */
  name?: AriaSwitchFieldProps['name']
  /** The value submitted while the switch is on. */
  value?: AriaSwitchFieldProps['value']
  /**
   * Layout for the wrapper. The control's own styling is internal, as a field's is —
   * so reach for this to place the switch, not to restyle it.
   */
  className?: string
  /** `Switch.Indicator` and `Switch.Text`, in that order. */
  children?: React.ReactNode
}

export interface SwitchIndicatorProps extends React.HTMLAttributes<HTMLSpanElement> {
  className?: string
}

export interface SwitchTextProps extends React.HTMLAttributes<HTMLSpanElement> {
  children?: React.ReactNode
}

export interface SwitchErrorProps extends AriaFieldErrorProps {
  /** The message, or a function of the field's validation result. */
  children?: AriaFieldErrorProps['children']
}

/**
 * The track and its knob. Use it as `Switch.Indicator`, inside a `Switch`.
 *
 * Exported as `SwitchIndicator` only so tooling can resolve it; consume the compound
 * form `Switch.Indicator`.
 */
export function SwitchIndicator({ className, ...props }: SwitchIndicatorProps) {
  return (
    <span
      data-slot="indicator"
      aria-hidden="true"
      className={[TRACK, className].filter(Boolean).join(' ')}
      {...props}
    >
      <span data-slot="knob" className={KNOB} />
    </span>
  )
}

/**
 * The label of a switch. Use it as `Switch.Text`, beside `Switch.Indicator`. A bare
 * text child renders too, just without the label styling.
 *
 * Exported as `SwitchText` only so tooling can resolve it; consume the compound form
 * `Switch.Text`.
 */
export function SwitchText({ className, children, ...props }: SwitchTextProps) {
  return (
    <span
      data-slot="text"
      className={[TEXT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </span>
  )
}

/**
 * The message shown while the switch is `isInvalid`. Use it as `Switch.Error`.
 *
 * The switch already *paints* invalid — `CONTROL` turns its edge red above every other
 * state — so without this slot a failed switch said something was wrong and could not
 * say what. That matters most where a switch is required rather than merely on, which is
 * the one case a switch has something to fail: a consent, a confirmation.
 *
 * React Aria renders nothing while the field is valid, so it is always safe to include.
 *
 * Exported as `SwitchError` only so tooling can resolve it; consume the compound form
 * `Switch.Error`.
 */
export function SwitchError({ className, ...props }: SwitchErrorProps) {
  return (
    <AriaFieldError
      className={[ERROR, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * The clickable half — a `<label>` wrapping the hidden input. Styled element, not
 * exported: `Switch` below is the public symbol, and docgen reads the JSDoc from the
 * exported declaration, not this one.
 *
 * It exists as a separate element only because React Aria requires it to nest inside
 * `SwitchField`, which is what supplies the value. A consumer never writes it.
 */
function SwitchButton({
  className,
  children,
  ...props
}: AriaSwitchButtonProps) {
  return (
    <AriaSwitchButton
      className={[CONTROL, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaSwitchButton>
  )
}

/**
 * A switch — the sheet's `.ds-switch`. An on/off setting, unlike a checkbox, which is
 * one choice among several: the state reads from which side the knob sits on, and the
 * change takes effect at once rather than on submit.
 *
 * ```tsx
 * <Switch defaultSelected>
 *   <Switch.Indicator />
 *   <Switch.Text>Auto-retry failed checks</Switch.Text>
 * </Switch>
 * ```
 *
 * The slots are explicit, like `Checkbox.Indicator` and `Checkbox.Text`: `Switch`
 * draws the track and slides the knob for you, and `Switch.Text` the label. A bare
 * text child still renders, it just misses the label styling.
 *
 * `Switch.Error` is the message for an `isInvalid` switch — a required consent, a
 * confirmation that was not given. The control already turns its edge red when it is
 * invalid; this is where it says why.
 *
 * Built on `SwitchField` + `SwitchButton`, which is the pair React Aria now points at —
 * `Switch` itself is deprecated in 1.22. `SwitchField` is the wrapper that owns the
 * value, so the label it renders is the control root and every state lands on it.
 */
export const Switch = Object.assign(
  function Switch({ ref, className, children, ...props }: SwitchProps) {
    return (
      <AriaSwitchField
        ref={ref}
        className={[FIELD, className].filter(Boolean).join(' ')}
        {...props}
      >
        <SwitchButton>{children}</SwitchButton>
      </AriaSwitchField>
    )
  },
  { Indicator: SwitchIndicator, Text: SwitchText, Error: SwitchError },
)

import { Checkbox } from '../Checkbox/Checkbox'
import {
  Cell as AriaCell,
  Column as AriaColumn,
  ColumnResizer as AriaColumnResizer,
  ResizableTableContainer as AriaResizableTableContainer,
  TableFooter as AriaTableFooter,
  Row as AriaRow,
  Table as AriaTable,
  TableBody as AriaTableBody,
  TableHeader as AriaTableHeader,
  TableLoadMoreItem as AriaTableLoadMoreItem,
} from 'react-aria-components'
import { LOAD_MORE, LoadMoreSpinner } from '../loadMore'
import type {
  CellProps as AriaCellProps,
  ColumnProps as AriaColumnProps,
  ColumnResizerProps as AriaColumnResizerProps,
  ResizableTableContainerProps as AriaResizableTableContainerProps,
  TableFooterProps as AriaTableFooterProps,
  RowProps as AriaRowProps,
  TableBodyProps as AriaTableBodyProps,
  TableHeaderProps as AriaTableHeaderProps,
  TableProps as AriaTableProps,
  TableLoadMoreItemProps as AriaTableLoadMoreItemProps,
} from 'react-aria-components'

/**
 * The sheet's `.ds-rows` and `.ds-row`: a panel-coloured stack separated by hairlines, closed by
 * a softer one. The sheet builds its rows out of a grid with fixed column widths, because it is
 * laying out one dashboard; a table is a table, so the columns are the table's own and the
 * surfaces are what get borrowed.
 */
const ROOT = 'w-full border-collapse border-b border-border-soft text-start'

/**
 * The sheet gives a row's own label — `.ds-row__label`, the name of the thing — 12px uppercase
 * letterspaced, and its figures 16–20px. Those are cell contents, not a header. The column
 * headings take the sheet's quieter legend (`.ds-select-group-label`): 11px, spaced, at 45%.
 */
const FOOTER = 'border-t border-border text-foreground/60'

const SELECTION_GUTTER =
  'has-[[data-slot=selection]]:w-12 has-[[data-slot=selection]]:px-3'

const COLUMN = [
  'relative border-b border-border px-5 py-2.5 text-start',
  SELECTION_GUTTER,
  'text-[11px] font-normal uppercase tracking-[0.08em] text-foreground/45',
  // A transparent outline at rest, never `outline-none` — see AGENTS.md. With `outline-none` the
  // focus ring below could never draw: it sets the shared --tw-outline-style that outline-1 reads back.
  'outline-1 -outline-offset-2 outline-transparent',
  'data-[focus-visible]:outline-1 data-[focus-visible]:-outline-offset-2',
  'data-[focus-visible]:outline-ring',
  'data-[disabled]:cursor-not-allowed data-[disabled]:opacity-35',
].join(' ')

/**
 * The sheet's `.ds-row`: a panel surface with a hairline under it, and its last row without one
 * because `.ds-rows` closes the stack itself.
 *
 * Its hover is the native `:hover` — see below — and it is a *lighter solid*, not a wash: the
 * sheet picks `#12161c` against `.ds-panel`'s
 * `#0D1015`, which is `--muted` here. A translucent overlay would look similar over the
 * page and quite different over anything else, and it would leave the row see-through — a row is
 * a surface, and a surface does not become a window on hover.
 */
const ROW = [
  'border-b border-border bg-card last:border-b-0',
  'transition-colors duration-(--duration-fast) ease-pulse',
  // The native `:hover`, not `data-[hovered]` — which React Aria does set, but wires to pointer
  // *enter*, so a pointer over a cell does not shade its row. For a static surface like a row the
  // pseudo-class is both correct and what the sheet uses (`.ds-row--hover:hover`). Note that
  // neither route can be driven from a story: see the note in Table.stories.tsx.
  'hover:bg-muted',
  'data-[selected]:bg-muted',
  'data-[pressed]:bg-foreground/10',
  'data-[focus-visible]:outline-1 data-[focus-visible]:-outline-offset-2',
  'data-[focus-visible]:outline-ring',
  'data-[disabled]:opacity-40',
].join(' ')

/**
 * The sheet's `.ds-row__cell`: 13px at 75%, with the row's own name at full strength. That name is
 * the cell React Aria marks as the row header, so it is styled off the role rather than asked for
 * by a prop — one place to write it, and it cannot drift from which column is the row's identity.
 */
const CELL = [
  'px-5 py-3.5 align-middle',
  SELECTION_GUTTER,
  'text-[13px] leading-[1.5] text-foreground/75',
  // **A number in a column must not move as it changes.** The body font is monospace today, so
  // this is invisible — which is exactly why it has to come from the property and not from the
  // typeface: the day a theme picks a proportional family, the column starts dancing.
  'tabular-nums',
  // The other half of a table that survives its data. An auto-layout table ignores the root's
  // `overflow-wrap: break-word` while it measures a cell, so a long hostname or URL widens the
  // table instead of wrapping inside it.
  'wrap-anywhere',
  '[&[role=rowheader]]:text-foreground',
  'data-[focus-visible]:outline-1 data-[focus-visible]:-outline-offset-2',
  'data-[focus-visible]:outline-ring',
].join(' ')

/**
 * The selection checkbox, drawn to sit in a table cell rather than beside a label: no text, and
 * the target is the control itself.
 */
const SELECTION = 'flex items-center justify-center'

export interface TableSelectionProps extends React.ComponentProps<
  typeof Checkbox
> {
  /** React 19 passes `ref` as an ordinary prop, so no `forwardRef` wrapper. */
  ref?: React.Ref<HTMLLabelElement>
}

/**
 * The checkbox that selects a row. Use it as `Table.Selection` — once in a `Table.Column` of its
 * own, once inside a `Table.Cell` in each row.
 *
 * ```tsx
 * <Table selectionMode="multiple">
 *   <Table.Column width={48}><Table.Selection /></Table.Column>
 *   ...
 *   <Table.Cell><Table.Selection /></Table.Cell>
 * ```
 *
 * **It is not wired to anything.** React Aria finds it by its `slot="selection"` and drives it:
 * the one in the column heading becomes select-all with its own **indeterminate** state when some
 * rows are chosen, and each row's own becomes that row's checkbox. Nothing here passes
 * `isSelected` or `onChange`, and passing them would fight the table.
 *
 * Exported as `TableSelection` only so tooling can resolve it; consume the compound form
 * `Table.Selection`.
 */
export function TableSelection({ className, ...props }: TableSelectionProps) {
  return (
    <Checkbox
      slot="selection"
      data-slot="selection"
      className={[SELECTION, className].filter(Boolean).join(' ')}
      {...props}
    >
      <Checkbox.Indicator />
    </Checkbox>
  )
}

export interface TableProps extends Omit<
  AriaTableProps,
  'children' | 'className'
> {
  /** React 19 passes `ref` as an ordinary prop, so no `forwardRef` wrapper. */
  ref?: React.Ref<HTMLTableElement>
  /**
   * Which rows are disabled, by the same keys their `id`s use. A table has no `isDisabled` of its
   * own — disabling one row of a table is a much more common thing to want than disabling all of
   * them, and React Aria's model is the per-row one.
   */
  disabledKeys?: AriaTableProps['disabledKeys']
  /** Which rows are selected, in multiple mode. */
  selectedKeys?: AriaTableProps['selectedKeys']
  defaultSelectedKeys?: AriaTableProps['defaultSelectedKeys']
  onSelectionChange?: AriaTableProps['onSelectionChange']
  selectionMode?: AriaTableProps['selectionMode']
  className?: string
  /** `Table.Header`, then `Table.Body`. */
  children?: React.ReactNode
}

export interface TableHeaderProps extends Omit<
  AriaTableHeaderProps<object>,
  'children' | 'className'
> {
  className?: string
  /** The `Table.Column`s this table is made of. */
  children?: React.ReactNode
}

export interface TableColumnProps extends Omit<
  AriaColumnProps,
  'children' | 'className'
> {
  /** Marks the column whose cell names the row. Exactly one per table. */
  isRowHeader?: AriaColumnProps['isRowHeader']
  /** Fixes the column's width, as the sheet's grid does for its own. */
  width?: AriaColumnProps['width']
  className?: string
  children?: React.ReactNode
}

export interface TableBodyProps extends Omit<
  AriaTableBodyProps<object>,
  'children' | 'className'
> {
  className?: string
  /** What to draw when there is nothing to show — an empty table reads as a broken one. */
  renderEmptyState?: AriaTableBodyProps<object>['renderEmptyState']
  /** The `Table.Row`s. */
  children?: React.ReactNode
}

export interface TableRowProps extends Omit<
  AriaRowProps<object>,
  'children' | 'className'
> {
  className?: string
  /** The `Table.Cell`s, one per column. */
  children?: React.ReactNode
}

export interface TableCellProps extends Omit<
  AriaCellProps,
  'children' | 'className'
> {
  className?: string
  children?: React.ReactNode
}

/**
 * The column headings. Use it as `Table.Header`, with `Table.Column`s inside.
 *
 * Exported as `TableHeader` only so tooling can resolve it; consume the compound form
 * `Table.Header`.
 */
export function TableHeader({
  className,
  children,
  ...props
}: TableHeaderProps) {
  return (
    <AriaTableHeader className={className} {...props}>
      {children}
    </AriaTableHeader>
  )
}

/**
 * One column — its heading, and the width every cell under it takes. Use it as `Table.Column`.
 * Mark exactly one with `isRowHeader`: that is the column whose cell names the row, and it is
 * what a screen reader reads out before the rest of the row.
 *
 * Exported as `TableColumn` only so tooling can resolve it; consume the compound form
 * `Table.Column`.
 */
export function TableColumn({
  className,
  children,
  ...props
}: TableColumnProps) {
  return (
    <AriaColumn
      className={[COLUMN, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaColumn>
  )
}

/**
 * The rows. Use it as `Table.Body`, with `Table.Row`s inside. `renderEmptyState` lives here rather
 * than on the table, because it replaces the body — a table with nothing in it reads as a table
 * that failed rather than as one with nothing to say.
 *
 * Exported as `TableBody` only so tooling can resolve it; consume the compound form `Table.Body`.
 */
export function TableBody({ className, children, ...props }: TableBodyProps) {
  return (
    <AriaTableBody className={className} {...props}>
      {children}
    </AriaTableBody>
  )
}

/**
 * One row. Use it as `Table.Row`; its `id` is what `selectedKeys` speaks in.
 *
 * Exported as `TableRow` only so tooling can resolve it; consume the compound form `Table.Row`.
 */
export function TableRow({ className, children, ...props }: TableRowProps) {
  return (
    <AriaRow className={[ROW, className].filter(Boolean).join(' ')} {...props}>
      {children}
    </AriaRow>
  )
}

/**
 * One cell. Use it as `Table.Cell`. The cell under the `isRowHeader` column carries
 * `role="rowheader"` and is styled at full strength from that role, so which column identifies the
 * row is decided once, on the column.
 *
 * Exported as `TableCell` only so tooling can resolve it; consume the compound form `Table.Cell`.
 */
export function TableCell({ className, children, ...props }: TableCellProps) {
  return (
    <AriaCell
      className={[CELL, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaCell>
  )
}

/**
 * Styled element. Not exported — `Table` below is the public symbol, and docgen reads the JSDoc
 * from the *exported* declaration, not this one.
 */
/**
 * The closing row group. Use it as `Table.Footer`, after `Table.Body`.
 *
 * **A footer is not a body row that happens to be last.** It is the table's conclusion — the totals, the
 * count, the average — and it is the one row a reader arrives at deliberately rather than scanning past.
 * So it is separated by a line above it instead of below, and its type is a step quieter than the data,
 * which is the same relationship the header has at the other end.
 *
 * It holds `Table.Row`s like the body does, because it is the same collection machinery.
 */
export function TableFooter({
  className,
  ...props
}: AriaTableFooterProps<object>) {
  return (
    <AriaTableFooter
      data-slot="table-footer"
      className={[FOOTER, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

function TableRoot({ ref, className, children, ...props }: TableProps) {
  return (
    <AriaTable
      ref={ref}
      className={[ROOT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaTable>
  )
}

/**
 * The sheet's table rows — `.ds-rows` and `.ds-row`. A panel-coloured stack separated by
 * hairlines, closed by a softer one, with a row's own name at full strength and everything else
 * at 75%.
 *
 * ```tsx
 * <Table aria-label="Monitors">
 *   <Table.Header>
 *     <Table.Column isRowHeader>Monitor</Table.Column>
 *     <Table.Column>Status</Table.Column>
 *     <Table.Column>Uptime</Table.Column>
 *   </Table.Header>
 *   <Table.Body>
 *     <Table.Row id="fra1">
 *       <Table.Cell>fra1 · Frankfurt</Table.Cell>
 *       <Table.Cell>Up</Table.Cell>
 *       <Table.Cell>99.98%</Table.Cell>
 *     </Table.Row>
 *   </Table.Body>
 * </Table>
 * ```
 *
 * Give it an `aria-label` — a table with no caption and no label is a grid of numbers with no
 * subject.
 *
 * **The header is the table's, not the sheet's.** The sheet has no table header at all: its rows
 * are a dashboard grid, where each cell holds its own 12px uppercase label above its value, so
 * the row carries its labels with it. A real table says them once at the top instead, and the
 * header takes the sheet's *quieter* legend style for it. Row headers are the exception — the
 * column marked `isRowHeader` is the row's own name, so it keeps full strength.
 *
 * `Table.Cell` has no numeric variant. The sheet's big yellow figure — 20px, letterspaced, in
 * `--warning` — belongs to its dashboard, where a number is the point of the row; in a table
 * it is one column of many, and a table of yellow figures is a table where nothing stands out.
 * Pass a `className` when a column really is the point.
 */

/**
 * The scroll container that makes a column resizable.
 *
 * **A `ColumnResizer` throws without it** — *"Wrap your `<Table>` in a `<ResizableTableContainer>` to
 * enable column resizing"* — so the two are one feature and not two props. It walks up to the first
 * scrollable element and measures that, which is why it has to be the thing that scrolls.
 */
export function TableResizable({
  className,
  children,
  ...props
}: AriaResizableTableContainerProps) {
  return (
    <AriaResizableTableContainer
      data-slot="resizable-table"
      className={['w-full overflow-x-auto overscroll-x-contain', className]
        .filter(Boolean)
        .join(' ')}
      {...props}
    >
      {children}
    </AriaResizableTableContainer>
  )
}

/**
 * The grip on a column's trailing edge. Use it as `Table.Resizer`, inside a `Table.Column`.
 *
 * It is a drag handle **and**, because React Aria renders an `<input>` inside it, a keyboard control:
 * focus it and the arrow keys widen and narrow the column, which is the only version of this that is
 * usable without a mouse.
 *
 * The hairline appears on hover and turns teal while the drag is live — the accent for a genuinely active
 * state, the same rule a selected table row follows. It is **never an inset fill**: the grip sits over the
 * column's own edge, so it must not eat into the cell's padding.
 *
 * `outline-2 outline-transparent` at rest rather than `outline-none`, or its own focus ring could never
 * draw — see `Table.Column`, which had exactly that bug.
 */
export function TableResizer({ className, ...props }: AriaColumnResizerProps) {
  return (
    <AriaColumnResizer
      data-slot="column-resizer"
      className={[
        'absolute inset-y-0 -end-px z-10 w-1.5 cursor-col-resize touch-none select-none',
        'outline-2 outline-offset-1 outline-transparent',
        'transition-colors duration-(--duration-fast) ease-pulse',
        'data-[hovered]:bg-input',
        'data-[resizing]:bg-primary',
        'data-[focus-visible]:outline-ring',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
      {...props}
    />
  )
}

/**
 * The row that asks for the next page. Use it as `Table.LoadMore`, last inside `Table`.
 *
 * It watches the scroll position and calls `onLoadMore` when it comes into view.
 *
 * **It only works inside a virtualized collection** — `Virtualizer` supplies the scroll container the
 * sentinel observes. Without one React Aria renders nothing for it at all when idle, so there is no
 * sentinel and no request. `GridList.LoadMore` carries the end-to-end proof; this is the same machinery in
 * another collection.
 *
 * **It draws nothing until `isLoading`**, and the spinner is `motion-safe`.
 */
export function TableLoadMore({
  className,
  children,
  ...props
}: AriaTableLoadMoreItemProps) {
  return (
    <AriaTableLoadMoreItem
      data-slot="table-load-more"
      className={[LOAD_MORE, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children ?? <LoadMoreSpinner />}
    </AriaTableLoadMoreItem>
  )
}

export const Table = Object.assign(TableRoot, {
  Selection: TableSelection,
  Header: TableHeader,
  Column: TableColumn,
  Body: TableBody,
  Row: TableRow,
  Cell: TableCell,
  Resizable: TableResizable,
  Resizer: TableResizer,
  Footer: TableFooter,
  LoadMore: TableLoadMore,
})

import {
  Tab as AriaTab,
  TabList as AriaTabList,
  TabPanel as AriaTabPanel,
  TabPanels as AriaTabPanels,
  Tabs as AriaTabs,
} from 'react-aria-components'
import type {
  TabListProps as AriaTabListProps,
  TabPanelProps as AriaTabPanelProps,
  TabPanelsProps as AriaTabPanelsProps,
  TabProps as AriaTabProps,
  TabsProps as AriaTabsProps,
} from 'react-aria-components'

/**
 * The sheet's `.ds-tabs`: a row with one hairline under all of it, which each tab's indicator
 * then sits on top of. The line is at 30% — `--border-soft` — which is the one place in the
 * sheet where a boundary is deliberately this quiet, because the selected tab's 2px of teal is
 * what is meant to be read.
 */
const LIST = [
  'flex border-b border-border-soft',
  // The orientation describes the strip, so the strip is what turns. A vertical list runs down
  // the page, and its hairline moves to the trailing edge — the same treatment as the sheet's
  // horizontal one, which is a line along the strip's long side with the indicator over it.
  'aria-[orientation=vertical]:flex-col',
  'aria-[orientation=vertical]:border-b-0 aria-[orientation=vertical]:border-e',
].join(' ')

/**
 * The sheet's `.ds-tab`. `relative` because the indicator is drawn against it, and the indicator
 * is an `::after` rather than a border so that fading it in cannot move the one above it — which
 * a border going from 0 to 2px would do to every tab in the row.
 */
const TAB = [
  'relative cursor-pointer select-none',
  'bg-transparent px-[18px] py-3 text-[13px] tracking-[0.02em] text-foreground/55',
  'transition-colors duration-(--duration-fast) ease-pulse',
  'data-[hovered]:text-foreground',
  'data-[selected]:text-foreground',
  'data-[pressed]:text-foreground',
  // The indicator spans the tab's own text, not its padding, so it reads as belonging to the
  // label rather than to the cell.
  'after:absolute after:inset-x-[18px] after:-bottom-px after:h-0.5',
  'after:bg-primary after:opacity-0 after:transition-opacity after:duration-(--duration-fast)',
  // The indicator fades on the system's own curve, not on Tailwind's default one.
  'after:ease-pulse',
  // The same indicator, turned: down the tab's own text rather than across it, over the strip's
  // hairline at its trailing edge. Written against the list's `aria-orientation` rather than a
  // group variant, because a group variant ties on specificity with the rules above and would
  // leave the outcome to source order.
  // Physical block edges rather than `inset-y-*`: the horizontal rule sets `bottom` physically,
  // and a logical `inset-block` would leave the two fighting over the same box edge.
  // `start-auto` rather than `inset-x-auto`, because the latter writes both inline edges and
  // would clobber the `end-` offset below.
  '[[aria-orientation=vertical]_&]:after:start-auto',
  '[[aria-orientation=vertical]_&]:after:end-[-1px]',
  '[[aria-orientation=vertical]_&]:after:top-3',
  '[[aria-orientation=vertical]_&]:after:bottom-3',
  '[[aria-orientation=vertical]_&]:after:h-auto',
  '[[aria-orientation=vertical]_&]:after:w-0.5',
  'data-[selected]:after:opacity-100',
  // The sheet gives a tab the shared ring, unlike a field, whose border is the edge it repeats.
  'data-[focus-visible]:outline-1 data-[focus-visible]:outline-offset-[3px]',
  'data-[focus-visible]:outline-ring',
  'data-[disabled]:cursor-not-allowed data-[disabled]:opacity-35',
].join(' ')

/** The sheet's `.ds-count`: 11px, in the selected-yellow, beside the label. */
const COUNT = 'ms-2 text-[11px] text-warning'

/** The sheet's `.ds-tabpanel`: the panel clears the list by 18px and nothing more. */
const PANEL = [
  'pt-[18px]',
  // A focusable tabpanel that draws nothing is a focusable tabpanel with no focus: the
  // same transparent-outline-at-rest pattern `Table`'s column and `GridList`'s row use.
  'outline-1 -outline-offset-2 outline-transparent',
  'data-[focus-visible]:outline-ring',
].join(' ')

export interface TabsProps extends Omit<
  AriaTabsProps,
  'isDisabled' | 'children' | 'className'
> {
  /** React 19 passes `ref` as an ordinary prop, so no `forwardRef` wrapper. */
  ref?: React.Ref<HTMLDivElement>
  /** Disables the whole set. This is a React Aria prop — there is no `disabled`. */
  isDisabled?: AriaTabsProps['isDisabled']
  /** The set owns the value, as a single key. `onSelectionChange` gives it back. */
  selectedKey?: AriaTabsProps['selectedKey']
  defaultSelectedKey?: AriaTabsProps['defaultSelectedKey']
  onSelectionChange?: AriaTabsProps['onSelectionChange']
  /**
   * Which way the tab list runs. It describes the *strip*, not the panels — a vertical list
   * stacks its tabs and puts its hairline on the trailing edge, and where the panel then sits
   * is the consumer's layout to decide, not this prop's.
   */
  orientation?: AriaTabsProps['orientation']
  className?: string
  /** `Tabs.List`, then `Tabs.Panel`s — or a `Tabs.Panels` around them. */
  children?: React.ReactNode
}

export interface TabsListProps extends Omit<
  AriaTabListProps<object>,
  'children' | 'className'
> {
  className?: string
  children?: React.ReactNode
}

export interface TabsTabProps extends Omit<
  AriaTabProps,
  'isDisabled' | 'children' | 'className'
> {
  /** The tab's label — usually a `Tabs.Count` alongside it. */
  children?: React.ReactNode
  className?: string
}

export interface TabsCountProps extends React.HTMLAttributes<HTMLSpanElement> {
  children?: React.ReactNode
}

export interface TabsPanelsProps extends Omit<
  AriaTabPanelsProps<object>,
  'children' | 'className'
> {
  className?: string
  children?: React.ReactNode
}

export interface TabsPanelProps extends Omit<
  AriaTabPanelProps,
  'children' | 'className'
> {
  className?: string
  children?: React.ReactNode
}

/**
 * The tab strip. Use it as `Tabs.List`. Give it an `aria-label` when there is no visible heading
 * above it, since the list is what a screen reader announces the set by.
 *
 * Exported as `TabsList` only so tooling can resolve it; consume the compound form `Tabs.List`.
 */
export function TabsList({ className, children, ...props }: TabsListProps) {
  return (
    <AriaTabList
      className={[LIST, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaTabList>
  )
}

/**
 * One tab. Use it as `Tabs.Tab`, inside a `Tabs.List`. Its `id` is what ties it to the matching
 * `Tabs.Panel`, and the arrow keys move between tabs from anywhere in the set.
 *
 * Exported as `TabsTab` only so tooling can resolve it; consume the compound form `Tabs.Tab`.
 */
export function TabsTab({ className, children, ...props }: TabsTabProps) {
  return (
    <AriaTab className={[TAB, className].filter(Boolean).join(' ')} {...props}>
      {children}
    </AriaTab>
  )
}

/**
 * A count beside a tab's label, in the sheet's `.ds-count`. Use it as `Tabs.Count`.
 *
 * It is a slot rather than a number passed to `Tabs.Tab`, because a count is frequently the
 * whole reason to look at the tab — how many checks are failing — and the moment it needs a
 * dot, a colour of its own or a title, a prop stops being enough.
 *
 * Exported as `TabsCount` only so tooling can resolve it; consume the compound form
 * `Tabs.Count`.
 */
export function TabsCount({ className, children, ...props }: TabsCountProps) {
  return (
    <span
      data-slot="count"
      className={[COUNT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </span>
  )
}

/**
 * The run of panels. Use it as `Tabs.Panels` around the `Tabs.Panel`s. Optional — the panels
 * work without it — but it keeps the set's two halves readable when the contents are long.
 *
 * Exported as `TabsPanels` only so tooling can resolve it; consume the compound form
 * `Tabs.Panels`.
 */
export function TabsPanels({ className, children, ...props }: TabsPanelsProps) {
  return (
    <AriaTabPanels className={className} {...props}>
      {children}
    </AriaTabPanels>
  )
}

/**
 * The content behind a tab. Use it as `Tabs.Panel`; its `id` matches the tab's. Only the
 * selected panel is rendered — the rest are unmounted, not hidden — so a panel that needs to
 * hold state across a switch has to say so with `shouldForceMount`.
 *
 * Exported as `TabsPanel` only so tooling can resolve it; consume the compound form
 * `Tabs.Panel`.
 */
export function TabsPanel({ className, children, ...props }: TabsPanelProps) {
  return (
    <AriaTabPanel
      className={[PANEL, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaTabPanel>
  )
}

/**
 * Styled element. Not exported — `Tabs` below is the public symbol, and docgen reads the JSDoc
 * from the *exported* declaration, not this one.
 */
function TabsRoot({ ref, className, children, ...props }: TabsProps) {
  return (
    <AriaTabs ref={ref} className={className} {...props}>
      {children}
    </AriaTabs>
  )
}

/**
 * A set of tabs — the sheet's `.ds-tabs` and `.ds-tabpanel`. One panel is shown at a time, and
 * the whole set is a single tab stop: the arrow keys move between tabs rather than the Tab key,
 * which is what lets a keyboard user step past the strip instead of through it.
 *
 * ```tsx
 * <Tabs defaultSelectedKey="overview">
 *   <Tabs.List aria-label="Monitor detail">
 *     <Tabs.Tab id="overview">Overview</Tabs.Tab>
 *     <Tabs.Tab id="checks">
 *       Checks <Tabs.Count>3</Tabs.Count>
 *     </Tabs.Tab>
 *   </Tabs.List>
 *   <Tabs.Panel id="overview">Everything at a glance.</Tabs.Panel>
 *   <Tabs.Panel id="checks">Three failing.</Tabs.Panel>
 * </Tabs>
 * ```
 *
 * Use tabs to switch *views of the same thing*, not to step through a form: a tab set hides its
 * unselected panels, so anything a user must fill in belongs in a page flow rather than behind
 * a tab they might not open.
 */
export const Tabs = Object.assign(TabsRoot, {
  List: TabsList,
  Tab: TabsTab,
  Count: TabsCount,
  Panels: TabsPanels,
