export interface TimeFieldLabelProps extends Omit<AriaLabelProps, 'className'> {
  className?: string
}

export interface TimeFieldGroupProps extends Omit<AriaGroupProps, 'className'> {
  className?: string
}

export interface TimeFieldInputProps extends Omit<
  AriaDateInputProps,
  'children' | 'className'
