  size = 'md',
  className,
  children,
  ...props
}: TimeFieldProps<T>) {
  return (
    <AriaTimeField
      className={[
        FIELD_SIZES[size],
        '[--field-border:var(--color-input)]',
        '[--field-hover:var(--color-foreground)]',
        'flex w-fit flex-col gap-2',
        'data-[disabled]:cursor-not-allowed',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
      {...props}
    >
      {children}
    </AriaTimeField>
  )
}

/**
 * What the time is. Use it as `TimeField.Label`.
