export const TimeField = Object.assign(TimeFieldRoot, {
  Label: TimeFieldLabel,
  Group: TimeFieldGroup,
  Input: TimeFieldInput,
  Hint: TimeFieldHint,
  Error: TimeFieldError,
})

import {
  Button as AriaButton,
  UNSTABLE_Toast as AriaToast,
  UNSTABLE_ToastQueue,
  UNSTABLE_ToastRegion as AriaToastRegion,
} from 'react-aria-components'
import type {
  ButtonProps as AriaButtonProps,
  ToastProps as AriaToastProps,
  ToastRegionProps as AriaToastRegionProps,
} from 'react-aria-components'

/**
 * The sheet has no toast either — the third component here with nothing to copy, after the date
 * picker and the accordion. It borrows the tooltip's surface, which is the closest thing the sheet
 * has to a floating panel: its own panel, a strong hairline, square.
 *
 * **React Aria's toast is marked `UNSTABLE_`**, every part of it. That is a real risk and worth
 * saying out loud rather than burying: the API can change under this component, and the parts are
 * named to make that obvious at every import. It was still the right trade — a queue, a region,
 * auto-dismiss, focus management, and announcements to a screen reader are what a hand-rolled
 * toast gets wrong, and `role="status"` on a div does not get them right.
 */
const REGION =
  // The inset is added to the 16px rather than replacing it, and the `0px` fallback is not
  // optional: inside a `calc()` an unsupported `env()` invalidates the whole declaration.
  'fixed end-4 bottom-[calc(1rem+env(safe-area-inset-bottom,0px))] z-50 flex w-80 max-w-[calc(100vw-2rem)] flex-col gap-2'

const TOAST = [
  'flex items-start gap-3',
  'border border-border-strong bg-card rounded-xl p-3.5',
  // **RAC sets no entering or exiting attribute on a toast, and this file used to say it did.**
  // `Toast` in react-aria-components 1.22.1 writes `data-hovered`, `data-focused` and
  // `data-focus-visible` — the string "animation" does not appear in it — so its entry cannot hang
  // off a hook the way the dialogs' does. It comes from the shared overlay block in `styles.css`
  // instead, keyed on `data-slot="toast"`, which is the same animation every other panel gets on
  // mount. The exit still snaps: RAC removes the node as it leaves, and that is the hook it does
  // not give.
].join(' ')

const CONTENT = 'flex min-w-0 flex-1 flex-col gap-1'

/** The sheet's row legend, at full strength: a toast's heading is read, not scanned. */
const TITLE = 'text-[12px] uppercase tracking-[0.06em] text-foreground'

const TEXT = 'text-[13px] leading-[1.5] text-foreground/70'

const CLOSE = [
  // `relative` is load-bearing: without it the hit area below resolves against the *region*, which
  // is `fixed`, and the whole toast stack becomes one dismiss target.
  'relative flex size-5 shrink-0 items-center justify-center',
  'cursor-pointer text-foreground/45',
  'transition-[color,opacity] duration-(--duration-fast) ease-pulse',
  // 20px of drawing, 40px of target.
  'after:absolute after:content-[""] after:-inset-2.5',
  'data-[hovered]:text-foreground',
  'data-[pressed]:opacity-70',
  'data-[focus-visible]:outline-1 data-[focus-visible]:outline-offset-2',
  'data-[focus-visible]:outline-ring',
].join(' ')

/**
 * The queue, exported as a type as well as a value: `Object.assign` flattens the generic, so a
 * consumer who wants typed `toast.content` has to say so once, on the queue.
 */
export type ToastQueue<T> = UNSTABLE_ToastQueue<T>

export interface ToastRegionProps<T> extends Omit<
  AriaToastRegionProps<T>,
  'children' | 'className'
> {
  className?: string
  /** A function of `{ toast }` returning a `Toast`, or a `Toast.List` of them. */
  children: AriaToastRegionProps<T>['children']
}

export interface ToastProps<T> extends Omit<
  AriaToastProps<T>,
  'children' | 'className' | 'toast'
> {
  /** The toast to render, from the queue `Toast.Region` is draining. Its `content` is what the slots read. */
  toast: AriaToastProps<T>['toast']

  className?: string
  /** A `Toast.Content`, and a `Toast.Close` beside it. */
  children?: React.ReactNode
}

export interface ToastContentProps {
  className?: string
  /** A `Toast.Title` and a `Toast.Text`. */
  children?: React.ReactNode
}

export interface ToastTitleProps extends React.HTMLAttributes<HTMLSpanElement> {
  children?: React.ReactNode
}

export interface ToastTextProps extends React.HTMLAttributes<HTMLSpanElement> {
  children?: React.ReactNode
}

export interface ToastCloseProps extends Omit<
  AriaButtonProps,
  'children' | 'className'
> {
  className?: string
  children?: React.ReactNode
}

/**
 * The corner the toasts collect in. Use it as `Toast.Region`, once, near the root — and only once,
 * because it is the whole of what a screen reader is told is happening on the page.
 *
 * Exported as `ToastRegion` only so tooling can resolve it; consume the compound form
 * `Toast.Region`.
 */
export function ToastRegion<T>({
  className,
  children,
  ...props
}: ToastRegionProps<T>) {
  return (
    <AriaToastRegion
      data-slot="toast-region"
      className={[REGION, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaToastRegion>
  )
}

/**
 * One toast. Use it as `Toast`, inside a `Toast.Region`'s render function.
 *
 * Exported as `ToastItem` only so tooling can resolve it; consume the compound form `Toast`.
 */
export function ToastItem<T>({ className, children, ...props }: ToastProps<T>) {
  return (
    <AriaToast
      data-slot="toast"
      className={[TOAST, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaToast>
  )
}

/**
 * A toast's text. Use it as `Toast.Content`.
 *
 * Exported as `ToastContent` only so tooling can resolve it; consume the compound form
 * `Toast.Content`.
 */
export function ToastContent({ className, children }: ToastContentProps) {
  return (
    <div
      data-slot="content"
      className={[CONTENT, className].filter(Boolean).join(' ')}
    >
      {children}
    </div>
  )
}

/**
 * What the toast is about. Use it as `Toast.Title`, above a `Toast.Text` — React Aria wires the
 * two together so the announcement reads as one message rather than two.
 *
 * Exported as `ToastTitle` only so tooling can resolve it; consume the compound form
 * `Toast.Title`.
 */
export function ToastTitle({ className, children, ...props }: ToastTitleProps) {
  return (
    <span
      data-slot="title"
      className={[TITLE, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </span>
  )
}

/**
 * The detail under it. Use it as `Toast.Text`.
 *
 * Exported as `ToastText` only so tooling can resolve it; consume the compound form
 * `Toast.Text`.
 */
export function ToastText({ className, children, ...props }: ToastTextProps) {
  return (
    <span
      data-slot="text"
      className={[TEXT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </span>
  )
}

/**
 * Dismisses it. Use it as `Toast.Close`. Its `slot="close"` is what tells React Aria it is the
 * dismiss control, so it gets the label, the keyboard handling and the focus return for free —
 * and it is why the slot has to be written here rather than left to the consumer.
 *
 * Exported as `ToastClose` only so tooling can resolve it; consume the compound form
 * `Toast.Close`.
 */
export function ToastClose({ className, children, ...props }: ToastCloseProps) {
  return (
    <AriaButton
      slot="close"
      aria-label="Dismiss"
      className={[CLOSE, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children ?? (
        <svg
          viewBox="0 0 10 10"
          fill="none"
          aria-hidden="true"
          className="size-2.5"
        >
          <path
            d="M1 1L9 9M9 1L1 9"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
          />
        </svg>
      )}
    </AriaButton>
  )
}

/**
 * The sheet has no toast, so this follows the tooltip's surface — its own panel, a strong
 * hairline, square — and React Aria's behaviour.
 *
 * ```tsx
 * const queue = new Toast.Queue({ maxVisibleToasts: 3 })
 *
 * <Toast.Region queue={queue} aria-label="Notifications">
 *   {({ toast }) => (
 *     <Toast toast={toast}>
 *       <Toast.Content>
 *         <Toast.Title>Check failed</Toast.Title>
 *         <Toast.Text>fra1 · Frankfurt stopped responding.</Toast.Text>
 *       </Toast.Content>
 *       <Toast.Close />
 *     </Toast>
 *   )}
 * </Toast.Region>
 *
 * queue.add({ title: 'Check failed' }, { timeout: 5000 })
 * ```
 *
 * **React Aria's toast is `UNSTABLE_` in every part**, and this component is a thin skin over it.
 * The API can move between minor versions. It is still worth it: a queue, a region, auto-dismiss,
 * a pause on hover, focus management and an announcement to a screen reader are precisely what a
 * hand-rolled toast gets wrong.
 *
 * **A toast announces itself, so it should not be the only place anything is said.** It is for
 * what has just happened and needs no answer — anything a user must act on belongs in the page,
 * where it will still be there when they look back. The `timeout` is how long it stays; a toast
 * with no timeout stays until it is dismissed, which is a decision worth making deliberately.
 */
export const Toast = Object.assign(ToastItem, {
  Region: ToastRegion,
  Content: ToastContent,
  Title: ToastTitle,
  Text: ToastText,
  Close: ToastClose,
})

/**
 * The queue the region drains. Create one, push toasts onto it, and pass it to `Toast.Region`.
 *
 * **A named export rather than a slot, and the only thing here that is not a component.** Every other
 * trailing name in this system is a component you can render — `Toast.Title`, `Modal.Content` — so
 * `Toast.Queue` was a name that looked renderable and was a class. Renaming it says what it is.
 */
export const ToastQueue = UNSTABLE_ToastQueue

import { ToggleButtonGroup as AriaToggleButtonGroup } from 'react-aria-components'
import type { ToggleButtonGroupProps as AriaToggleButtonGroupProps } from 'react-aria-components'
import { SEGMENT_SELECTED } from '../segment'

import type { ReactNode } from 'react'

import { ToggleButton } from '../ToggleButton/ToggleButton'
import type { ToggleButtonProps } from '../ToggleButton/ToggleButton'

/**
 * The box, which the segments cannot draw for themselves.
 *
 * Every segment is a `ghost` — border-transparent — so without this the control is a row of words with
 * nothing around it. The border is the group's, and each segment draws only the divider before it, so
 * there are no doubled edges at the joins.
 */
const GROUP = 'inline-flex w-fit border border-input rounded-md'

/**
 * One segment of the group.
 *
 * Two `data-[selected]:` rules do the work, and both are variants — which is what makes them land: a
 * variant rule outranks the plain utility the `ghost` variant declares, whatever order the two reach
 * the stylesheet in. `border-l-line-control` is a variant for the same reason: it has to beat the plain
 * `border-transparent` a ghost button carries.
 *
 * The segment is a `ghost` at rest and a **fill** when it is on, so the group reads as one control with
 * a hole pressed into it. `--btn` is retargeted to teal as well as the background, so the hover recipe —
 * which deepens `--btn` toward ink — follows and a selected segment deepens rather than jumping.
 */
const SEGMENT = SEGMENT_SELECTED

export interface ToggleButtonGroupProps extends Omit<
  AriaToggleButtonGroupProps,
  'children' | 'className'
> {
  /** `single` gives a radio group and `multiple` a row of switches. */
  selectionMode?: AriaToggleButtonGroupProps['selectionMode']
  /** The on segments, by each toggle's `id`. Controlled. */
  selectedKeys?: AriaToggleButtonGroupProps['selectedKeys']
  /** What starts on. Uncontrolled. */
  defaultSelectedKeys?: AriaToggleButtonGroupProps['defaultSelectedKeys']
  /** Called with the new set of keys. */
  onSelectionChange?: AriaToggleButtonGroupProps['onSelectionChange']
  /** Disables the whole group. */
  isDisabled?: AriaToggleButtonGroupProps['isDisabled']
  /** Which way the arrow keys walk. Defaults to horizontal. */
  orientation?: AriaToggleButtonGroupProps['orientation']
  /**
   * Whether the last on segment can be turned off. **`single` makes this `true` by default**, and that
   * is a correction rather than a taste: without it the arrow keys *clear* the selection, so a
   * segmented control can end up showing no current value at all — which answers no question.
   */
  disallowEmptySelection?: AriaToggleButtonGroupProps['disallowEmptySelection']
  className?: string
  children?: ReactNode
}

export interface ToggleButtonGroupButtonProps extends ToggleButtonProps {
  /** The identity this segment carries in the group's value. Required — a segment without one cannot be selected. */
  id: string
}

/**
 * One segment. Use it as `ToggleButtonGroup.Button`.
 *
 * `ghost` is the default variant here rather than the button's own `default`, because a segment is not
 * a button: its fill is the *state*, not the variant. Pass `variant` to override and it wins.
 */
export function ToggleButtonGroupButton({
  className,
  variant = 'ghost',
  ...props
}: ToggleButtonGroupButtonProps) {
  return (
    <ToggleButton
      variant={variant}
      className={[SEGMENT, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * A row of buttons where one — or several — is on. A segmented control.
 *
 * ```tsx
 * <ToggleButtonGroup defaultSelectedKeys={['24h']} selectionMode="single">
 *   <ToggleButtonGroup.Button id="1h">1h</ToggleButtonGroup.Button>
 *   <ToggleButtonGroup.Button id="24h">24h</ToggleButtonGroup.Button>
 *   <ToggleButtonGroup.Button id="7d">7d</ToggleButtonGroup.Button>
 * </ToggleButtonGroup>
 * ```
 *
 * **It is one control with holes pressed into it, not a row of buttons.** The group draws the border and
 * each segment draws the divider before it, so there are no doubled edges at the joins.
 *
 * **The arrow keys move focus, and activation is explicit** — Space, Enter or a click. They do *not*
 * carry the selection with them, and this doc claimed they did until the story was written and disagreed.
 * What matters is the corollary: with `single` the group refuses to be emptied, because React Aria's own
 * default lets the arrow keys clear the selection outright, leaving a segmented control that shows no
 * current value at all.
 *
 * In `multiple` mode it is a row of switches, tabbed into individually. That difference is React Aria's,
 * and it is the reason to use a group rather than place `ToggleButton`s side by side.
 *
 * **A segment is not a `Tab`.** Tabs swap the panel below them; this changes a value the rest of the page
 * reads. Where the sheet has a tab row it has an indicator under the current one; here the current
 * segment is *filled*, because there is no panel for an indicator to point at.
 */
function ToggleButtonGroupRoot({
  className,
  selectionMode,
  disallowEmptySelection,
  children,
  ...props
}: ToggleButtonGroupProps) {
  return (
    <AriaToggleButtonGroup
      data-slot="toggle-button-group"
      selectionMode={selectionMode}
      disallowEmptySelection={
        disallowEmptySelection ?? selectionMode === 'single'
      }
      className={[GROUP, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaToggleButtonGroup>
  )
}

export const ToggleButtonGroup = Object.assign(ToggleButtonGroupRoot, {
  Button: ToggleButtonGroupButton,
})

import {
  Label as AriaLabel,
  Text as AriaText,
  Token as AriaToken,
  TokenField as AriaTokenField,
  TokenInput as AriaTokenInput,
} from 'react-aria-components'
import type {
  LabelProps as AriaLabelProps,
  TextProps as AriaTextProps,
  TokenFieldProps as AriaTokenFieldProps,
  TokenInputProps as AriaTokenInputProps,
  TokenProps as AriaTokenProps,
} from 'react-aria-components'

import type { ReactNode } from 'react'

import { CHIP } from '../TagGroup/TagGroup'
import { FIELD, HINT, INPUT, LABEL } from '../field'

/**
 * The chip a token wears: the tag's box with none of the tag's behaviour.
 *
 * Composed from `CHIP` rather than from `TAG_CHIP`, because a token is not pressable, not focusable
 * and not hoverable — it is a piece of the *value* with a box round it. Writing it as `TAG_CHIP` plus a
 * `cursor-text` override would be two plain utilities at the same specificity, which ties and is
 * decided by Tailwind's source order rather than by intent.
 */
export const TOKEN_CHIP = [
  CHIP,
  'cursor-text select-none',
  'border-input bg-muted text-foreground',
].join(' ')

export interface TokenFieldProps extends Omit<
  AriaTokenFieldProps,
  'children' | 'className' | 'value' | 'defaultValue' | 'onChange'
> {
  /** The value. Controlled, so pass `onChange` with it. */
  value?: AriaTokenFieldProps['value']
  /** What it starts with, as a `TokenFieldValue`. Uncontrolled. */
  defaultValue?: AriaTokenFieldProps['defaultValue']
  /** Called with the whole `TokenFieldValue`, whose `segments` are the text and the tokens in order. */
  onChange?: AriaTokenFieldProps['onChange']
  className?: string
  children?: ReactNode
}

export interface TokenFieldLabelProps extends Omit<
  AriaLabelProps,
  'className'
> {
  className?: string
}

export interface TokenFieldInputProps extends Omit<
  AriaTokenInputProps,
  'children' | 'className'
> {
  className?: string
  /**
   * Overrides how a **token** is drawn. It is called once per token segment and never for text —
   * React Aria renders a text segment as the bare string it is, which is what makes the result one
   * editable sentence rather than a row of boxes. So the sentence's own type and colour belong on
   * `TokenField.Input`, not on a slot.
   */
  children?: AriaTokenInputProps['children']
}

export interface TokenFieldTokenProps extends Omit<
  AriaTokenProps,
  'className'
> {
  className?: string
}

export interface TokenFieldHintProps extends Omit<AriaTextProps, 'className'> {
  className?: string
}

/** The field's name. Use it as `TokenField.Label`. */
export function TokenFieldLabel({ className, ...props }: TokenFieldLabelProps) {
  return (
    <AriaLabel
      className={[LABEL, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/** One token. Use it as `TokenField.Token` — only inside `TokenField.Input`, which is what tells it which segment it is. */
export function TokenFieldToken({ className, ...props }: TokenFieldTokenProps) {
  return (
    <AriaToken
      data-slot="token"
      className={[TOKEN_CHIP, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

/**
 * The typing surface, and the place the tokens are drawn. Use it as `TokenField.Input`.
 *
 * **It is a `role="textbox"` container, not an `<input>`.** There is no `placeholder` — a text field's
 * placeholder belongs to its input element, and this element has none to put it on. What stands in for
 * it is the *first text segment*: React Aria keeps one at the end of the value, so passing
 * `new TokenFieldValue(['#ops on call'])` and styling that leading text faintly is how this component
 * shows its invitation.
 */
export function TokenFieldInput({
  className,
  children,
  ...props
}: TokenFieldInputProps) {
  return (
    <AriaTokenInput
      data-slot="token-input"
      className={[INPUT, 'flex flex-wrap items-center gap-1.5 py-2', className]
        .filter(Boolean)
        .join(' ')}
      {...props}
    >
      {children ??
        ((segment) => (
          <AriaToken
            key={`t-${String(segment.value)}-${segment.text}`}
            data-slot="token"
            className={TOKEN_CHIP}
          >
            {segment.text}
          </AriaToken>
        ))}
    </AriaTokenInput>
  )
}

/** A line under the field. Use it as `TokenField.Hint`. */
export function TokenFieldHint({ className, ...props }: TokenFieldHintProps) {
  return (
    <AriaText
      slot="description"
      className={[HINT, className].filter(Boolean).join(' ')}
      {...props}
    />
  )
}

function TokenFieldRoot({ className, children, ...props }: TokenFieldProps) {
  return (
    <AriaTokenField
      className={[FIELD, 'w-full', className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaTokenField>
  )
}

/**
 * Text with tokens inside it — a notification target, an alert's audience.
 *
 * ```tsx
 * <TokenField defaultValue={new TokenFieldValue([{ type: 'token', text: '#ops', value: 'ops' }, ' and '])}>
 *   <TokenField.Label>Notify</TokenField.Label>
 *   <TokenField.Input />
 *   <TokenField.Hint>Backspace removes the token before the caret.</TokenField.Hint>
 * </TokenField>
 * ```
 *
 * **A token is part of the value, not a chip beside it.** That is the distinction from `TagGroup`,
 * which is a set of chips you edit as a set; here the tokens are words inside a sentence the user is
 * writing, in order, and React Aria puts the caret between them. `TagGroup` answers "which labels
 * apply"; this answers "who hears about it, and what do you want to say".
 *
 * **React Aria owns the keyboard, and that is most of the component.** Backspace at a token's edge
 * removes it; arrow keys step through tokens as single characters; typing filters the tokens that
 * remain. None of that is implemented here.
 *
 * **There is no `placeholder`.** A text field's placeholder belongs to its input element, and this
 * container has none — see `TokenField.Input` for what stands in for it.
 *
 * **There is no invalid state, and so no `TokenField.Error` — and the reason is now measured
 * rather than assumed.** React Aria 1.22's token field takes `isDisabled`, `isReadOnly` and
 * `allowsNewlines` and no validation props at all. Building the slot anyway was tried, and the
 * two halves of a field's error both fail on this control:
 *
 * - **The message cannot render.** `FieldError` renders through `Text slot="errorMessage"`, and a
 *   field registers that slot in its own text context. A token field registers only
 *   `description`, so a `FieldError` inside one throws `Invalid slot "errorMessage". Valid slot
 *   names are "description".` — measured. (It can be made to render by registering the slot by
 *   hand, which is fighting the framework for a slot this control was never given.)
 *   That alone would be a reason to say "not yet" rather than "no".
 * - **The control cannot be described by it**, which is the part that settles it. `TokenInput`
 *   runs its props through `filterDOMProps`, which keeps `data-*` attributes but not
 *   `aria-invalid` or `aria-describedby` — those it keeps only when a component asks for them by
 *   name, and the token input asks for neither. React Aria then merges its own `tokenFieldProps`
 *   in last, so a reference to the message is not merely dropped, it is replaced by the hint's.
 *   A message a screen reader cannot reach, under a control that cannot say it is invalid, is
 *   exactly the "renders and is wired to nothing" this note used to predict.
 *
 * So a token field is not one of the fields this library can make invalid, and the honest thing is
 * to say so rather than to ship a red message that only sighted users can see.
 */
export const TokenField = Object.assign(TokenFieldRoot, {
  Label: TokenFieldLabel,
  Input: TokenFieldInput,
  Token: TokenFieldToken,
  Hint: TokenFieldHint,
})

import {
  Separator as AriaSeparator,
  Toolbar as AriaToolbar,
} from 'react-aria-components'
import type {
  SeparatorProps as AriaSeparatorProps,
  ToolbarProps as AriaToolbarProps,
} from 'react-aria-components'

import type { ReactNode } from 'react'

export interface ToolbarProps extends Omit<
  AriaToolbarProps,
  'className' | 'children' | 'orientation'
> {
  /** Which way the arrow keys walk. Defaults to horizontal. */
  orientation?: AriaToolbarProps['orientation']

  className?: string
  children?: ReactNode
}

/** A run of controls that go together. */
export interface ToolbarGroupProps {
  className?: string
  children?: ReactNode
}

export interface ToolbarSeparatorProps extends Omit<
  AriaSeparatorProps,
  'className' | 'orientation'
> {
  className?: string
}

/**
 * A bar of controls, walked with the arrow keys.
 *
 * ```tsx
 * <Toolbar aria-label="Range">
 *   <Toolbar.Group>
 *     <ToggleButton defaultSelected>1h</ToggleButton>
 *     <ToggleButton>24h</ToggleButton>
 *     <ToggleButton>7d</ToggleButton>
 *   </Toolbar.Group>
 *   <Toolbar.Separator />
 *   <ToggleButton variant="ghost">Live</ToggleButton>
 * </Toolbar>
 * ```
 *
 * **The sheet has no toolbar class**, so the surface is an invention: the sheet's hairline, its square
 * corners, and its own controls inside it.
 *
 * What React Aria adds is the part a `div` with `display: flex` does not: the toolbar is **one tab
 * stop** and the arrow keys walk it, so a bar of eight controls does not cost a keyboard user eight
 * presses of Tab. Home and End reach the ends, and a disabled control is skipped over rather than
 * trapping them. That is the whole reason to use this rather than a flex row.
 *
 * `orientation` turns it, and the arrow keys turn with it — a vertical toolbar is walked up and down.
 */
function ToolbarRoot({ className, children, ...props }: ToolbarProps) {
  return (
    <AriaToolbar
      data-slot="toolbar"
      orientation="horizontal"
      className={[
        'flex items-center gap-1',
        'border border-border-strong bg-card rounded-md p-1',
        'data-[orientation=vertical]:w-fit data-[orientation=vertical]:flex-col',
        'data-[orientation=vertical]:items-stretch',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
      {...props}
    >
      {children}
    </AriaToolbar>
  )
}

/**
 * A run of controls that belongs together. Use it as `Toolbar.Group` — a segmented control is a group
 * of toggle buttons inside a toolbar, which is exactly what it is.
 *
 * Exported as `ToolbarGroup` only so tooling can resolve it; consume the compound form `Toolbar.Group`.
 */
export function ToolbarGroup({ className, children }: ToolbarGroupProps) {
  return (
    // No border of its own: the controls inside carry their own edges, and a box around a box reads as
    // a nesting mistake rather than as grouping.
    <div
      role="group"
      className={['flex items-center', className].filter(Boolean).join(' ')}
    >
      {children}
    </div>
  )
}

/**
 * The sheet's hairline, standing up between two runs of controls. Use it as `Toolbar.Separator`.
 *
 * Exported as `ToolbarSeparator` only so tooling can resolve it; consume the compound form
 * `Toolbar.Separator`.
 */
export function ToolbarSeparator({
  className,
  ...props
}: ToolbarSeparatorProps) {
  return (
    <AriaSeparator
      orientation="vertical"
      className={[
        'mx-1 h-5 w-px shrink-0 self-center bg-border',
        'data-[orientation=vertical]:h-5',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
      {...props}
    />
  )
}

/**
 * The compound export. A plain `function` decorated with `Object.assign` leaves TypeScript unaware of
 * the slots, which is why the root is named apart and only the decorated const is exported.
 */
export const Toolbar = Object.assign(ToolbarRoot, {
  Group: ToolbarGroup,
  Separator: ToolbarSeparator,
})

import {
  Tooltip as AriaTooltip,
  TooltipTrigger as AriaTooltipTrigger,
} from 'react-aria-components'
import type {
  TooltipProps as AriaTooltipProps,
  TooltipTriggerComponentProps as AriaTooltipTriggerProps,
} from 'react-aria-components'
import { OverlayArrow } from '../OverlayArrow/OverlayArrow'

/**
 * The sheet's `.ds-tip`: its own panel rather than a themed bubble, at 94% so a hairline of
 * whatever is behind it shows through, with a 45% border over the top. `w-max` because a tooltip
 * is as wide as its text and never the width of the thing it describes.
 */
const CONTENT = [
  'flex w-max max-w-72 flex-col gap-[5px]',
  // The control step, not the surface one: 1.4 × the base on a box this short is most of its height.
  'border border-border-strong bg-card/94 rounded-md px-3.5 pt-2.5 pb-3',
].join(' ')

/** The sheet's `.ds-tip__title`: 12px, letterspaced, in the accent — not uppercase, as the sheet's labels are. */
const TITLE = 'text-[12px] tracking-[0.1em] text-primary'

/** The sheet's `.ds-tip__sub`: 14px, with the sheet's negative tracking. */
const TEXT = 'text-[14px] tracking-[-0.5px] text-foreground'

export interface TooltipProps extends Omit<
  AriaTooltipTriggerProps,
  'children' | 'className'
> {
  /**
   * How long to wait before showing, on hover only. React Aria's default is a deliberately
   * unhurried 1500ms, which is the ARIA guidance for a hover — a tooltip that appears the instant
   * a pointer crosses it flickers over every icon in a toolbar. Set `0` when the tooltip is the
   * only way to know what something is.
   */
  delay?: AriaTooltipTriggerProps['delay']
  /** Opens on focus as well as hover. On by default, because a keyboard user has no pointer. */
  isOpen?: AriaTooltipTriggerProps['isOpen']
  defaultOpen?: AriaTooltipTriggerProps['defaultOpen']
  onOpenChange?: AriaTooltipTriggerProps['onOpenChange']
  /**
   * The thing being described, then a `Tooltip.Content`. There is no `className`: like
   * `Select.AutoComplete`, this renders no element of its own — it is the wiring between the two
   * — so there is nothing to style. Put the class on the thing being described.
   */
  children?: React.ReactNode
}

export interface TooltipContentProps extends Omit<
  AriaTooltipProps,
  'children' | 'className'
> {
  className?: string
  /** A `Tooltip.Title` and a `Tooltip.Text`, in that order. */
  children?: React.ReactNode
}

export interface TooltipTitleProps extends React.HTMLAttributes<HTMLSpanElement> {
  children?: React.ReactNode
}

export interface TooltipTextProps extends React.HTMLAttributes<HTMLSpanElement> {
  children?: React.ReactNode
}

/**
 * The tooltip's surface. Use it as `Tooltip.Content`, as the second child of a `Tooltip`.
 *
 * Exported as `TooltipContent` only so tooling can resolve it; consume the compound form
 * `Tooltip.Content`.
 */
export function TooltipContent({
  className,
  children,
  offset = 10,
  ...props
}: TooltipContentProps) {
  return (
    <AriaTooltip
      offset={offset}
      className={[CONTENT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaTooltip>
  )
}

/**
 * What the tooltip is about. Use it as `Tooltip.Title`, above a `Tooltip.Text`.
 *
 * Exported as `TooltipTitle` only so tooling can resolve it; consume the compound form
 * `Tooltip.Title`.
 */
export function TooltipTitle({
  className,
  children,
  ...props
}: TooltipTitleProps) {
  return (
    <span
      data-slot="title"
      className={[TITLE, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </span>
  )
}

/**
 * The detail under it. Use it as `Tooltip.Text`.
 *
 * Exported as `TooltipText` only so tooling can resolve it; consume the compound form
 * `Tooltip.Text`.
 */
export function TooltipText({
  className,
  children,
  ...props
}: TooltipTextProps) {
  return (
    <span
      data-slot="text"
      className={[TEXT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </span>
  )
}

/**
 * Styled element. Not exported — `Tooltip` below is the public symbol, and docgen reads the JSDoc
 * from the *exported* declaration, not this one.
 */
function TooltipRoot({ children, ...props }: TooltipProps) {
  return <AriaTooltipTrigger {...props}>{children}</AriaTooltipTrigger>
}

/**
 * The sheet's `.ds-tip` — a short description attached to the thing it describes. It carries the
 * thing itself as its first child and the tooltip as its second, so the two cannot be wired to
 * different things:
 *
 * ```tsx
 * <Tooltip delay={0}>
 *   <Button>Restart</Button>
 *   <Tooltip.Content>
 *     <Tooltip.Title>Restart</Tooltip.Title>
 *     <Tooltip.Text>Runs the check again from the top.</Tooltip.Text>
 *   </Tooltip.Content>
 * </Tooltip>
 * ```
 *
 * **A tooltip is not a label and not a place to put anything necessary.** It opens on hover and
 * on focus, cannot be scrolled or selected, and is gone the moment the pointer moves — so anything
 * a user must be able to read twice, copy, or click belongs somewhere else. Its own content is
 * described, not interactive.
 *
 * React Aria gives it the parts a hand-rolled tooltip always gets wrong: it opens on **focus** as
 * well as hover, so a keyboard user can reach it; it waits before opening on hover, so a pointer
 * crossing a toolbar does not flicker through every tooltip in it; it stays open while the pointer
 * moves onto the tooltip itself; and it is wired as `aria-describedby` rather than replacing the
 * element's name.
 *
 * `Tooltip.Title` is the sheet's `.ds-tip__title` — 12px, letterspaced, in the accent — and is
 * deliberately **not** uppercase, unlike the sheet's other small text. A tooltip's heading is
 * read at a glance while the pointer is resting, not scanned in a column.
 */

/**
 * The marker pointing back at the trigger. Use it as `Tooltip.Arrow`.
 *
 * **Opt-in, and nothing here uses it.** The design language's panels are flat and anchored by proximity;
 * see `OverlayArrow` for why the shape exists at all and what it is made of.
 */
export function TooltipArrow({ className }: { className?: string }) {
  return <OverlayArrow className={className} />
}

export const Tooltip = Object.assign(TooltipRoot, {
  Arrow: TooltipArrow,
  Content: TooltipContent,
  Title: TooltipTitle,
  Text: TooltipText,
})

import {
  Button as AriaButton,
  Tree as AriaTree,
  TreeHeader as AriaTreeHeader,
  TreeItem as AriaTreeItem,
  TreeItemContent as AriaTreeItemContent,
  TreeSection as AriaTreeSection,
  TreeLoadMoreItem as AriaTreeLoadMoreItem,
} from 'react-aria-components'
import { LOAD_MORE, LoadMoreSpinner } from '../loadMore'
import type {
  SectionProps as AriaSectionProps,
  TreeItemContentProps as AriaTreeItemContentProps,
  TreeItemProps as AriaTreeItemProps,
  TreeProps as AriaTreeProps,
  TreeLoadMoreItemProps as AriaTreeLoadMoreItemProps,
} from 'react-aria-components'

import type { ComponentProps, ReactNode } from 'react'

import {
  NAV_CHEVRON,
  NAV_GUTTER,
  NAV_HEADER,
  NAV_ITEM,
  NAV_LABEL,
  NAV_LEVEL,
  NavCaret,
} from '../Nav/Nav'

/**
 * Join a class list, dropping anything falsy.
 *
 * React Aria types `className` as `string | ((renderProps) => string)`, and the root passes it straight
 * through, so this has to accept the function form as well as the resolved string.
 */
type ClassPart = string | false | undefined | ((...args: never[]) => string)
const join = (...parts: ClassPart[]) =>
  parts.filter((part): part is string => typeof part === 'string').join(' ')

export interface TreeProps<T extends object = object> extends Omit<
  AriaTreeProps<T>,
  | 'children'
  | 'className'
  | 'selectionMode'
  | 'selectedKeys'
  | 'defaultSelectedKeys'
  | 'onSelectionChange'
  | 'expandedKeys'
  | 'defaultExpandedKeys'
  | 'onExpandedChange'
  | 'disabledKeys'
> {
  /** `none`, `single` or `multiple`. A tree with no selection mode is a tree of labels. */
  selectionMode?: AriaTreeProps<T>['selectionMode']
  /** The chosen rows, by each item's `id`. */
  selectedKeys?: AriaTreeProps<T>['selectedKeys']
  /** What starts chosen. */
  defaultSelectedKeys?: AriaTreeProps<T>['defaultSelectedKeys']
  /** Called with the new set of keys. */
  onSelectionChange?: AriaTreeProps<T>['onSelectionChange']
  /** Which rows are open, by `id`. */
  expandedKeys?: AriaTreeProps<T>['expandedKeys']
  /** What starts open. Without an `id` on the item this matches nothing and the tree renders collapsed, silently. */
  defaultExpandedKeys?: AriaTreeProps<T>['defaultExpandedKeys']
  /** Called as rows open and close. */
  onExpandedChange?: AriaTreeProps<T>['onExpandedChange']
  /** Rows that cannot be chosen. */
  disabledKeys?: AriaTreeProps<T>['disabledKeys']

  className?: AriaTreeProps<T>['className']
  children?: ReactNode
}

export interface TreeItemProps<T extends object = object> extends Omit<
  AriaTreeItemProps<T>,
  'className' | 'children'
> {
  className?: AriaTreeItemProps<T>['className']
  children?: ReactNode
}

export interface TreeLabelProps extends Omit<
  AriaTreeItemContentProps,
  'className' | 'children'
> {
  children?: ReactNode
}

export interface TreeSectionProps<T extends object = object> extends Omit<
  AriaSectionProps<T>,
  'className' | 'children'
> {
  className?: string
  children?: ReactNode
}

/**
 * `TreeHeader` reports a `<header>` element while React Aria's exported `HeaderProps` describes a
 * `<div>`, so the two disagree by one DOM generic. Taking the component's own props avoids the
 * argument entirely, and is what the header's type actually is.
 */
export type TreeHeaderProps = Omit<
  ComponentProps<typeof AriaTreeHeader>,
  'className'
> & {
  className?: string
}

/**
 * What an item says, plus its disclosure chevron.
 *
 * **The chevron is a button with `slot="chevron"`, drawn from the render props.** React Aria hands over
 * `hasChildItems` and `isExpanded` and renders nothing for either — so a parent row has no affordance
 * at all until this draws one, and a leaf correctly gets none. It is the same `NAV_CHEVRON` and the same
 * `NavCaret` a sidebar row uses, so a tree and a nav disclose in one direction.
 *
 * It carries **no `className`**, because `TreeItemContent` takes none — the row's own class list is on
 * the row, and everything here is inside it.
 *
 * Exported as `TreeLabel` only so tooling can resolve it; consume the compound form `Tree.Label`.
 */
export function TreeLabel({ children, ...props }: TreeLabelProps) {
  return (
    <AriaTreeItemContent {...props}>
      {({ hasChildItems, isExpanded }) => (
        <>
          {hasChildItems ? (
            <AriaButton slot="chevron" className={NAV_CHEVRON}>
              <NavCaret expanded={isExpanded} />
            </AriaButton>
          ) : (
            // An empty box where a chevron would be, so a leaf's label starts on the same left edge as
            // its siblings'. A tree and a sidebar read as columns of edges, and an indentation that
            // depends on whether a row happens to have children says nothing true about the hierarchy.
            <span aria-hidden="true" className={NAV_GUTTER} />
          )}
          <span className={NAV_LABEL}>{children}</span>
        </>
      )}
    </AriaTreeItemContent>
  )
}

/**
 * One node. Use it as `Tree.Item` — it nests inside itself for depth.
 *
 * Exported as `TreeItem` only so tooling can resolve it; consume the compound form `Tree.Item`.
 */
export function TreeItem<T extends object = object>({
  className,
  textValue,
  children,
  ...props
}: TreeItemProps<T>) {
  return (
    <AriaTreeItem
      textValue={textValue}
      // **The indent is the level**, read from the render props rather than tracked by hand, so a
      // subtree of any depth lines up without the consumer counting anything.
      className={(renderProps) =>
        join(
          NAV_ITEM,
          // **`NAV_ITEM` marks `data-[current]`, and this is not that.** A navigation tree says where
          // you are with `isCurrent`; a selection tree says which row you chose. Sharing the row
          // vocabulary without this line left the chosen row with no accent at all — brighter only
          // through the browser's own selection handling. The accent is the same teal, because "the one
          // you are looking at" is the same idea in both.
          'data-[selected]:text-primary',
          NAV_LEVEL[renderProps.level] ?? NAV_LEVEL[3],
          typeof className === 'function' ? className(renderProps) : className,
        )
      }
      {...props}
    >
      {children}
    </AriaTreeItem>
  )
}

/**
 * A group of nodes. Use it as `Tree.Section`.
 *
 * Exported as `TreeSection` only so tooling can resolve it; consume the compound form `Tree.Section`.
 */
export function TreeSection<T extends object = object>({
  className,
  children,
  ...props
}: TreeSectionProps<T>) {
  return (
    <AriaTreeSection className={join(className)} {...props}>
      {children}
    </AriaTreeSection>
  )
}

/**
 * The legend above a section. Use it as `Tree.Header`.
 *
 * Exported as `TreeHeader` only so tooling can resolve it; consume the compound form `Tree.Header`.
 */
export function TreeHeader({ className, children, ...props }: TreeHeaderProps) {
  return (
    <AriaTreeHeader className={join(NAV_HEADER, className)} {...props}>
      {children}
    </AriaTreeHeader>
  )
}

/**
 * A hierarchical list of items, expanded and collapsed in place.
 *
 * ```tsx
 * <Tree aria-label="Files" selectionMode="single">
 *   <Tree.Item id="src" textValue="src">
 *     <Tree.Label>src</Tree.Label>
 *     <Tree.Item id="index" textValue="index.ts">
 *       <Tree.Label>index.ts</Tree.Label>
 *     </Tree.Item>
 *   </Tree.Item>
 * </Tree>
 * ```
 *
 * **This is what `Nav` is built on, with the links taken out.** React Aria's `NavigationTree` extends
 * its `Tree`, so the two share one row vocabulary — a label, a level indent and a disclosure chevron,
 * exported from `Nav` and composed here rather than copied, because a tree of files and a tree of links
 * should not drift apart in a sidebar.
 *
 * Reach for this when the hierarchy is **data** — a file explorer, a category tree, an outline — and
 * for `Nav` when it is **a set of destinations** and the current one is a URL. The difference is what a
 * click does: this selects, that navigates.
 *
 * **It renders a treegrid, not a list.** `role="row"` and `role="gridcell"` are the shape React Aria
 * builds, so a story queries those and a screen reader announces depth and position for free.
 *
 * **Expansion is the item's own state**, keyed by each item's `id` — the same key `selectedKeys` and
 * `disabledKeys` speak in. Without an `id`, `defaultExpandedKeys` matches nothing and the tree renders
 * fully collapsed, with no error and no warning.
 */
function TreeRoot<T extends object = object>({
  className,
  children,
  ...props
}: TreeProps<T>) {
  return (
    <AriaTree
      data-slot="tree"
      className={join('flex flex-col p-1 outline-none select-none', className)}
      {...props}
    >
      {children}
    </AriaTree>
  )
}

/**
 * The compound export. A plain `function` decorated with `Object.assign` leaves TypeScript unaware of
 * the slots, which is why the root is named apart and only the decorated const is exported.
 */

/**
 * The row that asks for the next page. Use it as `Tree.LoadMore`, last inside `Tree`.
 *
 * It watches the scroll position and calls `onLoadMore` when it comes into view.
 *
 * **It only works inside a virtualized collection** — `Virtualizer` supplies the scroll container the
 * sentinel observes. Without one React Aria renders nothing for it at all when idle, so there is no
 * sentinel and no request. `GridList.LoadMore` carries the end-to-end proof; this is the same machinery in
 * another collection.
 *
 * **It draws nothing until `isLoading`**, and the spinner is `motion-safe`.
 */
export function TreeLoadMore({
  className,
  children,
  ...props
}: AriaTreeLoadMoreItemProps) {
  return (
    <AriaTreeLoadMoreItem
      data-slot="tree-load-more"
      className={[LOAD_MORE, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children ?? <LoadMoreSpinner />}
    </AriaTreeLoadMoreItem>
  )
}

export const Tree = Object.assign(TreeRoot, {
  Item: TreeItem,
  Label: TreeLabel,
  Section: TreeSection,
  Header: TreeHeader,
  LoadMore: TreeLoadMore,
})

import { VisuallyHidden as AriaVisuallyHidden } from 'react-aria-components'
import type { VisuallyHiddenProps as AriaVisuallyHiddenProps } from 'react-aria-components'

/**
 * Text for screen readers and nobody else.
 *
 * ```tsx
 * <VisuallyHidden>Checked every 60 seconds</VisuallyHidden>
 * ```
 *
 * **It is not `display: none` and it is not `visibility: hidden`.** Both of those take the text out of the
 * accessibility tree as well as off the screen. This keeps the text in the tree at one pixel with the
 * clip-path technique — which is what `sr-only` is — so a screen reader still reads it and the page does
 * not move.
 *
 * It is here because several components in this repo had written the same `sr-only` span by hand, and a
 * visually hidden thing is easy to get subtly wrong: `width: 1px` without `white-space: nowrap` wraps the
 * text into a column, and a missing `clip-path` leaves it over the content it was hiding behind.
 */
export function VisuallyHidden({
  // **`span`, not React Aria's default `div`.** This component's whole job is to sit inside a sentence —
  // "Uptime <VisuallyHidden>checked every 60 seconds</VisuallyHidden>" — and a `<div>` there is invalid
  // HTML: the browser reports "a `<p>` cannot contain a nested `<div>`", and it forces a block box into
  // the middle of inline text. React Aria defaults to `div` and uses `elementType="span"` itself for its
  // own hidden inputs; the useful default for a design system is the inline one, and a consumer who needs
  // a block can still pass `elementType`.
  elementType = 'span',
  className,
  ...props
}: AriaVisuallyHiddenProps) {
  return (
    <AriaVisuallyHidden
      data-slot="visually-hidden"
      elementType={elementType}
      className={className}
      {...props}
    />
  )
}

import {
  Button as AriaButton,
  CalendarGrid as AriaCalendarGrid,
  CalendarGridBody as AriaCalendarGridBody,
  CalendarGridHeader as AriaCalendarGridHeader,
  CalendarHeaderCell as AriaCalendarHeaderCell,
